from __future__ import annotations
from itertools import combinations
import numpy as np
from scipy import stats

def _levels(v):
    u = list(dict.fromkeys(v))
    try:
        return sorted(u, key=float)
    except (TypeError, ValueError):
        return sorted(u, key=str)

def _cell_means_ss(y, codes, term, nlev):

    def marginal_ss(sub):
        if not sub:
            return 0.0
        keys = np.zeros(len(y), dtype=np.int64)
        for f in sub:
            keys = keys * nlev[f] + codes[f]
        _, inv, cnt = np.unique(keys, return_inverse=True, return_counts=True)
        sums = np.bincount(inv, weights=y)
        means = sums / cnt
        return float((cnt * (means - y.mean()) ** 2).sum())
    ss = 0.0
    for r in range(len(term), 0, -1):
        for sub in combinations(term, r):
            ss += (-1) ** (len(term) - r) * marginal_ss(sub)
    return ss

def balanced_anova(response, factors: dict, terms: list[tuple[str, ...]], random: list[str] | None=None, restricted: bool=False) -> dict:
    random = set(random or [])
    names = list(factors)
    rows = [i for i in range(len(response)) if response[i] is not None and all((factors[f][i] is not None for f in names))]
    y = np.array([float(response[i]) for i in rows])
    N = len(y)
    lev = {f: _levels([factors[f][i] for i in rows]) for f in names}
    nlev = {f: len(lev[f]) for f in names}
    codes = {f: np.array([lev[f].index(factors[f][i]) for i in rows]) for f in names}
    sst = float(((y - y.mean()) ** 2).sum())
    table = []
    for t in terms:
        ss = _cell_means_ss(y, codes, t, nlev)
        df = int(np.prod([nlev[f] - 1 for f in t]))
        table.append({'term': t, 'df': df, 'ss': ss, 'ms': ss / df})
    df_e = N - 1 - sum((r['df'] for r in table))
    ss_e = sst - sum((r['ss'] for r in table))
    error = {'term': ('Error',), 'df': df_e, 'ss': ss_e, 'ms': ss_e / df_e if df_e > 0 else float('nan')}

    def is_random(t):
        return any((f in random for f in t))

    def coef(t):
        return N / float(np.prod([nlev[f] for f in t]))
    ems = {}
    for r in table:
        t = r['term']
        comp = {('Error',): 1.0}
        for u in (x['term'] for x in table):
            if set(t) <= set(u) and u != t and is_random(u):
                extra = set(u) - set(t)
                if restricted and (not all((f in random for f in extra))):
                    continue
                comp[u] = coef(u)
        comp[t] = coef(t)
        ems[t] = comp
    out_rows = []
    ms = {r['term']: r['ms'] for r in table}
    ms['Error',] = error['ms']
    dfs = {r['term']: r['df'] for r in table}
    dfs['Error',] = df_e
    ems['Error',] = {('Error',): 1.0}
    for r in table:
        t = r['term']
        target = {k: v for k, v in ems[t].items() if k != t}
        err = next((u for u, e in ems.items() if u != t and e == target), None)
        if err is not None:
            denom, ddf = (ms[err], dfs[err])
            err_label = err
        else:
            keys = [u for u in ems if u != t]
            comps = sorted({c for u in keys for c in ems[u]}, key=str)
            A = np.array([[ems[u].get(c, 0.0) for u in keys] for c in comps])
            b = np.array([target.get(c, 0.0) for c in comps])
            w = np.linalg.lstsq(A, b, rcond=None)[0]
            denom = float(sum((wi * ms[u] for wi, u in zip(w, keys))))
            ddf = denom ** 2 / sum(((wi * ms[u]) ** 2 / dfs[u] for wi, u in zip(w, keys) if abs(wi) > 1e-12))
            err_label = None
        f = r['ms'] / denom
        out_rows.append({'source': '*'.join(t), 'df': r['df'], 'ss': r['ss'], 'ms': r['ms'], 'f': f, 'p': float(stats.f.sf(f, r['df'], ddf)), 'error_df': ddf, 'error_term': None if err_label is None else '*'.join(err_label)})
    vc = {('Error',): error['ms']}
    for t in sorted((x['term'] for x in table), key=len, reverse=True):
        if not is_random(t):
            continue
        rest = sum((c * vc.get(u, 0.0) for u, c in ems[t].items() if u != t))
        vc[t] = (ms[t] - rest) / ems[t][t]
    s = float(np.sqrt(error['ms'])) if df_e > 0 else None
    r_sq = 1 - ss_e / sst
    r_sq_adj = 1 - ss_e / df_e / (sst / (N - 1)) if df_e > 0 else None
    ems_text = []
    order = [x['term'] for x in table] + [('Error',)]
    for t in order:
        parts = []
        for u in reversed(order):
            if u in ems[t]:
                idx = order.index(u) + 1
                c = ems[t][u]
                if u == t and (not is_random(t)) and (t != ('Error',)):
                    parts.append(f'{c:g} Q[{idx}]' if restricted else f'Q[{idx}]')
                else:
                    parts.append(f'({idx})' if c == 1 else f'{c:g} ({idx})')
        ems_text.append({'source': '*'.join(t), 'ems': ' + '.join(parts), 'variance_component': vc.get(t) if is_random(t) or t == ('Error',) else None})
    return {'factors': {f: [str(v) for v in lev[f]] for f in names}, 'rows': out_rows, 'error': {'df': df_e, 'ss': ss_e, 'ms': error['ms']}, 'total': {'df': N - 1, 'ss': sst}, 's': s, 'r_sq': r_sq, 'r_sq_adj': r_sq_adj, 'ems': ems_text}

def two_way_anova(response, row_factor, col_factor, additive: bool=False) -> dict:
    terms = [('A',), ('B',)] + ([] if additive else [('A', 'B')])
    r = balanced_anova(response, {'A': row_factor, 'B': col_factor}, terms)
    names = {'A': 'row', 'B': 'col'}
    y = np.array([float(v) for v in response if v is not None])
    means = {}
    for key, col in (('row', row_factor), ('col', col_factor)):
        lv = _levels(col)
        means[key] = [{'level': str(l_), 'mean': float(np.mean([float(v) for v, c in zip(response, col) if c == l_]))} for l_ in lv]
    for row in r['rows']:
        row['source'] = {'A': 'row', 'B': 'col', 'A*B': 'interaction'}[row['source']]
    r['means'] = means
    return r

def fully_nested_anova(response, factors: list[list]) -> dict:
    y = np.array([float(v) for v in response], dtype=float)
    N = len(y)
    keys = []
    acc = [''] * N
    for col in factors:
        acc = [a + '|' + str(c) for a, c in zip(acc, col)]
        keys.append(list(acc))
    gm = y.mean()
    rows = []
    prev_means = np.full(N, gm)
    prev_groups = 1
    for i, k in enumerate(keys):
        uniq = list(dict.fromkeys(k))
        idx = np.array([uniq.index(v) for v in k])
        means = np.bincount(idx, weights=y) / np.bincount(idx)
        m = means[idx]
        ss = float(((m - prev_means) ** 2).sum())
        df = len(uniq) - prev_groups
        if df <= 0:
            raise ValueError('Faktörler dıştan içe sıralanmalı (her faktör bir öncekinin içinde yuvalanmalı).')
        rows.append({'level': i + 1, 'df': df, 'ss': ss, 'ms': ss / df, 'n_per': N / len(uniq)})
        prev_means, prev_groups = (m, len(uniq))
    ss_e = float(((y - prev_means) ** 2).sum())
    df_e = N - prev_groups
    rows.append({'level': len(keys) + 1, 'df': df_e, 'ss': ss_e, 'ms': ss_e / df_e, 'n_per': 1.0})
    for i in range(len(rows) - 1):
        f = rows[i]['ms'] / rows[i + 1]['ms']
        rows[i]['f'] = f
        rows[i]['p'] = float(stats.f.sf(f, rows[i]['df'], rows[i + 1]['df']))
    comps = []
    for i in range(len(rows)):
        if i == len(rows) - 1:
            comps.append(rows[i]['ms'])
        else:
            comps.append((rows[i]['ms'] - rows[i + 1]['ms']) / rows[i]['n_per'])
    tot = sum((max(c, 0.0) for c in comps))
    for r, c in zip(rows, comps):
        r['variance_component'] = c
        r['pct_of_total'] = 100 * max(c, 0.0) / tot
        r['stdev'] = float(np.sqrt(max(c, 0.0)))
    return {'rows': rows, 'total': {'df': N - 1, 'ss': float(((y - gm) ** 2).sum())}}

