from __future__ import annotations
from dataclasses import asdict
from typing import Literal
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from .api_spc import _clean
from .basic import hypothesis as H
from .basic.correlation import correlation, covariance, grubbs
from .basic.descriptive import describe
from .basic import nonparametric as NP
from .basic.normality import anderson_darling_test, kolmogorov_smirnov_test, ryan_joiner_test
from .basic.variances import one_variance, two_variances
router = APIRouter(prefix='/api/basic', tags=['Temel İstatistikler'])
Alt = Literal[-1, 0, 1]
Conf = Field(0.95, gt=0, lt=1)

def _guard(fn):
    try:
        return fn()
    except (ValueError, ZeroDivisionError, IndexError) as e:
        raise HTTPException(422, str(e)) from e

class DescribeIn(BaseModel):
    columns: dict[str, list[float | None]]

@router.post('/describe')
def describe_ep(req: DescribeIn) -> dict:
    return _clean({k: asdict(describe(v)) for k, v in req.columns.items()})

class OneSampleIn(BaseModel):
    values: list[float | None]
    test: float | None = None
    sigma: float | None = Field(None, gt=0)
    confidence: float = Conf
    alternative: Alt = 0

@router.post('/one-sample')
def one_sample(req: OneSampleIn) -> dict:
    if req.sigma is not None:
        r = _guard(lambda: H.one_sample_z(req.values, req.sigma, req.test, req.confidence, req.alternative))
    else:
        r = _guard(lambda: H.one_sample_t(req.values, req.test, req.confidence, req.alternative))
    return _clean(asdict(r))

class TwoSampleIn(BaseModel):
    a: list[float | None]
    b: list[float | None]
    test: float = 0.0
    confidence: float = Conf
    alternative: Alt = 0
    pooled: bool = False
    paired: bool = False

@router.post('/two-sample')
def two_sample(req: TwoSampleIn) -> dict:
    if req.paired:
        r = _guard(lambda: H.paired_t(req.a, req.b, req.test, req.confidence, req.alternative))
    else:
        r = _guard(lambda: H.two_sample_t(req.a, req.b, req.test, req.confidence, req.alternative, req.pooled))
    return _clean(asdict(r))

class OneProportionIn(BaseModel):
    trials: int = Field(gt=0)
    events: int = Field(ge=0)
    test: float | None = Field(None, gt=0, lt=1)
    confidence: float = Conf
    alternative: Alt = 0
    method: Literal['exact', 'normal', 'wilson', 'agresti_coull'] = 'exact'
    continuity: bool = False

@router.post('/one-proportion')
def one_proportion(req: OneProportionIn) -> dict:
    if req.events > req.trials:
        raise HTTPException(422, 'Olay sayısı deneme sayısını aşamaz.')
    return _clean(asdict(H.one_proportion(req.trials, req.events, req.test, req.confidence, req.alternative, req.method, req.continuity)))

class TwoProportionsIn(BaseModel):
    trials1: int = Field(gt=0)
    events1: int = Field(ge=0)
    trials2: int = Field(gt=0)
    events2: int = Field(ge=0)
    test: float = 0.0
    confidence: float = Conf
    alternative: Alt = 0
    pooled: bool = False

@router.post('/two-proportions')
def two_proportions(req: TwoProportionsIn) -> dict:
    return _clean(asdict(H.two_proportions(req.trials1, req.events1, req.trials2, req.events2, req.test, req.confidence, req.alternative, req.pooled)))

class OneRateIn(BaseModel):
    n: float = Field(gt=0)
    total: int = Field(ge=0)
    test: float | None = Field(None, gt=0)
    confidence: float = Conf
    alternative: Alt = 0
    method: Literal['exact', 'normal'] = 'exact'
    length: float = Field(1.0, gt=0)

@router.post('/one-rate')
def one_rate(req: OneRateIn) -> dict:
    return _clean(asdict(H.one_poisson_rate(req.n, req.total, req.test, req.confidence, req.alternative, req.method, req.length)))

class TwoRatesIn(BaseModel):
    n1: float = Field(gt=0)
    total1: int = Field(ge=0)
    n2: float = Field(gt=0)
    total2: int = Field(ge=0)
    test: float = 0.0
    confidence: float = Conf
    alternative: Alt = 0
    pooled: bool = False
    length: float = Field(1.0, gt=0)

@router.post('/two-rates')
def two_rates(req: TwoRatesIn) -> dict:
    return _clean(asdict(H.two_poisson_rates(req.n1, req.total1, req.n2, req.total2, req.test, req.confidence, req.alternative, req.pooled, req.length)))

class OneVarianceIn(BaseModel):
    values: list[float | None]
    test_variance: float | None = Field(None, gt=0)
    confidence: float = Conf
    alternative: Alt = 0

@router.post('/one-variance')
def one_variance_ep(req: OneVarianceIn) -> dict:
    return _clean(_guard(lambda: one_variance(req.values, req.test_variance, req.confidence, req.alternative)))

class TwoVariancesIn(BaseModel):
    a: list[float | None]
    b: list[float | None]
    test_ratio: float = Field(1.0, gt=0)
    confidence: float = Conf
    alternative: Alt = 0
    use_f: bool = False

@router.post('/two-variances')
def two_variances_ep(req: TwoVariancesIn) -> dict:
    return _clean(_guard(lambda: two_variances(req.a, req.b, req.test_ratio, req.confidence, req.alternative, req.use_f)))

class CorrelationIn(BaseModel):
    columns: dict[str, list[float | None]]
    method: Literal['pearson', 'spearman'] = 'pearson'
    confidence: float = Conf

@router.post('/correlation')
def correlation_ep(req: CorrelationIn) -> dict:
    if len(req.columns) < 2:
        raise HTTPException(422, 'En az iki sütun gerekir.')
    pairs = _guard(lambda: correlation(req.columns, req.method, req.confidence))
    return _clean({'pairs': [asdict(p) for p in pairs], 'covariance': covariance(req.columns), 'names': list(req.columns)})

class NormalityIn(BaseModel):
    values: list[float | None]
    method: Literal['ad', 'rj', 'ks'] = 'ad'

@router.post('/normality')
def normality(req: NormalityIn) -> dict:
    fn = {'ad': anderson_darling_test, 'rj': ryan_joiner_test, 'ks': kolmogorov_smirnov_test}[req.method]
    return _clean(asdict(_guard(lambda: fn(req.values))))

class OutlierIn(BaseModel):
    values: list[float | None]
    alternative: Alt = 0
    method: Literal['grubbs', 'r10', 'r11', 'r12', 'r20', 'r21', 'r22'] = 'grubbs'

@router.post('/outlier')
def outlier(req: OutlierIn) -> dict:
    if req.method == 'grubbs':
        return _clean(_guard(lambda: grubbs(req.values, req.alternative)))
    from .basic.correlation import dixon
    return _clean(_guard(lambda: dixon(req.values, int(req.method[1]), int(req.method[2]), req.alternative)))

class SignWilcoxonIn(BaseModel):
    values: list[float | None]
    median: float | None = None
    confidence: float = Conf
    alternative: Alt = 0
    method: Literal['sign', 'wilcoxon'] = 'sign'

@router.post('/one-sample-median')
def one_sample_median(req: SignWilcoxonIn) -> dict:
    if req.method == 'sign':
        r = NP.sign_test(req.values, req.median, req.alternative) if req.median is not None else NP.sign_ci(req.values, req.confidence)
    else:
        r = NP.wilcoxon_test(req.values, req.median, req.alternative) if req.median is not None else NP.wilcoxon_ci(req.values, req.confidence)
    return _clean(_guard(lambda: r))

class MannWhitneyIn(BaseModel):
    a: list[float | None]
    b: list[float | None]
    confidence: float = Conf
    alternative: Alt = 0

@router.post('/mann-whitney')
def mann_whitney_ep(req: MannWhitneyIn) -> dict:
    return _clean(_guard(lambda: NP.mann_whitney(req.a, req.b, req.confidence, req.alternative)))

class KSampleIn(BaseModel):
    response: list[float | None]
    factor: list[str | float | None]
    method: Literal['kruskal', 'mood'] = 'kruskal'
    confidence: float = Conf

@router.post('/k-sample-median')
def k_sample(req: KSampleIn) -> dict:
    f = [None if v is None else str(v) for v in req.factor]
    if req.method == 'kruskal':
        return _clean(_guard(lambda: NP.kruskal_wallis(req.response, f)))
    return _clean(_guard(lambda: NP.mood_median(req.response, f, req.confidence)))

class FriedmanIn(BaseModel):
    response: list[float | None]
    treatment: list[str | float | None]
    blocks: list[str | float | None]

@router.post('/friedman')
def friedman_ep(req: FriedmanIn) -> dict:
    return _clean(_guard(lambda: NP.friedman(req.response, [str(v) for v in req.treatment], [str(v) for v in req.blocks])))

class RunsIn(BaseModel):
    values: list[float | None]
    k: float | None = None

@router.post('/runs')
def runs(req: RunsIn) -> dict:
    return _clean(_guard(lambda: NP.runs_test(req.values, req.k)))

class ChiAssocIn(BaseModel):
    rows: list[str | float | None]
    columns: list[str | float | None]

@router.post('/chi-square-association')
def chi_assoc(req: ChiAssocIn) -> dict:
    r = [None if v is None else str(v) for v in req.rows]
    c = [None if v is None else str(v) for v in req.columns]
    return _clean(_guard(lambda: NP.chi_square_association(r, c)))

@router.post('/crosstab-measures')
def crosstab_measures(req: ChiAssocIn) -> dict:
    r = [None if v is None else str(v) for v in req.rows]
    c = [None if v is None else str(v) for v in req.columns]
    return _clean(_guard(lambda: NP.crosstab_measures(r, c)))

class ChiGofIn(BaseModel):
    observed: list[float] | None = None
    names: list[str | float] | None = None
    data: list[str | float | None] | None = None
    proportions: list[float] | None = None
    historical_counts: list[float] | None = None

@router.post('/chi-square-gof')
def chi_gof(req: ChiGofIn) -> dict:
    if req.observed is None and req.data is None:
        raise HTTPException(422, 'Gözlenen sayımlar veya kategorik veri gerekli.')
    data = None if req.data is None else [None if v is None else str(v) for v in req.data]
    return _clean(_guard(lambda: NP.chi_square_gof(req.observed, req.names, data, req.proportions, req.historical_counts)))

class EquivalenceIn(BaseModel):
    kind: Literal['one', 'two', 'paired'] = 'two'
    test: list[float | None]
    reference: list[float | None] | None = None
    target: float | None = None
    lower: float
    upper: float
    alpha: float = Field(0.05, gt=0, lt=0.5)
    equal_variances: bool = True
    extend: bool = True
    ratio: bool = False
    relative: bool = False

@router.post('/equivalence')
def equivalence(req: EquivalenceIn) -> dict:
    from .basic.equivalence import one_sample_tost, paired_tost, two_sample_tost
    if req.lower >= req.upper:
        raise HTTPException(422, 'Alt sınır üst sınırdan küçük olmalı.')
    if req.kind == 'one':
        if req.target is None:
            raise HTTPException(422, 'Hedef değer gerekir.')
        return _clean(_guard(lambda: one_sample_tost(req.test, req.target, req.lower, req.upper, req.alpha, req.extend, req.relative)))
    if req.reference is None:
        raise HTTPException(422, 'Referans örneklem gerekir.')
    if req.kind == 'paired':
        return _clean(_guard(lambda: paired_tost(req.test, req.reference, req.lower, req.upper, req.alpha, req.extend, req.relative)))
    return _clean(_guard(lambda: two_sample_tost(req.test, req.reference, req.lower, req.upper, req.alpha, req.equal_variances, req.extend, req.ratio, req.relative)))

class ProbabilityIn(BaseModel):
    distribution: str
    params: list[float]
    function: Literal['pdf', 'cdf', 'invcdf'] = 'cdf'
    values: list[float]

@router.post('/probability')
def probability(req: ProbabilityIn) -> dict:
    from .probability import cdf, inv_cdf, pdf
    fn = {'pdf': pdf, 'cdf': cdf, 'invcdf': inv_cdf}[req.function]
    try:
        return _clean({'results': fn(req.distribution, req.params, req.values)})
    except (ValueError, IndexError, TypeError) as e:
        raise HTTPException(422, str(e)) from e

class DescTableIn(BaseModel):
    rows: list[str | float | None]
    columns: list[str | float | None] | None = None
    variable: list[float | None] | None = None
    proportion: list[float] | None = None

@router.post('/descriptive-table')
def desc_table(req: DescTableIn) -> dict:
    from .basic.tables import descriptive_table
    prop = tuple(req.proportion) if req.proportion and len(req.proportion) == 2 else None
    rows = [None if v is None else str(v) for v in req.rows]
    cols = None if req.columns is None else [None if v is None else str(v) for v in req.columns]
    return _clean(_guard(lambda: descriptive_table(rows, cols, req.variable, prop)))

class PoissonGofIn(BaseModel):
    values: list[float | None]
    frequencies: list[float | None] | None = None

@router.post('/poisson-gof')
def poisson_gof_endpoint(req: PoissonGofIn) -> dict:
    return _clean(_guard(lambda: NP.poisson_gof(req.values, req.frequencies)))

