from __future__ import annotations
from dataclasses import asdict
from typing import Literal
import numpy as np
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from . import distributions as D
from .api_spc import TestsIn, _clean
from .capability.attribute import binomial_capability, poisson_capability
from .capability.nonnormal import FITTERS, nonnormal_capability
from .spc.attributes import AttributeOptions
router = APIRouter(prefix='/api/capability', tags=['Yetenek'])

def _fit_dict(f: D.Fit) -> dict:
    return {'name': f.name, 'params': f.params, 'ad': f.ad, 'p_value': f.p_value, 'p_text': f.p_text, 'lrt_p': f.lrt_p, 'loglik': f.loglik, 'n_params': f.n_params}

class AttributeCapaIn(BaseModel):
    counts: list[float | None]
    sizes: float | list[float | None] = 1.0
    target: float | None = None
    confidence: float = Field(0.95, gt=0, lt=1)
    tests: TestsIn = TestsIn()

@router.post('/binomial')
def binomial(req: AttributeCapaIn) -> dict:
    try:
        r = binomial_capability(req.counts, req.sizes, req.target, req.confidence, AttributeOptions(tests=req.tests.spec()))
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    out = asdict(r)
    out['chart'] = {'center': r.chart.center_value, 'panel': asdict(r.chart.panel)}
    return _clean(out)

@router.post('/poisson')
def poisson(req: AttributeCapaIn) -> dict:
    try:
        r = poisson_capability(req.counts, req.sizes, req.target, req.confidence, AttributeOptions(tests=req.tests.spec()))
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    out = asdict(r)
