    distribution: Literal[tuple(FITTERS)]
    lsl: float | None = None
    usl: float | None = None
    method: Literal['z', 'iso'] = 'z'

@router.post('/nonnormal')
def nonnormal(req: NonnormalIn) -> dict:
    try:
        r = nonnormal_capability(req.values, req.distribution, req.lsl, req.usl, req.method)
    except (ValueError, FloatingPointError) as e:
        raise HTTPException(422, str(e)) from e
    x = np.array([v for v in req.values if v is not None], dtype=float)
    grid = np.linspace(x.min() - 0.1 * np.ptp(x), x.max() + 0.1 * np.ptp(x), 200)
    pdf = np.gradient(r.fit.cdf(grid), grid)
    return _clean({'n': r.n, 'mean': r.mean, 'fit': _fit_dict(r.fit), 'pp': r.pp, 'ppl': r.ppl, 'ppu': r.ppu, 'ppk': r.ppk, 'ppm_observed': asdict(r.ppm_observed), 'ppm_expected': asdict(r.ppm_expected), 'curve': {'x': grid, 'pdf': pdf}})

