    levels: list[int] | None = None
    array: str | None = None

@router.post('/design')
def other_design(req: OtherDesignIn) -> dict:
    from .doe.designs import general_full_factorial, plackett_burman, taguchi
    try:
        if req.kind == 'plackett_burman':
            m = plackett_burman(req.factors or 0, req.runs or 12)
        elif req.kind == 'general_full':
            m = general_full_factorial(req.levels or [])
        elif req.kind == 'definitive_screening':
            from .doe.screening import definitive_screening
            rows = definitive_screening(req.factors or 0)
            return {'matrix': [r['levels'] for r in rows], 'pt_type': [r['pt_type'] for r in rows], 'runs': len(rows)}
        else:
            m = taguchi(req.array or '', req.factors)
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    return {'matrix': m, 'runs': len(m)}

