    kind: str = Field(pattern='^(simplex_centroid|simplex_lattice|extreme_vertices)$')
    components: int | None = Field(None, ge=2, le=20)
    degree: int = Field(2, ge=1, le=10)
    center: bool = False
    axial: bool = False
    lower: list[float] | None = None
    upper: list[float] | None = None

@router.post('/mixture/create')
def mixture_design(req: MixtureDesignIn) -> dict:
    from .doe.mixture import extreme_vertices, simplex_centroid, simplex_lattice
    try:
        if req.kind == 'simplex_centroid':
            rows = simplex_centroid(req.components or 0, req.axial)
        elif req.kind == 'simplex_lattice':
            rows = simplex_lattice(req.components or 0, req.degree, req.center, req.axial)
        else:
            if not req.lower or not req.upper or len(req.lower) != len(req.upper):
                raise ValueError('Alt ve üst sınırlar aynı uzunlukta verilmeli.')
            rows = extreme_vertices(req.lower, req.upper, min(req.degree, 2), req.center)
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    return {'rows': rows, 'runs': len(rows)}

