    from .api_spc import _clean
    from .doe.mixture import analyze_mixture
    try:
        return _clean(analyze_mixture(req.components, req.response, None if req.terms is None else [tuple(t) for t in req.terms]))
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e

