    name: str = 'Y'
    model: dict
    goal: str = Field(pattern='^(minimize|maximize|target)$')
    lower: float | None = None
    target: float
    upper: float | None = None
    weight: float = Field(1.0, gt=0)
    importance: float = Field(1.0, gt=0)

class OptimizerIn(BaseModel):
    variables: list[dict]
    responses: list[OptimizerResponse]
    mixture_total: float | None = None

@router.post('/optimize')
def response_optimizer(req: OptimizerIn) -> dict:
    from .api_spc import _clean
    from .doe.optimizer import optimize_responses
    for r in req.responses:
        if r.goal in ('maximize', 'target') and r.lower is None or (r.goal in ('minimize', 'target') and r.upper is None):
            raise HTTPException(422, f'{r.name}: hedef için gerekli alt/üst sınır eksik.')
    try:
        return _clean(optimize_responses(req.variables, [r.model_dump() for r in req.responses], req.mixture_total))
    except (ValueError, KeyError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e

