    terms: list[str]
    categorical: list[str] = []
    constant: bool = True
    confidence: float = Field(0.95, gt=0, lt=1)

@router.post('/regression/fit')
def regression_fit(req: RegressionIn) -> dict:
    missing = {p for t in req.terms for p in t.split('*')} | {req.response}
    missing -= set(req.data)
    if missing:
        raise HTTPException(422, f"Sütun bulunamadı: {', '.join(sorted(missing))}")
    try:
        r = fit_regression(req.data, req.response, req.terms, req.categorical, req.constant, req.confidence)
    except (ValueError, ZeroDivisionError, np_linalg_error()) as e:
        raise HTTPException(422, f'Model kurulamadı: {e}') from e
    return _clean(asdict(r))

def np_linalg_error():
    import numpy as np
    return np.linalg.LinAlgError

