from __future__ import annotations
from typing import Literal
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from .api_spc import _clean
from .power import MIN_N, POWER_FUNCS, sample_size, solve_effect
router = APIRouter(prefix='/api/power', tags=['Güç ve Örneklem'])
EFFECT = {'z': ('diff', 1e-09, 1000000.0), 't1': ('diff', 1e-09, 1000000.0), 'paired': ('diff', 1e-09, 1000000.0), 't2': ('diff', 1e-09, 1000000.0), 'p1': ('p', 1e-09, 1 - 1e-09), 'p2': ('p', 1e-09, 1 - 1e-09), 'anova': ('max_diff', 1e-09, 1000000.0), 'var1': ('ratio', 1 + 1e-09, 1000.0), 'var2': ('ratio', 1 + 1e-09, 1000.0), 'rate1': ('rate', 1e-09, 1000000.0), 'rate2': ('rate', 1e-09, 1000000.0)}

class PowerIn(BaseModel):
    test: Literal['z', 't1', 'paired', 't2', 'p1', 'p2', 'anova', 'var1', 'var2', 'rate1', 'rate2']
    params: dict = {}
    alpha: float = Field(0.05, gt=0, lt=1)
    alternative: Literal[-1, 0, 1] = 0
    sample_sizes: list[float] = []
    effects: list[float] = []
    powers: list[float] = []

@router.post('')
def power(req: PowerIn) -> dict:
    fn = POWER_FUNCS[req.test]
    key, lo, hi = EFFECT[req.test]
    base = dict(req.params, alpha=req.alpha)
    if req.test != 'anova':
        base['alt'] = req.alternative
    rows = []
    try:
        filled = sum((bool(x) for x in (req.sample_sizes, req.effects, req.powers)))
        if filled != 2:
            raise ValueError('Örneklem büyüklüğü, fark ve güçten tam olarak ikisini girin.')
        if req.sample_sizes and req.effects:
            for e in req.effects:
                for n in req.sample_sizes:
                    rows.append({key: e, 'n': n, 'power': fn(**{key: e, 'n': n}, **base)})
        elif req.effects and req.powers:
            for e in req.effects:
                for p in req.powers:
                    n, act = sample_size(fn, p, MIN_N.get(req.test, 1), **{key: e}, **base)
                    rows.append({key: e, 'n': n, 'target_power': p, 'power': act})
        else:
            for n in req.sample_sizes:
                for p in req.powers:
                    if req.test in ('p1', 'p2', 'rate1', 'rate2'):
                        ref = req.params.get('p0', req.params.get('p_base', req.params.get('rate0', req.params.get('rate_base'))))
                        a, b = (ref + 1e-09, hi) if req.alternative >= 0 else (lo, ref - 1e-09)
                    else:
                        a, b = (lo, hi)
                    rows.append({'n': n, 'power': p, key: solve_effect(fn, p, key, a, b, n=n, **base)})
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e
    return _clean({'test': req.test, 'effect_name': key, 'rows': rows})

class DesignPowerIn(BaseModel):
    kind: Literal['two_level', 'plackett_burman', 'general']
    corner_points: int | None = Field(None, ge=4)
    factors: int | None = Field(None, ge=1)
    runs: int | None = Field(None, ge=4)
    levels: list[int] | None = None
    reps: list[int] = Field([1], min_length=1)
    effect: float = Field(..., gt=0)
    sigma: float = Field(..., gt=0)
    center_points: int = Field(0, ge=0)
    alpha: float = Field(0.05, gt=0, lt=1)
    omit: int = Field(0, ge=0)
    fit_center: bool = False
    blocks: int = Field(1, ge=1)
    fit_blocks: bool = False
    order: int = Field(2, ge=1)

@router.post('/design')
def design_power(req: DesignPowerIn) -> dict:
    from . import power as P
    out = []
    try:
        for r in req.reps:
            if req.kind == 'two_level':
                res = P.power_two_level(req.corner_points or 0, r, req.effect, req.sigma, req.center_points, req.alpha, req.omit, req.fit_center, req.blocks, req.fit_blocks)
            elif req.kind == 'plackett_burman':
                res = P.power_plackett_burman(req.factors or 0, req.runs or 0, r, req.effect, req.sigma, req.center_points, req.alpha, req.omit, req.fit_center)
            else:
                if not req.levels:
                    raise ValueError('Düzey sayıları gerekli.')
                res = P.power_general_factorial(req.levels, r, req.effect, req.sigma, req.order, req.alpha)
            out.append({'reps': r, **res})
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    return {'rows': out}

class TostPowerIn(BaseModel):
    design: Literal['one', 'two', 'paired', 'crossover']
    sizes: list[int] = Field(..., min_length=1)
    difference: float
    lower: float | None = None
    upper: float | None = None
    sigma: float = Field(..., gt=0)
    alpha: float = Field(0.05, gt=0, lt=0.5)

@router.post('/tost')
def tost_power(req: TostPowerIn) -> dict:
    from . import power as P
    if req.lower is None and req.upper is None:
        raise HTTPException(422, 'En az bir eşdeğerlik sınırı gerekli.')
    try:
        return {'rows': [{'n': n, 'power': P.power_tost(req.design, n, req.difference, req.lower, req.upper, req.sigma, req.alpha)} for n in req.sizes]}
    except ValueError as e:
        raise HTTPException(422, str(e)) from e

class EstimationIn(BaseModel):
    parameter: Literal['mean', 'proportion', 'rate', 'stdev']
    margins: list[float] = Field(..., min_length=1)
