    if need is None:
        raise HTTPException(422, 'Planlama değeri gerekli.')
    try:
        return {'rows': [{'margin': m, 'n': P.sample_size_estimation(req.parameter, m, req.confidence, req.sides, req.sigma, req.sigma_known, req.proportion, req.rate, req.length)} for m in req.margins]}
    except ValueError as e:
        raise HTTPException(422, str(e)) from e

