from __future__ import annotations
from typing import Literal
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from .api_spc import _clean
from .predictive.cart import fit_cart
from .predictive.common import prepare
from .predictive.discover import discover
from .predictive.ensemble import fit_forest, fit_treenet
from .predictive.mars import fit_mars
router = APIRouter(prefix='/api/predictive', tags=['Tahmine Dayalı Analitik'])

class Predictor(BaseModel):
    name: str
    values: list[str | float | None]
    categorical: bool = False

class PredIn(BaseModel):
    response: list[str | float | None]
    task: Literal['class', 'reg']
    predictors: list[Predictor] = Field(min_length=1)
    event: str | None = None
    validation: Literal['kfold', 'test', 'none'] = 'kfold'
    k: int = Field(10, ge=2, le=20)
    test_frac: float = Field(0.3, gt=0.05, lt=0.9)
    seed: int = Field(1, ge=0)
    criterion: Literal['gini', 'entropy'] = 'gini'
    min_split: int = Field(10, ge=2)
    min_leaf: int = Field(3, ge=1)
    max_depth: int | None = Field(None, ge=1)
    select: Literal['1se', 'min'] = '1se'
    n_trees: int = Field(300, ge=10, le=2000)
    mtry: int | None = Field(None, ge=1)
    learning_rate: float | None = Field(None, gt=0, le=1)
    max_leaves: int = Field(6, ge=2, le=64)
    subsample: float = Field(0.5, gt=0.05, le=1)
    max_terms: int = Field(30, ge=3, le=100)
    degree: int = Field(1, ge=1, le=3)

def _data(req: PredIn):
    if len(req.response) > 50000:
        raise HTTPException(422, 'En çok 50 000 satır.')
    return prepare(req.response, [p.model_dump() for p in req.predictors], req.task, req.event)

def _run(fn):
    try:
        return _clean(fn())
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e

@router.post('/cart')
def cart(req: PredIn) -> dict:
    return _run(lambda: fit_cart(_data(req), crit=req.criterion, min_split=req.min_split, min_leaf=req.min_leaf, max_depth=req.max_depth, validation=req.validation, k=req.k, test_frac=req.test_frac, seed=req.seed, select=req.select))

@router.post('/forest')
def forest(req: PredIn) -> dict:
    return _run(lambda: fit_forest(_data(req), n_trees=req.n_trees, mtry=req.mtry, seed=req.seed))

@router.post('/treenet')
def treenet(req: PredIn) -> dict:
    return _run(lambda: fit_treenet(_data(req), n_trees=req.n_trees, lr=req.learning_rate, leaves=req.max_leaves, min_leaf=req.min_leaf, subsample=req.subsample, validation=req.validation, k=min(req.k, 10), test_frac=req.test_frac, seed=req.seed))

@router.post('/mars')
def mars(req: PredIn) -> dict:
    return _run(lambda: fit_mars(_data(req), max_terms=req.max_terms, degree=req.degree, validation=req.validation, k=min(req.k, 10), test_frac=req.test_frac, seed=req.seed))

@router.post('/discover')
def discover_ep(req: PredIn) -> dict:
    return _run(lambda: discover(_data(req), k=min(req.k, 10), seed=req.seed, n_trees=min(req.n_trees, 300)))

