class AcceptanceIn(BaseModel):
    kind: Literal['attributes', 'variables'] = 'attributes'
    aql: float = Field(gt=0)
    rql: float = Field(gt=0)
    alpha: float = Field(0.05, gt=0, lt=1)
    beta: float = Field(0.1, gt=0, lt=1)
    lot: int | None = Field(None, ge=1)
    units: Literal['percent', 'proportion', 'ppm'] = 'percent'
    defects: bool = False
    hypergeometric: bool = False
    sigma_known: bool = False
    n: int | None = None
    c: float | None = None

@router.post('/acceptance-sampling')
def acceptance(req: AcceptanceIn) -> dict:
    if req.rql <= req.aql:
        raise HTTPException(422, 'RQL, AQL değerinden büyük olmalı.')
    try:
        if req.kind == 'attributes':
            p = attribute_plan(req.aql, req.rql, req.alpha, req.beta, req.lot, req.units, req.defects, req.hypergeometric, req.n, None if req.c is None else int(req.c))
        else:
            p = variables_plan(req.aql, req.rql, req.alpha, req.beta, req.lot, req.units, req.sigma_known, req.n, req.c)
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e
    return _clean(asdict(p))

