from __future__ import annotations
from dataclasses import asdict
from typing import Literal
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from .api_spc import _clean
from .reliability.distribution import kaplan_meier, parametric_analysis
router = APIRouter(prefix='/api/reliability', tags=['Güvenilirlik'])

class DistributionIn(BaseModel):
    times: list[float]
    censor: list[str | float | None] | None = None
    censor_value: str | float = 0
    distribution: Literal['weibull', 'exponential', 'lognormal', 'loglogistic', 'normal', 'logistic', 'sev'] = 'weibull'
    method: Literal['mle', 'lsxy'] = 'mle'
    confidence: float = Field(0.95, gt=0, lt=1)
    percents: list[float] | None = None
    survival_times: list[float] | None = None

def _censor(req):
    if req.censor is None:
        return (None, 0)
    vals = [None if v is None else str(v) for v in req.censor]
    return (vals, str(req.censor_value))

@router.post('/parametric')
def parametric(req: DistributionIn) -> dict:
    if any((t <= 0 for t in req.times)) and req.distribution in ('weibull', 'exponential', 'lognormal', 'loglogistic'):
        raise HTTPException(422, 'Bu dağılım için zamanlar pozitif olmalı.')
    c, cv = _censor(req)
    try:
        r = parametric_analysis(req.times, c, cv, req.distribution, req.confidence, req.percents, req.survival_times, req.method)
    except (ValueError, ZeroDivisionError, OverflowError) as e:
        raise HTTPException(422, str(e)) from e
    out = asdict(r)
    out['correlation'] = r.correlation
    return _clean(out)

@router.post('/kaplan-meier')
def km(req: DistributionIn) -> dict:
    c, cv = _censor(req)
    return _clean(kaplan_meier(req.times, c, cv, req.confidence))

