class ArbitraryIn(BaseModel):
    start: list[float | None]
    end: list[float | None]
    freq: list[float] | None = None
    distribution: Literal['weibull', 'exponential', 'lognormal', 'loglogistic', 'normal', 'logistic', 'sev'] = 'weibull'
    confidence: float = Field(0.95, gt=0, lt=1)
    percents: list[float] | None = None
    survival_times: list[float] | None = None

@router.post('/parametric-arbitrary')
def parametric_arbitrary(req: ArbitraryIn) -> dict:
    if len(req.start) != len(req.end) or (req.freq is not None and len(req.freq) != len(req.start)):
        raise HTTPException(422, 'Başlangıç, bitiş ve frekans sütunları aynı uzunlukta olmalı.')
    for a, b in zip(req.start, req.end):
        if a is None and b is None:
            raise HTTPException(422, 'Bir satırda başlangıç ve bitiş birlikte eksik olamaz.')
        if a is not None and b is not None and (a > b):
            raise HTTPException(422, 'Başlangıç bitişten büyük olamaz.')
    try:
        r = parametric_analysis(None, None, 0, req.distribution, req.confidence, req.percents, req.survival_times, start=req.start, end=req.end, freq=req.freq)
    except (ValueError, ZeroDivisionError, OverflowError, np_linalg_error()) as e:
        raise HTTPException(422, str(e)) from e
    return _clean(asdict(r))

