from __future__ import annotations
import math
from dataclasses import asdict
from typing import Literal
import numpy as np
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from .sigma import SigmaError, WithinMethod
from .spc import TestSpec
from .spc import attributes as attr
from .spc import multivariate as mv
from .spc import special, time_weighted as tw
from .spc import variables as var
router = APIRouter(prefix='/api/spc', tags=['SPC'])

def _clean(obj):
    if isinstance(obj, float):
        return obj if math.isfinite(obj) else None
    if isinstance(obj, (np.floating,)):
        return _clean(float(obj))
    if isinstance(obj, np.ndarray):
        return _clean(obj.tolist())
    if isinstance(obj, dict):
        return {str(k): _clean(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_clean(v) for v in obj]
    return obj

def _panels(panels) -> list[dict]:
    return [asdict(p) for p in panels]

class TestsIn(BaseModel):
    tests: list[int] = Field(default_factory=lambda: [1])
    k: dict[int, float] | None = None

    def spec(self) -> TestSpec:
        return TestSpec(tuple(self.tests), self.k)
Method = Literal['pooled', 'rbar', 'sbar', 'avg_mr', 'median_mr', 'sqrt_mssd']

class VariablesIn(BaseModel):
    chart: Literal['xbar_r', 'xbar_s', 'xbar', 'r', 's', 'i_mr', 'i', 'mr', 'between_within']
    values: list[float | None]
    subgroup: int | list[str | int | float] = 1
    sigma_method: Method | None = None
    unbiased: bool = True
    mr_span: int = Field(2, ge=2, le=100)
    k_sigma: float = Field(3.0, gt=0)
    historical_mean: float | None = None
    historical_sigma: float | None = Field(None, gt=0)
    tests: TestsIn = TestsIn()

@router.post('/variables')
def variables_chart(req: VariablesIn) -> dict:
    opts = var.ChartOptions(sigma_method=WithinMethod(req.sigma_method) if req.sigma_method else None, unbiased=req.unbiased, mr_span=req.mr_span, k_sigma=req.k_sigma, historical_mean=req.historical_mean, historical_sigma=req.historical_sigma, tests=req.tests.spec())
    fn = {'xbar_r': var.xbar_r_chart, 'xbar_s': var.xbar_s_chart, 'xbar': var.xbar_chart, 'r': var.r_chart, 's': var.s_chart, 'i_mr': var.i_mr_chart, 'i': var.i_chart, 'mr': var.mr_chart, 'between_within': var.between_within_chart}[req.chart]
    try:
        individual = req.chart in ('i_mr', 'i', 'mr')
        r = fn(req.values, opts) if individual else fn(req.values, req.subgroup, opts)
    except (ValueError, SigmaError) as e:
        raise HTTPException(422, str(e)) from e
    if req.chart == 'between_within':
        est = {'mean': r.mean, 'sigma_means': r.sigma_means, 'sigma_between': r.sigma_between, 'sigma_within': r.sigma_within, 'sigma_total': r.sigma_total}
    else:
        est = {'mean': r.mean, 'sigma': r.sigma.value, 'sigma_method': str(r.sigma.method), 'subgroup_sizes': r.subgroup_sizes}
    return _clean({'chart': req.chart, 'panels': _panels(r.panels), 'estimates': est})

class AttributesIn(BaseModel):
    chart: Literal['p', 'np', 'c', 'u', 'laney_p', 'laney_u']
    counts: list[float | None]
    sizes: float | list[float | None] | None = None
    k_sigma: float = Field(3.0, gt=0)
    historical: float | None = None
    tests: TestsIn = TestsIn()

@router.post('/attributes')
def attributes_chart(req: AttributesIn) -> dict:
    opts = attr.AttributeOptions(k_sigma=req.k_sigma, historical=req.historical, tests=req.tests.spec())
    try:
        if req.chart == 'c':
            r = attr.c_chart(req.counts, opts)
        else:
            if req.sizes is None:
                raise ValueError('bu kart için alt grup boyutu gerekli')
            fn = {'p': attr.p_chart, 'np': attr.np_chart, 'u': attr.u_chart, 'laney_p': attr.laney_p_chart, 'laney_u': attr.laney_u_chart}[req.chart]
            r = fn(req.counts, req.sizes, opts)
    except ValueError as e:
        raise HTTPException(422, str(e)) from e
    return _clean({'chart': req.chart, 'panels': _panels([r.panel]), 'estimates': {'center': r.center_value, 'sigma_z': r.sigma_z}})

class TimeWeightedIn(BaseModel):
    chart: Literal['ewma', 'ma', 'cusum']
    values: list[float | None]
    subgroup: int | list[str | int | float] = 1
    weight: float = Field(0.2, gt=0, le=1)
    span: int = Field(3, ge=2)
    k_sigma: float = Field(3.0, gt=0)
    target: float = 0.0
    h: float = Field(4.0, gt=0)
    k: float = Field(0.5, ge=0)
    fir: float | None = None
    historical_mean: float | None = None
    historical_sigma: float | None = Field(None, gt=0)

@router.post('/time-weighted')
def time_weighted_chart(req: TimeWeightedIn) -> dict:
    try:
        if req.chart == 'cusum':
            r = tw.cusum_chart(req.values, req.subgroup, tw.CusumOptions(target=req.target, h=req.h, k=req.k, fir=req.fir, historical_sigma=req.historical_sigma))
            n = len(r.upper)
            panels = [{'name': 'CUSUM+', 'points': r.upper, 'center': [0.0] * n, 'lcl': r.lcl, 'ucl': r.ucl, 'tests': {}}, {'name': 'CUSUM−', 'points': r.lower, 'center': [0.0] * n, 'lcl': r.lcl, 'ucl': r.ucl, 'tests': {}}]
            est = {'mean': r.mean, 'sigma': r.sigma.value, 'signals': r.signals}
        else:
            opts = tw.TimeWeightedOptions(weight=req.weight, span=req.span, k_sigma=req.k_sigma, historical_mean=req.historical_mean, historical_sigma=req.historical_sigma)
            fn = tw.ewma_chart if req.chart == 'ewma' else tw.moving_average_chart
            r = fn(req.values, req.subgroup, opts)
            panels = _panels([r.panel])
            est = {'mean': r.mean, 'sigma': r.sigma.value}
    except (ValueError, SigmaError) as e:
        raise HTTPException(422, str(e)) from e
    return _clean({'chart': req.chart, 'panels': panels, 'estimates': est})

class RareIn(BaseModel):
    chart: Literal['g', 't']
    values: list[float]
    tests: TestsIn = TestsIn(tests=[1, 2])

@router.post('/rare-event')
def rare_event_chart(req: RareIn) -> dict:
    fn = special.g_chart if req.chart == 'g' else special.t_chart
    r = fn(req.values, req.tests.spec())
    return _clean({'chart': req.chart, 'panels': _panels([r.panel]), 'estimates': r.parameters})

class ZoneIn(BaseModel):
    values: list[float | None]
    subgroup: int | list[str | int | float]
    weights: tuple[int, int, int, int] = (0, 2, 4, 8)

@router.post('/zone')
def zone(req: ZoneIn) -> dict:
    r = special.zone_chart(req.values, req.subgroup, req.weights)
    return _clean({'chart': 'zone', 'panels': _panels([r.panel]), 'estimates': {'mean': r.mean, 'sigma': r.sigma, 'scores': r.scores}})

class ZmrIn(BaseModel):
    values: list[float]
    parts: list[str | int | float]
    tests: TestsIn = TestsIn()

@router.post('/z-mr')
def z_mr(req: ZmrIn) -> dict:
    r = special.z_mr_chart(req.values, req.parts, req.tests.spec())
    return _clean({'chart': 'z_mr', 'panels': _panels(r.panels), 'estimates': {}})

class MultivariateIn(BaseModel):
    chart: Literal['t2', 'gv', 'mewma']
    data: list[list[float]] = Field(..., description='Satırlar: gözlemler, sütunlar: değişkenler')
    subgroup: int = Field(1, ge=1)
    weight: float = Field(0.1, gt=0, le=1)
    arl: float = Field(200.0, gt=1)

@router.post('/multivariate')
def multivariate_chart(req: MultivariateIn) -> dict:
    try:
        if req.chart == 't2':
            r = mv.t2_chart(req.data, req.subgroup)
        elif req.chart == 'gv':
            if req.subgroup < 2:
                raise ValueError('genelleştirilmiş varyans kartı alt grup boyutu ≥ 2 ister')
            r = mv.generalized_variance_chart(req.data, req.subgroup)
        else:
            r = mv.mewma_chart(req.data, req.subgroup, req.weight, req.arl)
    except (ValueError, np.linalg.LinAlgError) as e:
        raise HTTPException(422, str(e)) from e
    return _clean({'chart': req.chart, 'panels': _panels([r.panel]), 'estimates': {'means': r.means, 'covariance': r.covariance, **r.extra}})

class BoxCoxIn(BaseModel):
    data: list[float | None]
    subgroup_size: int = Field(1, ge=1)
    confidence: float = Field(95.0, gt=0, lt=100)

@router.post('/boxcox')
def boxcox(req: BoxCoxIn) -> dict:
    from .distributions import boxcox_analysis
    try:
        return _clean(boxcox_analysis(req.data, req.subgroup_size, confidence=req.confidence))
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e

