from __future__ import annotations
from typing import Literal
from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field
from . import timeseries as TS
from .api_spc import _clean
router = APIRouter(prefix='/api/timeseries', tags=['Zaman Serileri'])

class TSIn(BaseModel):
    values: list[float | None]
    method: Literal['trend', 'moving_average', 'ses', 'des', 'decomposition', 'acf', 'pacf', 'arima', 'winters']
    model: Literal['linear', 'quadratic', 'growth'] = 'linear'
    length: int = Field(3, ge=1)
    alpha: float = Field(0.2, gt=0, le=2)
    gamma: float = Field(0.2, gt=0, le=1)
    delta: float = Field(0.2, gt=0, le=1)
    period: int = Field(12, ge=2)
    multiplicative: bool = True
    with_trend: bool = True
    lags: int | None = Field(None, ge=1)
    forecasts: int = Field(0, ge=0)
    order: list[int] = Field([0, 0, 0])
    seasonal: list[int] = Field([0, 0, 0])
    constant: bool | None = None

@router.post('')
def timeseries(req: TSIn) -> dict:
    try:
        if req.method == 'trend':
            r = TS.trend_analysis(req.values, req.model, req.forecasts)
        elif req.method == 'moving_average':
            r = TS.moving_average(req.values, req.length, req.forecasts)
        elif req.method == 'ses':
            r = TS.single_exp_smoothing(req.values, req.alpha, forecasts=req.forecasts)
        elif req.method == 'des':
            r = TS.double_exp_smoothing(req.values, req.alpha, req.gamma, req.forecasts)
        elif req.method == 'decomposition':
            r = TS.decomposition(req.values, req.period, req.multiplicative, req.with_trend, req.forecasts)
        elif req.method == 'winters':
            r = TS.winters(req.values, req.period, req.alpha, req.gamma, req.delta, req.multiplicative, req.forecasts)
        elif req.method == 'arima':
            p, d, q = req.order
            P, D, Q_ = req.seasonal
            r = TS.arima(req.values, p, d, q, P, D, Q_, req.period, req.constant, req.forecasts)
        elif req.method == 'acf':
            r = TS.acf(req.values, req.lags)
        else:
            r = TS.pacf(req.values, req.lags)
    except (ValueError, ZeroDivisionError) as e:
        raise HTTPException(422, str(e)) from e
    return _clean(r)

