from __future__ import annotations
import math
from dataclasses import dataclass
import numpy as np
from scipy import optimize, stats

@dataclass
class TestResult:
    estimate: float
    ci: tuple[float | None, float | None]
    statistic: float | None = None
    df: float | None = None
    p_value: float | None = None
    extra: dict | None = None

def _clean(v):
    return np.array([x for x in v if x is not None and np.isfinite(x)], dtype=float)

def _interval(est, se, conf, alt, q):
    if alt == 0:
        h = q(1 - (1 - conf) / 2) * se
        return (est - h, est + h)
    h = q(conf) * se
    return (est - h, None) if alt == 1 else (None, est + h)

def _p_from(stat, alt, cdf, sf):
    if alt == 0:
        return float(min(1.0, 2 * min(cdf(stat), sf(stat))))
    return float(sf(stat) if alt == 1 else cdf(stat))

def one_sample_z(values, sigma: float, test: float | None=None, conf: float=0.95, alt: int=0) -> TestResult:
    x = _clean(values)
    n, m = (len(x), float(x.mean()))
    se = sigma / math.sqrt(n)
    ci = _interval(m, se, conf, alt, stats.norm.ppf)
    r = TestResult(m, ci, extra={'n': n, 'stdev': float(x.std(ddof=1)), 'se_mean': se})
    if test is not None:
        z = (m - test) / se
        r.statistic, r.p_value = (z, _p_from(z, alt, stats.norm.cdf, stats.norm.sf))
    return r

def one_sample_t(values, test: float | None=None, conf: float=0.95, alt: int=0) -> TestResult:
    x = _clean(values)
    n, m, s = (len(x), float(x.mean()), float(x.std(ddof=1)))
    se, df = (s / math.sqrt(n), n - 1)
    ci = _interval(m, se, conf, alt, lambda p: stats.t.ppf(p, df))
    r = TestResult(m, ci, df=df, extra={'n': n, 'stdev': s, 'se_mean': se})
    if test is not None:
        t = (m - test) / se
        r.statistic, r.p_value = (t, _p_from(t, alt, lambda v: stats.t.cdf(v, df), lambda v: stats.t.sf(v, df)))
    return r

def two_sample_t(a, b, test: float=0.0, conf: float=0.95, alt: int=0, pooled: bool=False) -> TestResult:
    x, y = (_clean(a), _clean(b))
    n1, n2 = (len(x), len(y))
    v1, v2 = (x.var(ddof=1), y.var(ddof=1))
    d = float(x.mean() - y.mean())
    if pooled:
        df = n1 + n2 - 2
        sp = math.sqrt(((n1 - 1) * v1 + (n2 - 1) * v2) / df)
        se = sp * math.sqrt(1 / n1 + 1 / n2)
    else:
        a1, a2 = (v1 / n1, v2 / n2)
        se = math.sqrt(a1 + a2)
        df = math.floor((a1 + a2) ** 2 / (a1 * a1 / (n1 - 1) + a2 * a2 / (n2 - 1)))
        sp = None
    ci = _interval(d, se, conf, alt, lambda p: stats.t.ppf(p, df))
    t = (d - test) / se
    return TestResult(d, ci, t, df, _p_from(t, alt, lambda v: stats.t.cdf(v, df), lambda v: stats.t.sf(v, df)), {'pooled_stdev': sp, 'n': (n1, n2), 'means': (float(x.mean()), float(y.mean())), 'stdevs': (math.sqrt(v1), math.sqrt(v2))})

def paired_t(a, b, test: float=0.0, conf: float=0.95, alt: int=0) -> TestResult:
    pairs = [(u, v) for u, v in zip(a, b) if u is not None and v is not None and np.isfinite(u) and np.isfinite(v)]
    return one_sample_t([u - v for u, v in pairs], test, conf, alt)

def _blaker_acceptability(cdf, sf, x: int, support_hi: int) -> float:
    lo, hi = (cdf(x), sf(x - 1))
    tol = 1 - 1e-10
    if lo <= hi:
        ys = np.arange(x + 1, support_hi + 1)
        tails = sf(ys - 1)
        ok = tails[tails < lo * tol]
        return float(min(1.0, lo + (ok.max() if ok.size else 0.0)))
    ys = np.arange(0, x)
    tails = cdf(ys)
    ok = tails[tails < hi * tol]
    return float(min(1.0, hi + (ok.max() if ok.size else 0.0)))

def _blaker_p(n: int, x: int, p: float) -> float:
    if p <= 0:
        return 1.0 if x == 0 else 0.0
    if p >= 1:
        return 1.0 if x == n else 0.0
    b = stats.binom(n, p)
    return _blaker_acceptability(b.cdf, b.sf, x, n)

def _indicator_edge(f, inside: float, outside: float, iters: int=60) -> float:
    for _ in range(iters):
        mid = (inside + outside) / 2
        if f(mid):
            inside = mid
        else:
            outside = mid
    return (inside + outside) / 2

def _blaker_ci(n: int, x: int, conf: float) -> tuple[float, float]:
    alpha = 1 - conf
    inside = lambda p: _blaker_p(n, x, p) > alpha
    ph = x / n
    grid = np.linspace(0, 1, 2001)
    acc = np.array([inside(p) for p in grid])
    lo = 0.0 if x == 0 else None
    hi = 1.0 if x == n else None
    if lo is None:
        idx = np.nonzero(acc & (grid <= ph))[0]
        i = idx.min()
        lo = _indicator_edge(inside, grid[i], grid[i - 1]) if i > 0 else 0.0
    if hi is None:
        idx = np.nonzero(acc & (grid >= ph))[0]
        i = idx.max()
        hi = _indicator_edge(inside, grid[i], grid[i + 1]) if i < len(grid) - 1 else 1.0
    return (lo, hi)

def one_proportion(n: int, x: int, test: float | None=None, conf: float=0.95, alt: int=0, method: str='exact', continuity: bool=False) -> TestResult:
    ph = x / n
    z2 = stats.norm.ppf(1 - (1 - conf) / 2) if alt == 0 else stats.norm.ppf(conf)
    r = TestResult(ph, (None, None), extra={'n': n, 'events': x, 'method': method})
    if method == 'exact':
        if alt == 0:
            r.ci = _blaker_ci(n, x, conf)
        elif alt == 1:
            r.ci = (0.0 if x == 0 else float(stats.beta.ppf(1 - conf, x, n - x + 1)), None)
        else:
            r.ci = (None, 1.0 if x == n else float(stats.beta.ppf(conf, x + 1, n - x)))
        if test is not None:
            b = stats.binom(n, test)
            r.p_value = _blaker_p(n, x, test) if alt == 0 else float(b.sf(x - 1) if alt == 1 else b.cdf(x))
        return r
    if method == 'normal':
        se = math.sqrt(ph * (1 - ph) / n)
        r.ci = _interval(ph, se, conf, alt, stats.norm.ppf)
    elif method == 'wilson':
        r.ci = _wilson(n, x, z2, alt, continuity)
    elif method == 'agresti_coull':
        r.ci = _agresti_coull(n, x, z2, alt)
    if test is None:
        return r
    se0 = math.sqrt(test * (1 - test) / n)
    if method == 'agresti_coull':

        def edge(z, upper):
            nt = n + z * z
            pt = (x + z * z / 2) / nt
            h = z * math.sqrt(pt * (1 - pt) / nt)
            return (pt + h if upper else pt - h) - test
        if alt == 0:
            upper = test >= ph
            z = optimize.brentq(lambda z: edge(z, upper), 0.0, 60.0) if edge(0.0, upper) * edge(60.0, upper) < 0 else 0.0
            r.p_value = float(min(1.0, 2 * stats.norm.sf(z)))
        else:
            z = optimize.brentq(lambda z: edge(z, alt == -1), -60.0, 60.0)
            r.p_value = float(stats.norm.sf(z))
        return r
    if method == 'wilson' and continuity:
        cc = 0.5 / n
        z_lo = (ph - test + cc) / se0
        z_hi = (ph - test - cc) / se0
        z = (ph - test) / se0
        r.statistic = z
        if alt == 0:
            zz = max(abs(ph - test) - cc, 0.0) / se0
            r.p_value = float(min(1.0, 2 * stats.norm.sf(zz)))
        else:
            r.p_value = float(stats.norm.sf(z_hi) if alt == 1 else stats.norm.cdf(z_lo))
        return r
    z = (ph - test) / se0
    r.statistic, r.p_value = (z, _p_from(z, alt, stats.norm.cdf, stats.norm.sf))
    return r

def _wilson(n, x, z, alt, continuity):
    ph = x / n
    if not continuity:
        c = (ph + z * z / (2 * n)) / (1 + z * z / n)
        h = z * math.sqrt(ph * (1 - ph) / n + z * z / (4 * n * n)) / (1 + z * z / n)
        lo, hi = (c - h, c + h)
    else:
        q = 1 - ph
        den = 2 * (n + z * z)
        lo = 0.0 if x == 0 else (2 * n * ph + z * z - 1 - z * math.sqrt(z * z - 2 - 1 / n + 4 * ph * (n * q + 1))) / den
        hi = 1.0 if x == n else (2 * n * ph + z * z + 1 + z * math.sqrt(z * z + 2 - 1 / n + 4 * ph * (n * q - 1))) / den
    lo, hi = (max(lo, 0.0), min(hi, 1.0))
    return (lo, hi) if alt == 0 else (lo, None) if alt == 1 else (None, hi)

def _agresti_coull(n, x, z, alt):
    nt = n + z * z
    pt = (x + z * z / 2) / nt
    h = z * math.sqrt(pt * (1 - pt) / nt)
    lo, hi = (max(pt - h, 0.0), min(pt + h, 1.0))
    return (lo, hi) if alt == 0 else (lo, None) if alt == 1 else (None, hi)

def two_proportions(n1: int, x1: int, n2: int, x2: int, test: float=0.0, conf: float=0.95, alt: int=0, pooled: bool=False) -> TestResult:
    p1, p2 = (x1 / n1, x2 / n2)
    d = p1 - p2
    se = math.sqrt(p1 * (1 - p1) / n1 + p2 * (1 - p2) / n2)
    ci = _interval(d, se, conf, alt, stats.norm.ppf)
    if pooled:
        pp = (x1 + x2) / (n1 + n2)
        se_t = math.sqrt(pp * (1 - pp) * (1 / n1 + 1 / n2))
    else:
        pp, se_t = (None, se)
    z = (d - test) / se_t
    p = _p_from(z, alt, stats.norm.cdf, stats.norm.sf)
    fisher = None
    if test == 0:
        tbl = [[x1, n1 - x1], [x2, n2 - x2]]
        fisher = float(stats.fisher_exact(tbl, alternative={0: 'two-sided', 1: 'greater', -1: 'less'}[alt]).pvalue)
    return TestResult(d, ci, z, None, p, {'p1': p1, 'p2': p2, 'pooled_p': pp, 'fisher_p': fisher})

def _poisson_lr(x, mu):
    return (x * math.log(x / mu) if x > 0 else 0.0) - (x - mu)

def one_poisson_rate(n: float, total: int, test: float | None=None, conf: float=0.95, alt: int=0, method: str='exact', length: float=1.0) -> TestResult:
    expo = n * length
    rate = total / expo
    r = TestResult(rate, (None, None), extra={'n': n, 'total': total, 'method': method})
    a = 1 - conf
    if method == 'exact':
        lo = None if total == 0 else stats.chi2.ppf(a / 2 if alt == 0 else a, 2 * total) / (2 * expo)
        hi = stats.chi2.ppf(1 - a / 2 if alt == 0 else conf, 2 * total + 2) / (2 * expo)
        r.ci = (lo, hi) if alt == 0 else (lo if lo is not None else 0.0, None) if alt == 1 else (None, hi)
        if test is not None:
            mu = test * expo
            d = stats.poisson(mu)
            if alt == 1:
                r.p_value = float(d.sf(total - 1))
            elif alt == -1:
                r.p_value = float(d.cdf(total))
            else:
                lr = _poisson_lr(total, mu) * (1 - 1e-12)
                hi_y = int(max(total, mu) + 20 * math.sqrt(mu) + 50)
                ys = np.arange(0, hi_y + 1)
                lrs = np.array([_poisson_lr(y, mu) for y in ys])
                r.p_value = float(min(1.0, d.pmf(ys[lrs >= lr]).sum() + (d.sf(hi_y) if _poisson_lr(hi_y + 1, mu) >= lr else 0)))
        return r
    se = math.sqrt(rate / expo)
    r.ci = _interval(rate, se, conf, alt, stats.norm.ppf)
    if test is not None:
        z = (rate - test) / math.sqrt(test / expo)
        r.statistic, r.p_value = (z, _p_from(z, alt, stats.norm.cdf, stats.norm.sf))
    return r

def two_poisson_rates(n1: float, t1: int, n2: float, t2: int, test: float=0.0, conf: float=0.95, alt: int=0, pooled: bool=False, length: float=1.0) -> TestResult:
    e1, e2 = (n1 * length, n2 * length)
    r1, r2 = (t1 / e1, t2 / e2)
    d = r1 - r2
    se = math.sqrt(r1 / e1 + r2 / e2)
    ci = _interval(d, se, conf, alt, stats.norm.ppf)
    if pooled:
        rp = (t1 + t2) / (e1 + e2)
        se_t = math.sqrt(rp * (1 / e1 + 1 / e2))
    else:
        se_t = se
    z = (d - test) / se_t
    p = _p_from(z, alt, stats.norm.cdf, stats.norm.sf)
    exact = None
    if test == 0:
        b = stats.binom(t1 + t2, e1 / (e1 + e2))
        lo, hi = (float(b.cdf(t1)), float(b.sf(t1 - 1)))
        exact = min(1.0, 2 * min(lo, hi)) if alt == 0 else hi if alt == 1 else lo
    return TestResult(d, ci, z, None, p, {'rates': (r1, r2), 'exact_p': exact})

