from __future__ import annotations
import math
from dataclasses import dataclass
import numpy as np
from scipy import stats
from ..distributions import anderson_darling, normal_ad_pvalue
from .hypothesis import _clean

@dataclass
class NormalityResult:
    method: str
    n: int
    mean: float
    stdev: float
    statistic: float
    p_value: float | None
    p_text: str

def _fmt(p: float) -> str:
    return f'{p:.3f}'

def anderson_darling_test(values) -> NormalityResult:
    x = _clean(values)
    n, m, s = (len(x), float(x.mean()), float(x.std(ddof=1)))
    a2 = anderson_darling(x, lambda v: stats.norm.cdf(v, m, s))
    p = normal_ad_pvalue(a2, n)
    return NormalityResult('AD', n, m, s, a2, p, '<0.005' if p < 0.005 else _fmt(p))

def _rj_critical(n: int) -> tuple[float, float, float]:
    r = math.sqrt(n)
    c10 = 1.0071 - 0.1371 / r - 0.3682 / n + 0.778 / n ** 2
    c05 = 1.0063 - 0.1288 / r - 0.6118 / n + 1.3505 / n ** 2
    c01 = 0.9963 - 0.0211 / r - 1.4106 / n + 3.1791 / n ** 2
    return (c10, c05, c01)

def ryan_joiner_test(values) -> NormalityResult:
    x = np.sort(_clean(values))
    n = len(x)
    i = np.arange(1, n + 1)
    b = stats.norm.ppf((i - 0.375) / (n + 0.25))
    for v in np.unique(x):
        tie = x == v
        if tie.sum() > 1:
            b[tie] = b[tie].mean()
    rj = float(np.corrcoef(x, b)[0, 1])
    c10, c05, c01 = _rj_critical(n)
    if rj >= c10:
        p, txt = (None, '>0.100')
    elif rj <= c01:
        p, txt = (None, '<0.010')
    elif rj >= c05:
        p = 0.05 + (rj - c05) / (c10 - c05) * 0.05
        txt = _fmt(p)
    else:
        p = 0.01 + (rj - c01) / (c05 - c01) * 0.04
        txt = _fmt(p)
    return NormalityResult('RJ', n, float(x.mean()), float(x.std(ddof=1)), rj, p, txt)
_KS_POINTS = ((0.775, 0.15), (0.819, 0.1), (0.895, 0.05), (0.995, 0.025), (1.035, 0.01))

def ks_normal_pvalue(d: float, n: int) -> tuple[float | None, str]:
    dm = d * (math.sqrt(n) - 0.01 + 0.85 / math.sqrt(n))
    if dm < _KS_POINTS[0][0]:
        return (None, '>0.150')
    if dm > _KS_POINTS[-1][0]:
        return (None, '<0.010')
    for (c1, a1), (c2, a2) in zip(_KS_POINTS, _KS_POINTS[1:]):
        if dm < c2 or c2 == _KS_POINTS[-1][0]:
            p = a2 + (c2 - dm) / (c2 - c1) * (a1 - a2)
            return (p, _fmt(p))
    raise AssertionError

def kolmogorov_smirnov_test(values) -> NormalityResult:
    x = np.sort(_clean(values))
    n = len(x)
    m, s = (float(x.mean()), float(x.std(ddof=1)))
    f = stats.norm.cdf(x, m, s)
    i = np.arange(1, n + 1)
    d = float(max((i / n - f).max(), (f - (i - 1) / n).max()))
    p, txt = ks_normal_pvalue(d, n)
    return NormalityResult('KS', n, m, s, d, p, txt)

