from __future__ import annotations
import numpy as np

def _levels(v):
    u = list(dict.fromkeys(v))
    try:
        return sorted(u, key=float)
    except (TypeError, ValueError):
        return sorted(u, key=str)

def _cell(values, prop):
    x = np.array([v for v in values if v is not None], dtype=float)
    n = len(x)
    out = {'n': n, 'nmissing': len(values) - n, 'mean': float(x.mean()) if n else None, 'median': float(np.median(x)) if n else None, 'stdev': float(x.std(ddof=1)) if n > 1 else None, 'minimum': float(x.min()) if n else None, 'maximum': float(x.max()) if n else None, 'sum': float(x.sum()) if n else None}
    if prop is not None and n:
        lo, hi = prop
        out['proportion'] = float(((x >= lo) & (x <= hi)).mean())
    return out

def descriptive_table(rows, columns=None, variable=None, proportion: tuple[float, float] | None=None) -> dict:
    n_all = len(rows)
    keep = [i for i in range(n_all) if rows[i] is not None and (columns is None or columns[i] is not None)]
    r = [str(rows[i]) for i in keep]
    c = [str(columns[i]) for i in keep] if columns is not None else ['All'] * len(keep)
    y = [None if variable is None or variable[i] is None else float(variable[i]) for i in keep]
    rl = [str(v) for v in _levels(r)] + ['All']
    cl = [str(v) for v in _levels(c)] + ['All'] if columns is not None else ['All']
    N = len(keep)
    cells = {}
    for a in rl:
        for b in cl:
            idx = [i for i in range(N) if (a == 'All' or r[i] == a) and (b == 'All' or c[i] == b)]
            cnt = len(idx)
            row_tot = sum((1 for i in range(N) if a == 'All' or r[i] == a))
            col_tot = sum((1 for i in range(N) if b == 'All' or c[i] == b))
            cell = {'count': cnt, 'row_percent': 100 * cnt / row_tot if row_tot else None, 'col_percent': 100 * cnt / col_tot if col_tot else None, 'total_percent': 100 * cnt / N if N else None}
            if variable is not None:
                cell.update(_cell([y[i] for i in idx], proportion))
            cells[f'{a}|{b}'] = cell
    return {'row_levels': rl, 'col_levels': cl, 'cells': cells, 'n': N}

