from __future__ import annotations
import math
import numpy as np
from scipy import optimize, stats
from .hypothesis import _clean, _p_from

def _frac_trimmed_mean(x: np.ndarray, prop: float) -> float:
    s = np.sort(x)
    n = len(s)
    g = prop * n
    k = int(math.floor(g))
    f = g - k
    w = np.ones(n)
    if k:
        w[:k] = 0
        w[n - k:] = 0
    w[k] -= f
    if n - 1 - k != k:
        w[n - 1 - k] -= f
    return float((w * s).sum() / w.sum())

def _parts(x: np.ndarray):
    n = len(x)
    m = _frac_trimmed_mean(x, 1 / (2 * math.sqrt(n - 4))) if n > 5 else float(x.mean())
    return (n, float(x.var(ddof=1)), float(((x - m) ** 4).sum()), float(((x - x.mean()) ** 2).sum()))

def bonett_variance_ci(x: np.ndarray, z: float) -> tuple[float, float]:
    n, s2, m4, ss = _parts(x)
    g4 = n * m4 / ss ** 2
    c = n / (n - z)
    se = c * math.sqrt((g4 - (n - 3) / n) / (n - 1))
    return (math.exp(math.log(c * s2) - z * se), math.exp(math.log(c * s2) + z * se))

def _sided(lo, hi, alt):
    return (lo, hi) if alt == 0 else (lo, None) if alt == 1 else (None, hi)

def _z(conf, alt):
    return stats.norm.ppf(1 - (1 - conf) / 2) if alt == 0 else stats.norm.ppf(conf)

def _chisq_ci(n, s2, conf, alt):
    a = 1 - conf
    if alt == 0:
        return ((n - 1) * s2 / stats.chi2.ppf(1 - a / 2, n - 1), (n - 1) * s2 / stats.chi2.ppf(a / 2, n - 1))
    return _sided((n - 1) * s2 / stats.chi2.ppf(conf, n - 1), (n - 1) * s2 / stats.chi2.ppf(a, n - 1), alt)

def _p_by_alpha(g) -> float:
    try:
        return float(optimize.brentq(g, 1e-14, 1 - 1e-14, xtol=1e-14))
    except ValueError:
        return 1.0 if g(0.5) < 0 else 0.0

def one_variance(values, test_var: float | None=None, conf: float=0.95, alt: int=0) -> dict:
    x = _clean(values)
    n, s2 = (len(x), float(x.var(ddof=1)))
    lo, hi = bonett_variance_ci(x, _z(conf, alt))
    out = {'n': n, 'stdev': math.sqrt(s2), 'variance': s2, 'bonett_ci': _sided(lo, hi, alt), 'chisq_ci': _chisq_ci(n, s2, conf, alt)}
    if test_var is None:
        return out
    chi = (n - 1) * s2 / test_var
    out.update(chisq=chi, df=n - 1, chisq_p=_p_from(chi, alt, lambda v: stats.chi2.cdf(v, n - 1), lambda v: stats.chi2.sf(v, n - 1)))

    def g(alpha):
        z = stats.norm.ppf(1 - alpha / 2) if alt == 0 else stats.norm.ppf(1 - alpha)
        l, h = bonett_variance_ci(x, z)
        if alt == 0:
            return l - test_var if test_var < l or test_var <= s2 else test_var - h
        return l - test_var if alt == 1 else test_var - h
    if alt == 0:
        side_lo = test_var <= s2
        out['bonett_p'] = _p_by_alpha(lambda a: bonett_variance_ci(x, stats.norm.ppf(1 - a / 2))[0] - test_var if side_lo else test_var - bonett_variance_ci(x, stats.norm.ppf(1 - a / 2))[1])
    else:
        out['bonett_p'] = _p_by_alpha(g)
    return out

def _ratio_stat(x1, x2, rho: float, z: float) -> float:
    n1, s1, m41, ss1 = _parts(x1)
    n2, s2, m42, ss2 = _parts(x2)
    g4 = (n1 + n2) * (m41 + rho * rho * m42) / (ss1 + rho * ss2) ** 2
    c = n1 / (n1 - z) / (n2 / (n2 - z))
    se = math.sqrt((g4 - (n1 - 3) / n1) / (n1 - 1) + (g4 - (n2 - 3) / n2) / (n2 - 1))
    return (math.log(c * s1 / s2) - math.log(rho)) / se

def _roots(f, center: float, span: float=9.0, steps: int=900):
    grid = np.exp(np.linspace(math.log(center) - span, math.log(center) + span, steps))
    vals = np.array([f(g) for g in grid])
    out = []
    for i in range(len(grid) - 1):
        if vals[i] * vals[i + 1] < 0:
            out.append(float(optimize.brentq(f, grid[i], grid[i + 1], xtol=1e-14)))
    return (out, grid, vals)

def two_variances(a, b, test_ratio: float=1.0, conf: float=0.95, alt: int=0, use_f: bool=False) -> dict:
    x1, x2 = (_clean(a), _clean(b))
    n1, n2 = (len(x1), len(x2))
    v1, v2 = (float(x1.var(ddof=1)), float(x2.var(ddof=1)))
    ratio = v1 / v2
    out = {'n': (n1, n2), 'stdevs': (math.sqrt(v1), math.sqrt(v2)), 'variances': (v1, v2), 'ratio': ratio}
    if use_f:
        fq = lambda p: stats.f.ppf(p, n1 - 1, n2 - 1)
        a_ = 1 - conf
        lo = ratio / fq(1 - a_ / 2 if alt == 0 else conf)
        hi = ratio / fq(a_ / 2 if alt == 0 else a_)
        f = ratio / test_ratio
        out.update(var_ci=[_chisq_ci(n1, v1, conf, alt), _chisq_ci(n2, v2, conf, alt)], f_ci=_sided(lo, hi, alt), f=f, df=(n1 - 1, n2 - 1), f_p=_p_from(f, alt, lambda v: stats.f.cdf(v, n1 - 1, n2 - 1), lambda v: stats.f.sf(v, n1 - 1, n2 - 1)))
        return out
    z = _z(conf, alt)
    out['var_ci'] = [_sided(*bonett_variance_ci(x, z), alt) for x in (x1, x2)]
    lo = _roots(lambda r: _ratio_stat(x1, x2, r, z) - z, ratio)[0]
    hi = _roots(lambda r: _ratio_stat(x1, x2, r, z) + z, ratio)[0]
    out['bonett_ci'] = _sided(lo[0] if lo else None, hi[-1] if hi else None, alt)

    def g(alpha):
        zz = stats.norm.ppf(1 - alpha / 2) if alt == 0 else stats.norm.ppf(1 - alpha)
        st = _ratio_stat(x1, x2, test_ratio, zz)
        return (abs(st) if alt == 0 else st * alt) - zz
    out['bonett_p'] = _p_by_alpha(g)
    lev = lambda r: stats.levene(x1, x2 * math.sqrt(r), center='median')
    st = lev(test_ratio)
    out['levene_f'], out['levene_df'] = (float(st.statistic), (1, n1 + n2 - 2))
    if alt == 0:
        out['levene_p'] = float(st.pvalue)
    else:
        d1 = np.abs(x1 - np.median(x1)).mean()
        y2 = x2 * math.sqrt(test_ratio)
        d2 = np.abs(y2 - np.median(y2)).mean()
        out['levene_p'] = float(st.pvalue / 2 if (d1 > d2) == (alt == 1) else 1 - st.pvalue / 2)
    alpha_l = 1 - conf if alt == 0 else 2 * (1 - conf)
    roots, _, _ = _roots(lambda r: lev(r).pvalue - alpha_l, ratio)
    l_lo, l_hi = (roots[0], roots[-1]) if len(roots) >= 2 else (None, None)
    out['levene_ci'] = _sided(l_lo, l_hi, alt)
    return out

def _pair_se(pi, pj) -> float:
    n1, _, m41, ss1 = pi
    n2, _, m42, ss2 = pj
    g4 = (n1 + n2) * (m41 + m42) / (ss1 + ss2) ** 2
    return math.sqrt((g4 - (n1 - 3) / n1) / (n1 - 1) + (g4 - (n2 - 3) / n2) / (n2 - 1))

def _smallest_root(n1: int, n2: int, v1: float, v2: float, se: float) -> float | None:
    f = lambda x: math.log(n1 / (n1 - x)) + math.log((n2 - x) / n2) - x * se + math.log(v1 / v2)
    if n1 < n2:
        d = (n1 + n2 - math.sqrt((n1 - n2) * (n1 - n2 - 4 / se))) / 2
        if f(d) > 0:
            return None
        step = 1.0
        while f(d - step) < 0:
            step *= 2
        return float(optimize.brentq(f, d - step, d, xtol=1e-14))
    if f(0.0) >= 0:
        return float(optimize.brentq(f, 0.0, min(n1, n2) * (1 - 1e-15), xtol=1e-14))
    step = 1.0
    while f(-step) < 0:
        step *= 2
    return float(optimize.brentq(f, -step, 0.0, xtol=1e-14))

def _mc_p(arrs) -> float:
    k = len(arrs)
    parts = [_parts(x) for x in arrs]
    se = np.zeros((k, k))
    for i in range(k):
        for j in range(i + 1, k):
            se[i, j] = se[j, i] = _pair_se(parts[i], parts[j])
    total = se.sum() / 2
    v = [((k - 1) * se[i].sum() - total) / ((k - 1) * (k - 2)) for i in range(k)]
    q_sf = lambda x: float(stats.studentized_range.sf(math.sqrt(2) * x, k, 1000000.0)) if x > 0 else 1.0
    best = 1.0
    for i in range(k):
        for j in range(i + 1, k):
            s_ij = v[i] + v[j]
            if s_ij <= 0:
                s_ij = se[i, j]
            (ni, vi), (nj, vj) = (parts[i][:2], parts[j][:2])
            if ni == nj:
                p = q_sf(abs(math.log(vi / vj)) / s_ij)
            else:
                zl = _smallest_root(ni, nj, vi, vj, s_ij)
                zu = _smallest_root(nj, ni, vj, vi, s_ij)
                p = min(0.0 if zl is None else q_sf(zl), 0.0 if zu is None else q_sf(zu))
            best = min(best, p)
    return best

def equal_variances_test(response, groups, conf: float=0.95, bartlett: bool=False) -> dict:
    data: dict = {}
    for y, g in zip(response, groups):
        if y is None or g is None or (not np.isfinite(y)):
            continue
        data.setdefault(g, []).append(float(y))
    keys = list(data)
    try:
        keys = sorted(keys, key=lambda k: tuple((float(v) for v in (k if isinstance(k, tuple) else (k,)))))
    except (TypeError, ValueError):
        keys = sorted(keys, key=lambda k: tuple((str(v) for v in (k if isinstance(k, tuple) else (k,)))))
    arrs = [np.asarray(data[k]) for k in keys]
    k = len(arrs)
    a_ind = (1 - conf) / k
    z = stats.norm.ppf(1 - a_ind / 2)
    rows = []
    for key, x in zip(keys, arrs):
        n, s2 = (len(x), float(x.var(ddof=1)))
        if bartlett:
            lo = (n - 1) * s2 / stats.chi2.ppf(1 - a_ind / 2, n - 1)
            hi = (n - 1) * s2 / stats.chi2.ppf(a_ind / 2, n - 1)
        else:
            lo, hi = bonett_variance_ci(x, z)
        rows.append({'group': key, 'n': n, 'stdev': math.sqrt(s2), 'ci': (math.sqrt(lo), math.sqrt(hi))})
    out = {'groups': rows, 'individual_conf': 1 - a_ind}
    if bartlett:
        b = stats.bartlett(*arrs)
        out.update(bartlett=float(b.statistic), bartlett_p=float(b.pvalue))
        return out
    out['mc_p'] = _mc_p(arrs) if k > 2 else two_variances(arrs[0], arrs[1])['bonett_p']
    lev = stats.levene(*arrs, center='median')
    out.update(levene=float(lev.statistic), levene_p=float(lev.pvalue))
    return out

