from __future__ import annotations
import numpy as np
from scipy import stats
from .normal import NormalCapabilityOptions, SpecLimits, normal_capability

def _summary(values, subgroup, specs):
    r = normal_capability(values, subgroup, specs)
    ppm = r.ppm_overall
    total = float(ppm.total)
    return {'n': r.n, 'mean': r.mean, 'stdev_overall': r.sigma_overall.value, 'stdev_within': r.sigma_within.value, 'pp': r.overall.cp, 'ppk': r.overall.cpk, 'cp': r.within.cp, 'cpk': r.within.cpk, 'z_bench': float(stats.norm.isf(total / 1000000.0)) if 0 < total < 1000000.0 else None, 'percent_out': total / 10000.0, 'ppm': total, 'ppm_observed': float(r.ppm_observed.total)}

def capability_comparison(before, after, lsl=None, usl=None, subgroup: int=1) -> dict:
    b = np.array([float(v) for v in before if v is not None])
    a = np.array([float(v) for v in after if v is not None])
    specs = SpecLimits(lsl=lsl, usl=usl)
    sb, sa = (_summary(list(b), subgroup, specs), _summary(list(a), subgroup, specs))
    t = stats.ttest_ind(b, a, equal_var=False)
    f = float(b.var(ddof=1) / a.var(ddof=1))
    p_sd = float(stats.f.sf(f, len(b) - 1, len(a) - 1))
    change = {k: sa[k] - sb[k] if sa[k] is not None and sb[k] is not None else None for k in ('mean', 'stdev_overall', 'pp', 'ppk', 'z_bench', 'percent_out', 'ppm')}
    return {'before': sb, 'after': sa, 'change': change, 'reduction_percent_out': None if sb['percent_out'] == 0 else 100 * (1 - sa['percent_out'] / sb['percent_out']), 'mean_test': {'t': float(t.statistic), 'df': float(t.df), 'p': float(t.pvalue)}, 'sd_test': {'f': f, 'p': p_sd}}

def multiple_variables_capability(columns: dict, lsl=None, usl=None, subgroup: int=1) -> dict:
    specs = SpecLimits(lsl=lsl, usl=usl)
    rows = []
    for name, vals in columns.items():
        x = [v for v in vals if v is not None]
        rows.append({'variable': name, **_summary(x, subgroup, specs)})
    return {'rows': rows}

