from __future__ import annotations
import numpy as np
from scipy import stats

def wilson_cc_interval(x: int, n: int, confidence: float=0.95) -> tuple[float, float]:
    p = x / n
    z = float(stats.norm.ppf(1 - (1 - confidence) / 2))
    z2, d = (z * z, 2 * (n + z * z))
    lo = 0.0 if x == 0 else (2 * n * p + z2 - 1 - z * np.sqrt(z2 - 2 - 1 / n + 4 * p * (n * (1 - p) + 1))) / d
    hi = 1.0 if x == n else (2 * n * p + z2 + 1 + z * np.sqrt(z2 + 2 - 1 / n + 4 * p * (n * (1 - p) - 1))) / d
    return (float(max(lo, 0.0)), float(min(hi, 1.0)))

def empirical_percentile(xs: np.ndarray, p: float) -> float:
    n = len(xs)
    pos = p * (n + 1)
    if pos <= 1:
        return float(xs[0])
    if pos >= n:
        return float(xs[-1])
    k = int(np.floor(pos))
    return float(xs[k - 1] + (pos - k) * (xs[k] - xs[k - 1]))

def nonparametric_capability(values, lsl: float | None=None, usl: float | None=None, target: float | None=None, confidence: float=0.95) -> dict:
    x = np.sort(np.array([float(v) for v in values if v is not None]))
    if len(x) < 2:
        raise ValueError('En az 2 gözlem gerekli.')
    if lsl is None and usl is None:
        raise ValueError('En az bir spesifikasyon sınırı gerekli.')
    lo, med, hi = (empirical_percentile(x, 0.00135), empirical_percentile(x, 0.5), empirical_percentile(x, 0.99865))
    out = {'n': len(x), 'mean': float(x.mean()), 'stdev': float(x.std(ddof=1)), 'median': med, 'p0135': lo, 'p99865': hi, 'lsl': lsl, 'usl': usl, 'target': target, 'cnp': None, 'cnpl': None, 'cnpu': None, 'cnpk': None}
    if lsl is not None and usl is not None and (hi > lo):
        out['cnp'] = (usl - lsl) / (hi - lo)
    if lsl is not None and med > lo:
        out['cnpl'] = (med - lsl) / (med - lo)
    if usl is not None and hi > med:
        out['cnpu'] = (usl - med) / (hi - med)
    ks = [v for v in (out['cnpl'], out['cnpu']) if v is not None]
    out['cnpk'] = min(ks) if ks else None
    n = len(x)
    below = int((x < lsl).sum()) if lsl is not None else None
    above = int((x > usl).sum()) if usl is not None else None
    out['observed'] = {'below': below, 'above': above, 'ppm_below': None if below is None else 1000000.0 * below / n, 'ppm_above': None if above is None else 1000000.0 * above / n, 'ppm_total': 1000000.0 * ((below or 0) + (above or 0)) / n}

    def _ci(k):
        if k is None:
            return None
        a, b = wilson_cc_interval(k, n, confidence)
        return [1000000.0 * a, 1000000.0 * b]
    out['observed']['confidence'] = confidence
    out['observed']['ppm_below_ci'] = _ci(below)
    out['observed']['ppm_above_ci'] = _ci(above)
    out['observed']['ppm_total_ci'] = _ci((below or 0) + (above or 0))
    return out

