from __future__ import annotations
from dataclasses import dataclass, field
from typing import Sequence
import numpy as np
from scipy import optimize
from scipy.special import expit
from scipy.stats import chi2, nct, norm
from ..sigma import SigmaEstimate, WithinMethod, between_within_sigma, overall_sigma, within_sigma
PPM = 1000000.0

@dataclass(frozen=True)
class SpecLimits:
    lsl: float | None = None
    usl: float | None = None
    target: float | None = None
    lsl_boundary: bool = False
    usl_boundary: bool = False

    def __post_init__(self) -> None:
        if self.lsl is None and self.usl is None:
            raise ValueError('en az bir spesifikasyon sınırı gerekli')
        if self.lsl is not None and self.usl is not None and (self.lsl >= self.usl):
            raise ValueError("AÖL, ÜÖL'den küçük olmalı")

@dataclass(frozen=True)
class NormalCapabilityOptions:
    within_method: WithinMethod | None = None
    unbiased_within: bool = True
    unbiased_overall: bool = False
    mr_span: int = 2
    k: float = 6.0
    historical_mean: float | None = None
    historical_sigma: float | None = None
    confidence: float | None = None
    two_sided_ci: bool = False
    between_within: bool = False

@dataclass
class IndexSet:
    cp: float | None
    cpl: float | None
    cpu: float | None
    cpk: float | None

@dataclass
class PpmSet:
    below_lsl: float | None
    above_usl: float | None
    total: float

@dataclass
class Interval:
    lower: float | None
    upper: float | None

@dataclass
class PpmBounds:
    below_lsl: Interval
    above_usl: Interval
    total: Interval

@dataclass
class NormalCapabilityResult:
    n: int
    mean: float
    sigma_within: SigmaEstimate
    sigma_overall: SigmaEstimate
    specs: SpecLimits
    k: float
    within: IndexSet
    overall: IndexSet
    cpm: float | None
    ppm_observed: PpmSet
    ppm_within: PpmSet
    ppm_overall: PpmSet
    ci: dict[str, Interval] = field(default_factory=dict)
    ppm_ci_within: PpmBounds | None = None
    ppm_ci_overall: PpmBounds | None = None

def _indices(mean: float, sigma: float, specs: SpecLimits, k: float) -> IndexSet:
    half = k / 2.0 * sigma
    cpl = None if specs.lsl is None or specs.lsl_boundary else (mean - specs.lsl) / half
    cpu = None if specs.usl is None or specs.usl_boundary else (specs.usl - mean) / half
    cp = None
    if specs.lsl is not None and specs.usl is not None and (not (specs.lsl_boundary or specs.usl_boundary)):
        cp = (specs.usl - specs.lsl) / (k * sigma)
    sides = [v for v in (cpl, cpu) if v is not None]
    cpk = min(sides) if sides else None
    return IndexSet(cp, cpl, cpu, cpk)

def _expected_ppm(mean: float, sigma: float, specs: SpecLimits) -> PpmSet:
    below = None if specs.lsl is None or specs.lsl_boundary else norm.cdf((specs.lsl - mean) / sigma) * PPM
    above = None if specs.usl is None or specs.usl_boundary else norm.sf((specs.usl - mean) / sigma) * PPM
    return PpmSet(below, above, (below or 0.0) + (above or 0.0))

def _observed_ppm(x: np.ndarray, specs: SpecLimits) -> PpmSet:
    n = len(x)
    below = None if specs.lsl is None else np.count_nonzero(x < specs.lsl) / n * PPM
    above = None if specs.usl is None else np.count_nonzero(x > specs.usl) / n * PPM
    return PpmSet(below, above, (below or 0.0) + (above or 0.0))

def _cpm(x: np.ndarray, specs: SpecLimits, k: float) -> float | None:
    if specs.target is None:
        return None
    t = specs.target
    tau = np.sqrt(((x - t) ** 2).sum() / len(x))
    sides = []
    if specs.lsl is not None and (not specs.lsl_boundary):
        sides.append(t - specs.lsl)
    if specs.usl is not None and (not specs.usl_boundary):
        sides.append(specs.usl - t)
    return min(sides) / (k / 2.0 * tau) if sides else None

def _bounds(lower: float, upper: float, two_sided: bool) -> Interval:
    return Interval(lower, upper if two_sided else None)

def _cp_interval(cp: float | None, dof: float, alpha: float, two_sided: bool) -> Interval:
    if cp is None:
        return Interval(None, None)
    return _bounds(cp * np.sqrt(chi2.ppf(alpha, dof) / dof), cp * np.sqrt(chi2.ppf(1 - alpha, dof) / dof), two_sided)

def _cpk_interval(cpk: float | None, n: int, dof: float, k: float, alpha: float, two_sided: bool) -> Interval:
    if cpk is None:
        return Interval(None, None)
    z = norm.ppf(1 - alpha)
    se = np.sqrt(1.0 / (n * (k / 2.0) ** 2) + cpk ** 2 / (2.0 * dof))
    return _bounds(cpk - z * se, cpk + z * se, two_sided)

def _known_mean_interval(index: float | None, dof: float, alpha: float, two_sided: bool) -> Interval:
    return _cp_interval(index, dof, alpha, two_sided)

def _cpm_interval(cpm: float | None, n: int, mean: float, target: float | None, sigma_overall: float, alpha: float, two_sided: bool) -> Interval:
    if cpm is None or target is None:
        return Interval(None, None)
    a = (mean - target) / sigma_overall
    nu = n * (1 + a * a) ** 2 / (1 + 2 * a * a)
    return _bounds(cpm * np.sqrt(chi2.ppf(alpha, nu) / nu), cpm * np.sqrt(chi2.ppf(1 - alpha, nu) / nu), two_sided)

def _side_ppm_bounds(z: float | None, n: int, dof: float, alpha: float, two_sided: bool) -> Interval:
    if z is None:
        return Interval(None, None)
    if two_sided:
        zc = norm.ppf(1 - alpha)
        se = np.sqrt(z * z / (2.0 * dof) + 1.0 / n)
        return Interval(norm.sf(z + zc * se) * PPM, norm.sf(z - zc * se) * PPM)
    t_obs = np.sqrt(n) * z
    f = lambda d: nct.cdf(t_obs, dof, d) - (1 - alpha)
    step, lo = (1.0, t_obs - 1.0)
    while f(lo) < 0:
        step *= 2
        lo = t_obs - step
    delta = optimize.brentq(f, lo, t_obs, xtol=1e-12)
    return Interval(None, norm.sf(delta / np.sqrt(n)) * PPM)

def _total_ppm_bounds(z_l: float | None, z_u: float | None, n: int, dof: float, alpha: float, two_sided: bool) -> Interval:
    if z_l is None or z_u is None:
        single = z_l if z_u is None else z_u
        return _side_ppm_bounds(single, n, dof, alpha, two_sided)
    p = norm.sf(z_l) + norm.sf(z_u)
    if p <= 0.0 or p >= 1.0:
        return Interval(None, None)
    g = 1.0 / ((1.0 - p) * p)
    d_mu = (norm.pdf(z_u) - norm.pdf(z_l)) * g
    d_sigma = 0.5 * (norm.pdf(z_l) * z_l + norm.pdf(z_u) * z_u) * g
    se = np.sqrt(2.0 * d_sigma ** 2 / dof + d_mu ** 2 / n)
    logit = np.log(p / (1.0 - p))
    zc = norm.ppf(1 - alpha)
    lower, upper = (expit(logit - zc * se) * PPM, expit(logit + zc * se) * PPM)
    return Interval(lower if two_sided else None, upper)
_NO_PPM_BOUNDS = PpmBounds(Interval(None, None), Interval(None, None), Interval(None, None))

def _ppm_bounds(mean: float, sigma: SigmaEstimate, specs: SpecLimits, n: int, alpha: float, two_sided: bool) -> PpmBounds:
    z_l = None if specs.lsl is None or specs.lsl_boundary else (mean - specs.lsl) / sigma.value
    z_u = None if specs.usl is None or specs.usl_boundary else (specs.usl - mean) / sigma.value
    return PpmBounds(_side_ppm_bounds(z_l, n, sigma.df, alpha, two_sided), _side_ppm_bounds(z_u, n, sigma.df, alpha, two_sided), _total_ppm_bounds(z_l, z_u, n, sigma.df, alpha, two_sided))

def normal_capability(values: Sequence[float | None], subgroup: int | Sequence, specs: SpecLimits, options: NormalCapabilityOptions=NormalCapabilityOptions()) -> NormalCapabilityResult:
    raw = np.array([np.nan if v is None else v for v in values], dtype=float)
    x = raw[~np.isnan(raw)]
    if len(x) < 2:
        raise ValueError('en az 2 gözlem gerekli')
    mean = options.historical_mean if options.historical_mean is not None else float(x.mean())
    sw = SigmaEstimate(options.historical_sigma, 'historical', float('inf')) if options.historical_sigma is not None else between_within_sigma(raw, subgroup, options.within_method, options.unbiased_within) if options.between_within else within_sigma(raw, subgroup, options.within_method, options.unbiased_within, options.mr_span)
    so = overall_sigma(raw, options.unbiased_overall)
    if sw.value <= 0 or so.value <= 0:
        raise ValueError('standart sapma sıfır; yetenek hesaplanamaz')
    within = _indices(mean, sw.value, specs, options.k)
    overall = _indices(mean, so.value, specs, options.k)
    result = NormalCapabilityResult(n=len(x), mean=mean, sigma_within=sw, sigma_overall=so, specs=specs, k=options.k, within=within, overall=overall, cpm=_cpm(x, specs, options.k), ppm_observed=_observed_ppm(x, specs), ppm_within=_expected_ppm(mean, sw.value, specs), ppm_overall=_expected_ppm(mean, so.value, specs))
    if options.confidence is not None:
        known_mu = options.historical_mean is not None
        known_sigma = options.historical_sigma is not None
        two = options.two_sided_ci
        alpha = (1 - options.confidence) / (2 if two else 1)
        n = len(x)
        none = Interval(None, None)
        if known_mu and known_sigma:
            cpk_ci = none
        elif known_mu:
            cpk_ci = _known_mean_interval(within.cpk, sw.df, alpha, two)
        else:
            cpk_ci = _cpk_interval(within.cpk, n, sw.df, options.k, alpha, two)
        result.ci = {'cp': none if known_sigma else _cp_interval(within.cp, sw.df, alpha, two), 'cpk': cpk_ci, 'pp': _cp_interval(overall.cp, so.df, alpha, two), 'ppk': _known_mean_interval(overall.cpk, so.df, alpha, two) if known_mu else _cpk_interval(overall.cpk, n, so.df, options.k, alpha, two), 'cpm': _cpm_interval(result.cpm, n, mean, specs.target, so.value, alpha, two)}
        result.ppm_ci_within = _NO_PPM_BOUNDS if known_mu or known_sigma else _ppm_bounds(mean, sw, specs, n, alpha, two)
        result.ppm_ci_overall = _NO_PPM_BOUNDS if known_mu else _ppm_bounds(mean, so, specs, n, alpha, two)
    return result

