from functools import lru_cache
from math import exp, inf, lgamma, sqrt
from scipy import integrate, optimize
from scipy.stats import norm

@lru_cache(maxsize=None)
def c4(n: int) -> float:
    if n < 2:
        raise ValueError('c4 için n >= 2 olmalı')
    return sqrt(2.0 / (n - 1)) * exp(lgamma(n / 2) - lgamma((n - 1) / 2))

@lru_cache(maxsize=None)
def d2_exact(n: int) -> float:
    if n < 2:
        raise ValueError('d2 için n >= 2 olmalı')
    f = lambda x: 1.0 - norm.cdf(x) ** n - norm.sf(x) ** n
    val, _ = integrate.quad(f, -inf, inf, epsabs=1e-13, epsrel=1e-12, limit=200)
    return val

@lru_cache(maxsize=None)
def d3_exact(n: int) -> float:
    if n < 2:
        raise ValueError('d3 için n >= 2 olmalı')

    def inner(y: float) -> float:
        Fy = norm.cdf(y)
        g = lambda x: 1.0 - Fy ** n - norm.sf(x) ** n + (Fy - norm.cdf(x)) ** n
        v, _ = integrate.quad(g, -inf, y, epsabs=1e-12, epsrel=1e-11, limit=200)
        return v
    er2, _ = integrate.quad(inner, -inf, inf, epsabs=1e-11, epsrel=1e-10, limit=200)
    return sqrt(2.0 * er2 - d2_exact(n) ** 2)

def _range_cdf(r: float, n: int) -> float:
    g = lambda x: norm.pdf(x) * (norm.cdf(x + r) - norm.cdf(x)) ** (n - 1)
    v, _ = integrate.quad(g, -inf, inf, epsabs=1e-13, epsrel=1e-12, limit=200)
    return n * v

