def d4_exact(n: int) -> float:
    if n < 2:
        raise ValueError('d4 için n >= 2 olmalı')
    return optimize.brentq(lambda r: _range_cdf(r, n) - 0.5, 1e-06, 20.0, xtol=1e-13)
