def _constant(table: tuple[float, ...], poly: tuple[float, ...], exact, n: int) -> float:
    if n < 2:
        raise ValueError('n >= 2 olmalı')
    if n - 2 < len(table):
        return table[n - 2]
    if n <= _MAX_APPROX_N:
        return _poly(poly, n)
    return exact(n)

def d2(n: int) -> float:
    return _constant(_D2_TABLE, _D2_POLY, d2_exact, n)

def d3(n: int) -> float:
    return _constant(_D3_TABLE, _D3_POLY, d3_exact, n)

def d4(n: int) -> float:
    return _constant(_D4_TABLE, _D4_POLY, d4_exact, n)

def mssd_unbiasing(n: int) -> float:
    if n < 2:
        raise ValueError('n >= 2 olmalı')
    if n == 2:
        return 0.79785
    if n == 3:
        return 0.87153
    return exp(-0.5) * (n / (n - 1)) ** ((n - 3) / 2) * (6 * n + 1) / (6 * n - 5) / (1.00013 + 0.12296 / n - 0.21543 / n ** 2)

