def anderson_darling(x: np.ndarray, cdf) -> float:
    xs = np.sort(np.asarray(x, dtype=float))
    n = len(xs)
    z = np.clip(cdf(xs), 1e-300, 1 - 1e-16)
    i = np.arange(1, n + 1)
    return float(-n - np.mean((2 * i - 1) * np.log(z) + (2 * n + 1 - 2 * i) * np.log(1 - z)))

def normal_ad_pvalue(a2: float, n: int) -> float:
    a = a2 * (1 + 0.75 / n + 2.25 / n ** 2)
    if a < 0.2:
