    elif a < 0.6:
        p = math.exp(0.9177 - 4.279 * a - 1.38 * a ** 2)
    else:
        p = math.exp(1.2937 - 5.709 * a + 0.0186 * a ** 2)
    return min(max(p, 0.0), 1.0)
