def _interp_row(key: float, keys, rows) -> list[float]:
    i = bisect.bisect_left(keys, key)
    if i == 0:
        return list(rows[0])
    if i >= len(keys):
        return list(rows[-1])
    w = (key - keys[i - 1]) / (keys[i] - keys[i - 1])
    return [a + w * (b - a) for a, b in zip(rows[i - 1], rows[i])]

def gamma_ad_pvalue(a2: float, shape: float) -> tuple[float | None, str]:
    row = _interp_row(shape, _GAMMA_SHAPES, _GAMMA_CRIT)
    return _table_pvalue(a2, list(zip(_GAMMA_ALPHA, row)))

def weibull3_ad_pvalue(a2: float, shape: float) -> tuple[float | None, str]:
    row = _interp_row(1.0 / shape, _W3_KEYS, _W3_CRIT)
    return _table_pvalue(a2, list(zip(_W3_ALPHA, row)))

def exponential_ad_pvalue(a2: float, n: int) -> tuple[float | None, str]:
    a = a2 * (1 + 0.6 / n)
    if a <= 0.26:
        p = 1 - math.exp(-12.2204 + 67.459 * a - 110.3 * a * a)
    elif a <= 0.51:
        p = 1 - math.exp(-6.1327 + 20.218 * a - 18.663 * a * a)
    elif a <= 0.95:
        p = math.exp(0.9209 - 3.353 * a + 0.3 * a * a)
    elif a <= 2.534:
        p = math.exp(0.731 - 3.009 * a + 0.15 * a * a)
    else:
        return (None, f'<{0.0025:.3f}')
    p = min(max(p, 0.0), 1.0)
    return (p, f'{p:.3f}')

def exponential2_ad_pvalue(a2: float, n: int) -> tuple[float | None, str]:
    return _table_pvalue(a2 * (1 + 5.4 / n - 11 / n ** 2), _EXP2_TABLE)

def _table_pvalue(a_mod: float, table: list[tuple[float, float]]) -> tuple[float | None, str]:
    if a_mod < table[0][1]:
        return (None, f'>{table[0][0]:.3f}')
    for (p1, c1), (p2, c2) in zip(table, table[1:]):
        if a_mod <= c2:
            p = p1 - (a_mod - c1) / (c2 - c1) * (p1 - p2)
            return (p, f'{p:.3f}')
    return (None, f'<{table[-1][0]:.3f}')

def _fmt_p(p: float, lo: float | None=None) -> str:
