    return f'{p:.3f}'

def _loglik(dist, x) -> float:
    return float(np.sum(dist.logpdf(x)))

def _profile_threshold(x: np.ndarray, fit_shifted, lower_gap: float=1e-09) -> tuple[float, tuple, float]:
    xm, spread = (x.min(), x.max() - x.min())

    def negll(th):
        params, ll = fit_shifted(x - th)
        return -ll
    lo = xm - 20 * max(spread, 1e-09)
    res = optimize.minimize_scalar(negll, bounds=(lo, xm - lower_gap * max(spread, 1)), method='bounded', options={'xatol': 1e-12, 'maxiter': 2000})
    th = float(res.x)
    params, ll = fit_shifted(x - th)
    return (th, params, ll)

def fit_normal(x: np.ndarray) -> Fit:
    m, s = (x.mean(), x.std(ddof=1))
    d = stats.norm(m, s)
    return Fit('Normal', {'location': m, 'scale': s}, d.cdf, d.ppf, _loglik(stats.norm(m, x.std()), x), 2)

def fit_lognormal(x: np.ndarray) -> Fit:
    lx = np.log(x)
    m, s = (lx.mean(), lx.std(ddof=1))
    d = stats.lognorm(s, 0, math.exp(m))
    ll = _loglik(stats.lognorm(lx.std(), 0, math.exp(m)), x)
    return Fit('Lognormal', {'location': m, 'scale': s}, d.cdf, d.ppf, ll, 2)

def fit_lognormal3(x: np.ndarray) -> Fit:

    def f(y):
        ly = np.log(y)
        m, s = (ly.mean(), ly.std())
        return ((m, s), float(np.sum(stats.norm.logpdf(ly, m, s) - ly)))
    th, (m, s), ll = _profile_threshold(x, f)
    d = stats.lognorm(s, th, math.exp(m))
    return Fit('3-Parameter Lognormal', {'location': m, 'scale': s, 'threshold': th}, d.cdf, d.ppf, ll, 3)

def fit_exponential(x: np.ndarray) -> Fit:
    d = stats.expon(0, x.mean())
    return Fit('Exponential', {'scale': x.mean()}, d.cdf, d.ppf, _loglik(d, x), 1)

def fit_exponential2(x: np.ndarray) -> Fit:
    n = len(x)
    scale = (x.mean() - x.min()) * n / (n - 1)
    th = x.min() - scale / n
    d = stats.expon(th, scale)
    return Fit('2-Parameter Exponential', {'scale': scale, 'threshold': th}, d.cdf, d.ppf, _loglik(d, x), 2)

def _weibull_mle(y: np.ndarray) -> tuple[float, float]:
    ly = np.log(y)
    lm = ly.mean()
    u = ly - ly.max()

    def g(k):
        w = np.exp(k * u)
        return np.sum(w * ly) / np.sum(w) - 1 / k - lm
    lo, hi = (0.01, 1.0)
    while g(hi) < 0:
        hi *= 2
    k = optimize.brentq(g, lo, hi, xtol=1e-14, rtol=1e-15, maxiter=500)
    scale = float(np.exp(ly.max()) * np.mean(np.exp(k * u)) ** (1 / k))
    return (float(k), scale)

