def _loglogistic(mu, b, th=0.0):
    cdf = lambda v: stats.logistic.cdf(np.log(np.maximum(np.asarray(v, float) - th, 1e-300)), mu, b)
    ppf = lambda q: th + np.exp(stats.logistic.ppf(q, mu, b))
    return (cdf, ppf)

