def boxcox_lambda(x: np.ndarray, lo: float=-5, hi: float=5) -> float:
    g = math.exp(np.log(x).mean())

    def sd(lam):
        w = np.log(x) * g if abs(lam) < 1e-12 else (x ** lam - 1) / (lam * g ** (lam - 1))
        return w.std(ddof=1)
    return float(optimize.minimize_scalar(sd, bounds=(lo, hi), method='bounded', options={'xatol': 1e-10}).x)

def boxcox_analysis(x, subgroup_size: int=1, lo: float=-5, hi: float=5, confidence: float=95.0) -> dict:
    x = np.asarray([float(v) for v in x if v is not None])
    if np.any(x <= 0):
        raise ValueError('Box-Cox için tüm veriler pozitif olmalı.')
    g = math.exp(np.log(x).mean())
    m = int(subgroup_size)

    def w(lam):
        return np.log(x) * g if abs(lam) < 1e-12 else (x ** lam - 1) / (lam * g ** (lam - 1))

    def sd(lam):
        v = w(lam)
        if m <= 1:
            return float(np.abs(np.diff(v)).mean() / 1.128)
        k = len(v) // m
        grp = v[:k * m].reshape(k, m)
        return float(math.sqrt(grp.var(axis=1, ddof=1).mean()))
    res = optimize.minimize_scalar(sd, bounds=(lo, hi), method='bounded', options={'xatol': 1e-10})
    lam, best = (float(res.x), float(res.fun))
    nu = 1.2 * (len(x) - 1) if m <= 1 else len(x) - len(x) // m
    limit = best * math.sqrt(math.exp(stats.chi2.ppf(confidence / 100, 1) / nu))
    lower = upper = None
    if sd(lo) > limit:
        lower = float(optimize.brentq(lambda v: sd(v) - limit, lo, lam))
    if sd(hi) > limit:
        upper = float(optimize.brentq(lambda v: sd(v) - limit, lam, hi))
    rounded = round_lambda(lam)
    grid = np.linspace(lo, hi, 41)
    return {'lambda': lam, 'stdev': best, 'lower': lower, 'upper': upper, 'rounded': rounded, 'limit': limit, 'curve': [{'lambda': float(v), 'stdev': sd(float(v))} for v in grid]}

def boxcox_transform(x: np.ndarray, lam: float) -> np.ndarray:
    return np.log(x) if lam == 0 else x ** lam

def round_lambda(lam: float) -> float:
    return round(lam * 2) / 2

@dataclass
class JohnsonTransform:
    family: str
    gamma: float
    eta: float
    epsilon: float
    lam: float | None
    z: float
    ad: float
    p_value: float

    def apply(self, x):
        x = np.asarray(x, dtype=float)
        if self.family == 'SB':
            return self.gamma + self.eta * np.log((x - self.epsilon) / (self.lam + self.epsilon - x))
        if self.family == 'SL':
            return self.gamma + self.eta * np.log(x - self.epsilon)
        return self.gamma + self.eta * np.arcsinh((x - self.epsilon) / self.lam)

    def text(self) -> str:
        if self.family == 'SB':
            return f'{self.gamma:.6g} + {self.eta:.6g} × Ln( ( X - {self.epsilon:.6g} ) / ( {self.lam + self.epsilon:.6g} - X ) )'
        if self.family == 'SL':
            return f'{self.gamma:.6g} + {self.eta:.6g} × Ln( X - {self.epsilon:.6g} )'
        return f'{self.gamma:.6g} + {self.eta:.6g} × Asinh( ( X - {self.epsilon:.6g} ) / {self.lam:.6g} )'

def _minitab_percentile(xs: np.ndarray, p: float) -> float:
    n = len(xs)
    pos = n * p + 0.5
    if pos <= 1:
        return float(xs[0])
    if pos >= n:
        return float(xs[-1])
    k = int(math.floor(pos))
    return float(xs[k - 1] + (pos - k) * (xs[k] - xs[k - 1]))

def johnson_transform(x, p_criterion: float=0.1, z_grid=None) -> JohnsonTransform | None:
    x = np.asarray(x, dtype=float)
    xs = np.sort(x)
    n = len(x)
    best: JohnsonTransform | None = None
    for z in z_grid if z_grid is not None else np.round(np.arange(0.25, 1.2501, 0.01), 2):
        x3n, x1n, x1, x3 = (_minitab_percentile(xs, stats.norm.cdf(k * z)) for k in (-3, -1, 1, 3))
        m, nn, p = (x3 - x1, x1n - x3n, x1 - x1n)
        if min(m, nn, p) <= 0:
            continue
        qr = m * nn / p ** 2
        try:
            if qr < 1:
                a = (1 + p / m) * (1 + p / nn)
                eta = z / math.acosh(0.5 * math.sqrt(a))
                gam = eta * math.asinh((p / nn - p / m) * math.sqrt(a - 4) / (2 * (p ** 2 / (m * nn) - 1)))
                lam = p * math.sqrt((a - 2) ** 2 - 4) / (p ** 2 / (m * nn) - 1)
                eps = (x1 + x1n) / 2 - lam / 2 + p * (p / nn - p / m) / (2 * (p ** 2 / (m * nn) - 1))
                if np.any(x <= eps) or np.any(x >= eps + lam):
                    continue
                t = JohnsonTransform('SB', gam, eta, eps, lam, float(z), 0, 0)
            elif qr > 1:
                eta = 2 * z / math.acosh(0.5 * (m / p + nn / p))
                gam = eta * math.asinh((nn / p - m / p) / (2 * math.sqrt(m * nn / p ** 2 - 1)))
                lam = 2 * p * math.sqrt(m * nn / p ** 2 - 1) / ((m / p + nn / p - 2) * math.sqrt(m / p + nn / p + 2))
                eps = (x1 + x1n) / 2 + p * (nn / p - m / p) / (2 * (m / p + nn / p - 2))
                t = JohnsonTransform('SU', gam, eta, eps, lam, float(z), 0, 0)
            else:
                eta = 2 * z / math.log(m / p)
                gam = eta * math.log((m / p - 1) / (p * math.sqrt(m / p)))
                eps = (x1 + x1n) / 2 - p / 2 * (m / p + 1) / (m / p - 1)
                if np.any(x <= eps):
                    continue
                t = JohnsonTransform('SL', gam, eta, eps, None, float(z), 0, 0)
        except (ValueError, ZeroDivisionError):
            continue
        y = t.apply(x)
        if not np.all(np.isfinite(y)):
            continue
        d = stats.norm(y.mean(), y.std(ddof=1))
        t.ad = anderson_darling(y, d.cdf)
        t.p_value = normal_ad_pvalue(t.ad, n)
        if best is None or t.p_value > best.p_value:
            best = t
    if best is None or best.p_value <= p_criterion:
        return None
    return best
FITTERS = [fit_normal, fit_lognormal, fit_lognormal3, fit_exponential, fit_exponential2, fit_weibull, fit_weibull3, fit_sev, fit_lev, fit_gamma, fit_gamma3, fit_logistic, fit_loglogistic, fit_loglogistic3]
_LRT_PARENT = {'3-Parameter Lognormal': 'Lognormal', '2-Parameter Exponential': 'Exponential', '3-Parameter Weibull': 'Weibull', '3-Parameter Gamma': 'Gamma', '3-Parameter Loglogistic': 'Loglogistic'}

def _goodness(fit: Fit, x: np.ndarray) -> None:
    n = len(x)
    fit.ad = anderson_darling(x, fit.cdf)
    name = fit.name
    if name in ('Normal', 'Lognormal'):
        fit.p_value = normal_ad_pvalue(fit.ad, n)
        fit.p_text = _fmt_p(fit.p_value, 0.005)
    elif name in ('Weibull', 'Smallest Extreme Value', 'Largest Extreme Value'):
        fit.p_value, fit.p_text = _table_pvalue(fit.ad * (1 + 0.2 / math.sqrt(n)), _EV_TABLE)
    elif name in ('Logistic', 'Loglogistic'):
        fit.p_value, fit.p_text = _table_pvalue(fit.ad * (1 + 0.25 / n), _LOGISTIC_TABLE)
    elif name == 'Gamma':
        fit.p_value, fit.p_text = gamma_ad_pvalue(fit.ad, fit.params['shape'])
    elif name == '3-Parameter Weibull':
        fit.p_value, fit.p_text = weibull3_ad_pvalue(fit.ad, fit.params['shape'])
    elif name == 'Exponential':
        fit.p_value, fit.p_text = exponential_ad_pvalue(fit.ad, n)
    elif name == '2-Parameter Exponential':
        fit.p_value, fit.p_text = exponential2_ad_pvalue(fit.ad, n)
    else:
        fit.p_value, fit.p_text = (None, '*')

def identify(x, include_transforms: bool=True) -> dict:
    x = np.asarray([v for v in x if v is not None and np.isfinite(v)], dtype=float)
    positive = bool(np.all(x > 0))
    fits: list[Fit] = []
    for fn in FITTERS:
        if not positive and fn not in (fit_normal, fit_sev, fit_lev, fit_logistic):
            continue
        f = fn(x)
        _goodness(f, x)
        fits.append(f)
    by_name = {f.name: f for f in fits}
    for child, parent in _LRT_PARENT.items():
        if child in by_name and parent in by_name:
            stat = max(0.0, 2 * (by_name[child].loglik - by_name[parent].loglik))
            by_name[child].lrt_p = float(stats.chi2.sf(stat, 1))
    out: dict = {'n': len(x), 'fits': fits}
    if include_transforms and positive:
        lam = boxcox_lambda(x)
        lam_r = round_lambda(lam)
        y = boxcox_transform(x, lam_r)
        d = stats.norm(y.mean(), y.std(ddof=1))
        ad = anderson_darling(y, d.cdf)
        p = normal_ad_pvalue(ad, len(x))
        out['boxcox'] = {'lambda': lam, 'lambda_rounded': lam_r, 'location': y.mean(), 'scale': y.std(ddof=1), 'ad': ad, 'p_value': p, 'p_text': _fmt_p(p, 0.005)}
    if include_transforms:
        out['johnson'] = johnson_transform(x)
    return out

