from __future__ import annotations
from fractions import Fraction
from itertools import combinations, product

def _ptype(row, q):
    nz = sum((1 for v in row if v > 1e-12))
    if nz == q and all((abs(v - 1 / q) < 1e-09 for v in row)):
        return 0
    return nz

def _axial(q):
    a, b = ((1 + 1 / q) / 2, 1 / q / 2)
    return [[a if j == i else b for j in range(q)] for i in range(q)]

def simplex_centroid(q: int, axial: bool=False) -> list[dict]:
    if q < 2:
        raise ValueError('En az 2 bileşen gerekli.')
    pts = []
    for r in range(1, q + 1):
        for sub in combinations(range(q), r):
            pts.append([1 / r if j in sub else 0.0 for j in range(q)])
    if axial:
        pts += _axial(q)
    return _rows(pts, q, n_axial=q if axial else 0)

def simplex_lattice(q: int, degree: int, center: bool=False, axial: bool=False) -> list[dict]:
    if q < 2 or degree < 1:
        raise ValueError('Geçersiz bileşen sayısı veya derece.')
    pts = []

    def rec(prefix, remaining, k):
        if k == q - 1:
            pts.append(prefix + [remaining])
            return
        for v in range(remaining, -1, -1):
            rec(prefix + [v], remaining - v, k + 1)
    rec([], degree, 0)
    pts = [[float(Fraction(v, degree)) for v in p] for p in pts]
    has_center = any((_ptype(p, q) == 0 for p in pts))
    if center and (not has_center):
        pts.append([1 / q] * q)
    if axial:
        pts += _axial(q)
    return _rows(pts, q, n_axial=q if axial else 0)

def extreme_vertices(lower: list[float], upper: list[float], degree: int=1, center: bool=False, total: float=1.0) -> list[dict]:
    q = len(lower)
    L, U = ([float(v) for v in lower], [float(v) for v in upper])
    if sum(L) > total + 1e-12 or sum(U) < total - 1e-12:
        raise ValueError('Sınırlar tutarsız: alt sınırlar toplamı ≤ toplam ≤ üst sınırlar toplamı olmalı.')
    verts: list[tuple[list[float], frozenset]] = []
    for j in range(q):
        others = [i for i in range(q) if i != j]
        for choice in product((0, 1), repeat=q - 1):
            x = [0.0] * q
            active = set()
            for i, c in zip(others, choice):
                x[i] = U[i] if c else L[i]
                active.add((i, c))
            x[j] = total - sum((x[i] for i in others))
            if x[j] < L[j] - 1e-09 or x[j] > U[j] + 1e-09:
                continue
            if abs(x[j] - L[j]) < 1e-09:
                active.add((j, 0))
            if abs(x[j] - U[j]) < 1e-09:
                active.add((j, 1))
            x = [round(v, 12) for v in x]
            for vx, act in verts:
                if all((abs(a - b) < 1e-09 for a, b in zip(vx, x))):
                    break
            else:
                verts.append((x, frozenset(active)))
    pts = [v for v, _ in verts]
    types = [1] * len(pts)
    if degree >= 2:
        for (a, sa), (b, sb) in combinations(verts, 2):
            if len(sa & sb) >= q - 2:
                pts.append([(u + v) / 2 for u, v in zip(a, b)])
                types.append(2)
    if center:
        pts.append([sum((v[i] for v, _ in verts)) / len(verts) for i in range(q)])
        types.append(0)
    return [{'std_order': i + 1, 'pt_type': t, 'components': p} for i, (p, t) in enumerate(zip(pts, types))]

def _rows(pts, q, n_axial=0):
    out = []
    for i, p in enumerate(pts):
        t = -1 if i >= len(pts) - n_axial else _ptype(p, q)
        out.append({'std_order': i + 1, 'pt_type': t, 'components': p})
    return out

def analyze_mixture(components: dict, response, terms: list[tuple[str, ...]] | None=None) -> dict:
    import numpy as np
    from scipy import stats
    names = list(components)
    q = len(names)
    rows = [i for i in range(len(response)) if response[i] is not None and all((components[c][i] is not None for c in names))]
    y = np.array([float(response[i]) for i in rows])
    Z = {c: np.array([float(components[c][i]) for i in rows]) for c in names}
    if terms is None:
        terms = [(c,) for c in names]
    terms = [tuple(t) for t in terms]
    lin = [t for t in terms if len(t) == 1]
    if sorted((t[0] for t in lin)) != sorted(names):
        raise ValueError('Modelde tüm bileşenlerin doğrusal terimleri bulunmalı.')

    def col(t):
        v = np.ones(len(y))
        for c in t:
            v = v * Z[c]
        return v
    X = np.column_stack([col(t) for t in terms])
    n, p = X.shape

    def sse_of(M):
        b, *_ = np.linalg.lstsq(M, y, rcond=None)
        r = y - M @ b
        return (float(r @ r), b)
    sse, beta = sse_of(X)
    sst = float(((y - y.mean()) ** 2).sum())
    dfe = n - p
    mse = sse / dfe if dfe > 0 else float('nan')
    XtXi = np.linalg.inv(X.T @ X)
    se = np.sqrt(np.diag(XtXi) * mse)
    vif = np.diag(XtXi) * np.diag(X.T @ X)
    coefs = []
    for j, t in enumerate(terms):
        row = {'term': '*'.join(t), 'coef': float(beta[j]), 'se': float(se[j]), 'vif': float(vif[j]), 't': None, 'p': None}
        if len(t) > 1:
            tv = beta[j] / se[j]
            row.update(t=float(tv), p=float(2 * stats.t.sf(abs(tv), dfe)))
        coefs.append(row)
    H = X @ XtXi @ X.T
    e = y - X @ beta
    press = float(((e / (1 - np.diag(H))) ** 2).sum())
    groups = {1: 'Linear', 2: 'Quadratic', 3: 'Special Cubic'}
    order = sorted(set((len(t) for t in terms)))
    ones = np.ones((n, 1))

    def f_row(source, df, seq, adj, level):
        ms = adj / df
        f = ms / mse
        return {'source': source, 'df': df, 'seq_ss': seq, 'adj_ss': adj, 'adj_ms': ms, 'f': f, 'p': float(stats.f.sf(f, df, dfe)), 'level': level}
    anova = []
    seq_terms = {}
    cur = [col(t) for t in lin]
    s_lin, _ = sse_of(np.column_stack(cur))
    seq_lin = sst - s_lin
    prev_sse = s_lin
    for t in [t for t in terms if len(t) > 1]:
        cur.append(col(t))
        s_new, _ = sse_of(np.column_stack(cur))
        seq_terms[t] = prev_sse - s_new
        prev_sse = s_new
    others_idx = [j for j, t in enumerate(terms) if len(t) > 1]
    red = np.column_stack([ones] + [X[:, j] for j in others_idx]) if others_idx else ones
    adj_lin = sse_of(red)[0] - sse
    anova.append(f_row('Linear', q - 1, seq_lin, adj_lin, 1))
    for k in order:
        if k == 1:
            continue
        grp = [t for t in terms if len(t) == k]
        keep = [j for j, t in enumerate(terms) if len(t) != k]
        adj_g = sse_of(X[:, keep])[0] - sse
        anova.append(f_row(groups.get(k, f'Order {k}'), len(grp), sum((seq_terms[t] for t in grp)), adj_g, 1))
        for t in grp:
            keep = [j for j, u in enumerate(terms) if u != t]
            anova.append(f_row('*'.join(t), 1, seq_terms[t], sse_of(X[:, keep])[0] - sse, 2))
    ssr = sst - sse
    reg = f_row('Regression', p - 1, ssr, ssr, 0)
    keys = [tuple(np.round(X[i, :q], 10)) for i in range(n)]
    uniq = {k_: [i for i in range(n) if keys[i] == k_] for k_ in dict.fromkeys(keys)}
    pe = float(sum((((y[idx] - y[idx].mean()) ** 2).sum() for idx in uniq.values())))
    df_pe = n - len(uniq)
    lof = None
    if df_pe > 0 and dfe - df_pe > 0:
        df_lof = dfe - df_pe
        ms_lof, ms_pe = ((sse - pe) / df_lof, pe / df_pe)
        lof = {'lack_of_fit': {'df': df_lof, 'ss': sse - pe, 'ms': ms_lof, 'f': ms_lof / ms_pe, 'p': float(stats.f.sf(ms_lof / ms_pe, df_lof, df_pe))}, 'pure_error': {'df': df_pe, 'ss': pe, 'ms': ms_pe}}
    return {'coefficients': coefs, 's': float(np.sqrt(mse)), 'r_sq': 1 - sse / sst, 'r_sq_adj': 1 - sse / dfe / (sst / (n - 1)), 'press': press, 'r_sq_pred': 1 - press / sst, 'anova': [reg] + anova, 'error': {'df': dfe, 'ss': sse, 'ms': mse}, 'total': {'df': n - 1, 'ss': sst}, 'lack_of_fit': lof, 'fits': (X @ beta).tolist(), 'residuals': e.tolist()}

