from __future__ import annotations
from itertools import product
import numpy as np
from scipy import optimize

def desirability(y: float, goal: str, lower: float | None, target: float, upper: float | None, weight: float=1.0) -> float:
    if goal == 'minimize':
        if y <= target:
            return 1.0
        if y >= upper:
            return 0.0
        return ((upper - y) / (upper - target)) ** weight
    if goal == 'maximize':
        if y >= target:
            return 1.0
        if y <= lower:
            return 0.0
        return ((y - lower) / (target - lower)) ** weight
    if goal == 'target':
        if y < lower or y > upper:
            return 0.0
        if y <= target:
            return ((y - lower) / (target - lower)) ** weight if target > lower else 1.0
        return ((upper - y) / (upper - target)) ** weight if upper > target else 1.0
    raise ValueError(f'Bilinmeyen hedef: {goal}')

def _predictor(model: dict, names: list[str]):
    idx = {n: i for i, n in enumerate(names)}
    terms = [[idx[v] for v in t] for t in model['terms']]
    coef = np.asarray(model['coefficients'], dtype=float)

    def f(x):
        return float(sum((c * np.prod([x[i] for i in t]) if t else c for c, t in zip(coef, terms))))
    return f

def optimize_responses(variables: list[dict], responses: list[dict], mixture_total: float | None=None, n_starts: int=7) -> dict:
    names = [v['name'] for v in variables]
    lo = np.array([float(v['low']) for v in variables])
    hi = np.array([float(v['high']) for v in variables])
    preds = [_predictor(r['model'], names) for r in responses]
    imp = np.array([float(r.get('importance', 1.0)) for r in responses])

    def comp(x):
        ds = [desirability(p(x), r['goal'], r.get('lower'), r['target'], r.get('upper'), r.get('weight', 1.0)) for p, r in zip(preds, responses)]
        if min(ds) <= 0:
            return (0.0, ds)
        return (float(np.exp((imp * np.log(ds)).sum() / imp.sum())), ds)

    def smooth(x):
        return -comp(x)[0]
    cons = []
    if mixture_total is not None:
        cons.append({'type': 'eq', 'fun': lambda x: x.sum() - mixture_total})
    k = len(names)
    grid = [np.linspace(0, 1, n_starts)] * k if k <= 3 else [np.linspace(0, 1, 3)] * k
    starts = []
    for g in product(*grid):
        x = lo + np.array(g) * (hi - lo)
        if mixture_total is not None:
            s = x.sum()
            if s <= 0:
                continue
            x = x * mixture_total / s
            if np.any(x < lo - 1e-12) or np.any(x > hi + 1e-12):
                continue
        starts.append(x)
    if mixture_total is not None:
        starts.append(np.full(k, mixture_total / k))
    best_x, best_d = (None, -1.0)
    for x0 in starts:
        val0, _ = comp(x0)
        if val0 > best_d:
            best_x, best_d = (x0.copy(), val0)
        res = optimize.minimize(smooth, x0, method='SLSQP', bounds=list(zip(lo, hi)), constraints=cons, options={'ftol': 1e-14, 'maxiter': 500})
        x = np.clip(res.x, lo, hi)
        if mixture_total is not None and abs(x.sum() - mixture_total) > 1e-08:
            continue
        val, _ = comp(x)
        if val > best_d + 1e-12:
            best_x, best_d = (x, val)
    d, ds = comp(best_x)
    return {'settings': {n: float(v) for n, v in zip(names, best_x)}, 'responses': [{'name': r.get('name', f'Y{i + 1}'), 'fit': p(best_x), 'desirability': di} for i, (p, r, di) in enumerate(zip(preds, responses, ds))], 'composite_desirability': d}

