from __future__ import annotations
from dataclasses import dataclass
from .factorial import LETTERS
CCD_CENTER = {2: 5, 3: 6, 4: 7, 5: 10, 6: 15}
BB_CENTER = {3: 3, 4: 3, 5: 6, 6: 6, 7: 6}
BB_PAIRS = {3: [(0, 1), (0, 2), (1, 2)], 4: [(0, 1), (2, 3), (0, 3), (1, 2), (0, 2), (1, 3)]}

@dataclass
class RSMDesign:
    factors: list[str]
    kind: str
    alpha: float | None
    point_type: list[int]
    matrix: list[list[float]]

def create_ccd(k: int, alpha: float | None=None, center_points: int | None=None) -> RSMDesign:
    names = list(LETTERS[:k])
    a = alpha if alpha is not None else (2 ** k) ** 0.25
    rows, pt = ([], [])
    for i in range(2 ** k):
        rows.append([1.0 if i >> j & 1 else -1.0 for j in range(k)])
        pt.append(1)
    for j in range(k):
        for sgn in (-1, 1):
            r = [0.0] * k
            r[j] = sgn * a
            rows.append(r)
            pt.append(-1)
    nc = CCD_CENTER.get(k, 6) if center_points is None else center_points
    rows += [[0.0] * k for _ in range(nc)]
    pt += [0] * nc
    return RSMDesign(names, 'CCD', a, pt, rows)

def create_box_behnken(k: int, center_points: int | None=None) -> RSMDesign:
    if k not in BB_PAIRS:
        raise ValueError('Box-Behnken şimdilik 3 ve 4 faktör için tanımlı.')
    names = list(LETTERS[:k])
    rows, pt = ([], [])
    for i, j in BB_PAIRS[k]:
        for b in (-1, 1):
            for a in (-1, 1):
                r = [0.0] * k
                r[i], r[j] = (float(a), float(b))
                rows.append(r)
                pt.append(2)
    nc = BB_CENTER.get(k, 3) if center_points is None else center_points
    rows += [[0.0] * k for _ in range(nc)]
    pt += [0] * nc
    return RSMDesign(names, 'Box-Behnken', None, pt, rows)

qualistat/doe/taguchi.py:
from __future__ import annotations
import math
import numpy as np

def sn_ratio(values, kind: str) -> float:
    y = np.asarray(values, dtype=float)
    if kind == 'larger':
        return float(-10 * math.log10(np.mean(1 / y ** 2)))
    if kind == 'smaller':
        return float(-10 * math.log10(np.mean(y ** 2)))
    s2 = float(y.var(ddof=1))
    if kind == 'nominal1':
        return float(-10 * math.log10(s2))
    return float(10 * math.log10(y.mean() ** 2 / s2))

def _response_table(matrix, values, names):
    M = np.asarray(matrix)
    v = np.asarray(values, dtype=float)
    table = {}
    for j, name in enumerate(names):
        levels = sorted(set(M[:, j].tolist()))
        means = [float(v[M[:, j] == lv].mean()) for lv in levels]
        table[name] = {'levels': levels, 'means': means, 'delta': max(means) - min(means)}
    order = sorted(names, key=lambda n: -table[n]['delta'])
    for n in names:
        table[n]['rank'] = order.index(n) + 1
    return table

def taguchi_analysis(matrix, responses: list[list[float]], factor_names: list[str], kind: str='nominal2') -> dict:
    sn = [sn_ratio(r, kind) for r in responses]
    means = [float(np.mean(r)) for r in responses]
    sds = [float(np.std(r, ddof=1)) if len(r) > 1 else None for r in responses]
    return {'sn': sn, 'means': means, 'stdevs': sds, 'sn_table': _response_table(matrix, sn, factor_names), 'mean_table': _response_table(matrix, means, factor_names)}

