from __future__ import annotations
import math
from dataclasses import dataclass, field
import numpy as np
from scipy import stats

@dataclass
class Agreement:
    appraiser: str | None
    inspected: int
    matched: int
    percent: float
    ci: tuple[float, float]

@dataclass
class KappaRow:
    appraiser: str | None
    response: str
    kappa: float | None
    se: float | None
    z: float | None
    p_value: float | None

@dataclass
class Disagreement:
    appraiser: str
    counts: dict

@dataclass
class KendallRow:
    appraiser: str | None
    coef: float
    se: float | None
    z: float | None
    p_value: float
    df: int | None = None
    chi2: float | None = None

@dataclass
class AttributeAgreementResult:
    categories: list[str]
    appraisers: list[str]
    trials: int
    within: list[Agreement] = field(default_factory=list)
    within_kappa: list[KappaRow] = field(default_factory=list)
    within_kendall: list[KendallRow] = field(default_factory=list)
    vs_standard: list[Agreement] = field(default_factory=list)
    disagreement: list[Disagreement] = field(default_factory=list)
    vs_standard_kappa: list[KappaRow] = field(default_factory=list)
    vs_standard_kendall: list[KendallRow] = field(default_factory=list)
    between: Agreement | None = None
    between_kappa: list[KappaRow] = field(default_factory=list)
    between_kendall: KendallRow | None = None
    all_vs_standard: Agreement | None = None
    all_vs_standard_kappa: list[KappaRow] = field(default_factory=list)
    all_vs_standard_kendall: KendallRow | None = None

def _cp(x: int, n: int, conf: float=0.95) -> tuple[float, float]:
    a = 1 - conf
    if x == 0:
        return (0.0, 100 * (1 - a ** (1 / n)))
    if x == n:
        return (100 * a ** (1 / n), 100.0)
    lo = stats.beta.ppf(a / 2, x, n - x + 1)
    hi = stats.beta.ppf(1 - a / 2, x + 1, n - x)
    return (100 * float(lo), 100 * float(hi))

def _agreement(who, matched: int, n: int) -> Agreement:
    return Agreement(who, n, matched, 100 * matched / n, _cp(matched, n))

def _fleiss(ratings: np.ndarray, cats: list[str]):
    n, m = ratings.shape
    x = np.array([[(row == c).sum() for c in cats] for row in ratings], dtype=float)
    p = x.sum(axis=0) / (n * m)
    q = 1 - p
    denom = n * m * (m - 1)
    per = []
    for j in range(len(cats)):
        if p[j] * q[j] == 0:
            per.append((None, None))
            continue
        kj = 1 - (x[:, j] * (m - x[:, j])).sum() / (denom * p[j] * q[j])
        per.append((float(kj), 2 / denom))
    pq = (p * q).sum()
    if pq == 0:
        return (per, (None, None))
    k = 1 - (n * m * m - (x * x).sum()) / (denom * pq)
    var = 2 / (pq * pq * denom) * (pq * pq - (p * q * (q - p)).sum())
    return (per, (float(k), float(var)))

def _kappa_rows(who, cats, items) -> list[KappaRow]:
    t = len(items)

    def row(label, vals):
        if any((k is None for k, _ in vals)):
            return KappaRow(who, label, None, None, None, None)
        k = sum((k for k, _ in vals)) / t
        se = math.sqrt(sum((v for _, v in vals))) / t
        z = k / se
        return KappaRow(who, label, k, se, z, float(stats.norm.sf(z)))
    out = [row(c, [it[0][j] for it in items]) for j, c in enumerate(cats)]
    if len(cats) > 2:
        out.append(row('Overall', [it[1] for it in items]))
    return out

def _kendall_w(ranks: np.ndarray) -> KendallRow:
    n, m = ranks.shape
    r = np.column_stack([stats.rankdata(ranks[:, j]) for j in range(m)])
    s = ((r.sum(axis=1) - m * (n + 1) / 2) ** 2).sum()
    ties = 0.0
    for j in range(m):
        _, cnt = np.unique(ranks[:, j], return_counts=True)
        ties += (cnt ** 3 - cnt).sum()
    w = 12 * s / (m * m * (n ** 3 - n) - m * ties)
    chi2 = m * (n - 1) * w
    return KendallRow(None, float(w), None, None, float(stats.chi2.sf(chi2, n - 1)), n - 1, float(chi2))

def _kendall_tau_b(a: np.ndarray, b: np.ndarray) -> tuple[float, float]:
    n = len(a)
    tau = stats.kendalltau(a, b, variant='b').statistic
    return (float(tau), 2 * (2 * n + 5) / (9 * n * (n - 1)))

def _tau_row(who, taus, n: int) -> KendallRow:
    t = len(taus)
    tau = sum((x for x, _ in taus)) / t
    se = math.sqrt(sum((v for _, v in taus))) / t
    corr = 1 / (t * n * (n - 1) / 2)
    z = math.copysign(max(abs(tau) - corr, 0.0), tau) / se
    return KendallRow(who, tau, se, z, float(stats.norm.sf(z)))

def attribute_agreement(samples, appraisers, responses, standard=None, ordinal: bool=False, categories: list[str] | None=None) -> AttributeAgreementResult:
    samples = [str(s) for s in samples]
    appraisers = [str(a) for a in appraisers]
    responses = [str(r) for r in responses]
    sl = list(dict.fromkeys(samples))
    al = list(dict.fromkeys(appraisers))
    if categories is None:
        cats = sorted(set(responses) | (set(map(str, standard)) if standard is not None else set()))
        try:
            cats = sorted(cats, key=float)
        except ValueError:
            pass
    else:
        cats = list(categories)
    n = len(sl)
    cube: dict[str, list[list[str]]] = {a: [[] for _ in sl] for a in al}
    std = {}
    for i, (s, a, r) in enumerate(zip(samples, appraisers, responses)):
        cube[a][sl.index(s)].append(r)
        if standard is not None:
            std[s] = str(standard[i])
    trials = min((len(v) for a in al for v in cube[a]))
    arr = {a: np.array([v[:trials] for v in cube[a]], dtype=object) for a in al}
    stdv = np.array([std[s] for s in sl], dtype=object) if standard is not None else None
    code = {c: k for k, c in enumerate(cats)}
    res = AttributeAgreementResult(cats, al, trials)
    if trials > 1:
        for a in al:
            same = sum((len(set(row)) == 1 for row in arr[a]))
            res.within.append(_agreement(a, same, n))
            res.within_kappa += _kappa_rows(a, cats, [_fleiss(arr[a], cats)])
            if ordinal:
                kw = _kendall_w(np.vectorize(code.get)(arr[a]).astype(float))
                kw.appraiser = a
                res.within_kendall.append(kw)
    if stdv is not None:
        all_items = []
        for a in al:
            ok = sum((all((v == stdv[i] for v in arr[a][i])) for i in range(n)))
            res.vs_standard.append(_agreement(a, ok, n))
            counts = {}
            for c_r in cats:
                for c_s in cats:
                    if c_r == c_s:
                        continue
                    k = sum((set(arr[a][i]) == {c_r} and stdv[i] == c_s for i in range(n)))
                    base = sum((stdv[i] == c_s for i in range(n)))
                    counts[f'{c_r} / {c_s}'] = (k, 100 * k / base if base else 0.0)
            if trials > 1:
                mixed = sum((len(set(arr[a][i])) > 1 for i in range(n)))
                counts['Mixed'] = (mixed, 100 * mixed / n)
            res.disagreement.append(Disagreement(a, counts))
            items = [_fleiss(np.column_stack([arr[a][:, t], stdv]), cats) for t in range(trials)]
            all_items += items
            res.vs_standard_kappa += _kappa_rows(a, cats, items)
            if ordinal:
                sc = np.vectorize(code.get)(stdv).astype(float)
                taus = [_kendall_tau_b(np.vectorize(code.get)(arr[a][:, t]).astype(float), sc) for t in range(trials)]
                res.vs_standard_kendall.append(_tau_row(a, taus, n))
        res.all_vs_standard_kappa = _kappa_rows(None, cats, all_items)
        ok = sum((all((v == stdv[i] for a in al for v in arr[a][i])) for i in range(n)))
        res.all_vs_standard = _agreement(None, ok, n)
        if ordinal:
            sc = np.vectorize(code.get)(stdv).astype(float)
            taus = [_kendall_tau_b(np.vectorize(code.get)(arr[a][:, t]).astype(float), sc) for a in al for t in range(trials)]
            res.all_vs_standard_kendall = _tau_row(None, taus, n)
    if len(al) > 1:
        allr = np.column_stack([arr[a] for a in al])
        same = sum((len(set(row)) == 1 for row in allr))
        res.between = _agreement(None, same, n)
        res.between_kappa = _kappa_rows(None, cats, [_fleiss(allr, cats)])
        if ordinal:
            res.between_kendall = _kendall_w(np.vectorize(code.get)(allr).astype(float))
    return res

