from __future__ import annotations
import numpy as np

def _satterthwaite_df(p: int, o: int, r: int, repro_share: float) -> float:
    var_o, var_e = (repro_share, 1 - repro_share)
    df_e = p * o * r - p - o + 1
    a, b = (1 - 1 / (p * r), 1 / (p * r))
    ms_o = var_e + p * r * var_o
    den = (a * var_e) ** 2 / df_e + ((b * ms_o) ** 2 / (o - 1) if o > 1 else 0.0)
    return 1.0 / den if den > 0 else float(df_e)

def simulate_estimates(p: int, o: int, r: int, pct_grr: float, repro_share: float, reps: int=4000, seed: int=20261018):
    rng = np.random.default_rng(seed + 7919 * p + 104729 * o + 1299709 * r)
    var = (pct_grr / 100) ** 2
    var_o, var_e = (repro_share * var, (1 - repro_share) * var)
    y = rng.normal(0, 1.0, (reps, p, 1, 1)) + rng.normal(0, np.sqrt(var_o), (reps, 1, o, 1)) + rng.normal(0, np.sqrt(var_e), (reps, p, o, r))
    gm = y.mean(axis=(1, 2, 3))
    ss_o = p * r * ((y.mean(axis=(1, 3)) - gm[:, None]) ** 2).sum(axis=1)
    ss_p = o * r * ((y.mean(axis=(2, 3)) - gm[:, None]) ** 2).sum(axis=1)
    ss_t = ((y - gm[:, None, None, None]) ** 2).sum(axis=(1, 2, 3))
    ms_err = (ss_t - ss_o - ss_p) / (p * o * r - p - o + 1)
    var_op = np.maximum((ss_o / (o - 1) - ms_err) / (p * r), 0) if o > 1 else 0.0
    return 100 * np.sqrt(ms_err + var_op)

def gage_rr_sample_size(pct_grr: float, repro_share: float=0.3, limit: float=30.0, target: float=0.9, parts=(5, 10, 15, 20, 25, 30), operators=(2, 3, 4), replicates=(2, 3, 4), reps: int=4000, criterion: str='probability') -> dict:
    if criterion not in ('probability', 'upper'):
        raise ValueError("Ölçüt 'probability' veya 'upper' olmalı.")
    if not 0 < pct_grr < 100:
        raise ValueError('Beklenen %GRR 0 ile 100 arasında olmalı.')
    if not 0 <= repro_share < 1:
        raise ValueError('Yeniden üretilebilirlik payı 0 ile 1 arasında olmalı.')
    if not 0 < target < 1:
        raise ValueError('Hedef olasılık 0 ile 1 arasında olmalı.')
    if not 0 < limit <= 100:
        raise ValueError('Karar eşiği 0 ile 100 arasında olmalı.')
    if min(operators) < 2 or min(replicates) < 2 or min(parts) < 2:
        raise ValueError('En az 2 parça, 2 operatör ve 2 tekrar gerekli.')
    rows = []
    for o in operators:
        for r in replicates:
            for p in parts:
                est = simulate_estimates(p, o, r, pct_grr, repro_share, reps)
                lo, med, hi = np.percentile(est, [2.5, 50, 97.5])
                prob = float((est < limit).mean())
                rows.append({'parts': p, 'operators': o, 'replicates': r, 'n': p * o * r, 'df_grr': _satterthwaite_df(p, o, r, repro_share), 'lower': float(lo), 'median': float(med), 'upper': float(hi), 'prob_below': prob, 'meets': prob >= target if criterion == 'probability' else bool(hi < limit)})
    rows.sort(key=lambda d: (d['n'], -d['prob_below']))
    ok = [d for d in rows if d['meets']]
    aiag = next((d for d in rows if (d['parts'], d['operators'], d['replicates']) == (10, 3, 3)), None)
    return {'pct_grr': pct_grr, 'repro_share': repro_share, 'limit': limit, 'target': target, 'reps': reps, 'criterion': criterion, 'designs': rows, 'recommended': ok[0] if ok else None, 'aiag_10x3x3': aiag, 'note': None if pct_grr < limit else 'Beklenen %GRR eşiğin üstünde: hiçbir plan kabul edilebilir sonucu güvenle veremez.'}

