from __future__ import annotations
import numpy as np
from scipy import optimize, stats

def _levels(v):
    u = list(dict.fromkeys(v))
    try:
        return sorted(u, key=float)
    except (TypeError, ValueError):
        return sorted(u, key=str)

def stability_study(response, time, batch=None, lower_spec: float | None=None, upper_spec: float | None=None, confidence: float=95.0, alpha: float=0.25, t_max: float | None=None, percent: float=50.0) -> dict:
    if not 0 < percent < 100:
        raise ValueError('Yanıt yüzdesi 0 ile 100 arasında olmalı.')
    if lower_spec is None and upper_spec is None:
        raise ValueError('En az bir spesifikasyon sınırı gerekli.')
    keep = [i for i in range(len(response)) if response[i] is not None and time[i] is not None and (batch is None or batch[i] is not None)]
    y = np.array([float(response[i]) for i in keep])
    t = np.array([float(time[i]) for i in keep])
    b = None if batch is None else [str(batch[i]) for i in keep]
    lev = _levels(b) if b is not None else []
    n = len(y)

    def eff(level):
        return np.array([(1.0 if level == m else 0.0) - (1.0 if level == lev[-1] else 0.0) for m in lev[:-1]])
    E = np.array([eff(v) for v in b]) if b is not None else np.zeros((n, 0))

    def design(model):
        cols = [np.ones(n), t]
        if model in ('intercepts', 'full'):
            cols += [E[:, j] for j in range(E.shape[1])]
        if model == 'full':
            cols += [t * E[:, j] for j in range(E.shape[1])]
        return np.column_stack(cols)

    def fit(X):
        beta, *_ = np.linalg.lstsq(X, y, rcond=None)
        r = y - X @ beta
        return (beta, float(r @ r))
    sst = float(((y - y.mean()) ** 2).sum())
    selection = []
    model = 'common'
    if b is not None and len(lev) > 1:
        k = len(lev) - 1
        _, sse1 = fit(design('common'))
        _, sse2 = fit(design('intercepts'))
        _, sse3 = fit(design('full'))
        df3 = n - 2 - 2 * k

        def tab(rows, sse, dfe):
            mse = sse / dfe
            out = []
            for src, df, ss in rows:
                f = ss / df / mse
                out.append({'source': src, 'df': df, 'seq_ss': ss, 'seq_ms': ss / df, 'f': f, 'p': float(stats.f.sf(f, df, dfe))})
            out.append({'source': 'Error', 'df': dfe, 'seq_ss': sse, 'seq_ms': mse})
            out.append({'source': 'Total', 'df': n - 1, 'seq_ss': sst})
            return out
        t1 = tab([('Time', 1, sst - sse1), ('Batch', k, sse1 - sse2), ('Time*Batch', k, sse2 - sse3)], sse3, df3)
        selection.append(t1)
        model = 'full'
        if t1[2]['p'] > alpha:
            model = 'intercepts'
            t2 = tab([('Time', 1, sst - sse1), ('Batch', k, sse1 - sse2)], sse2, n - 2 - k)
            selection.append(t2)
            if t2[1]['p'] > alpha:
                model = 'common'
    X = design(model)
    beta, sse = fit(X)
    p = X.shape[1]
    dfe = n - p
    s2 = sse / dfe
    XtXi = np.linalg.inv(X.T @ X)
    se = np.sqrt(np.diag(XtXi) * s2)
    H = X @ XtXi @ X.T
    e = y - X @ beta
    press = float(((e / (1 - np.diag(H))) ** 2).sum())
    names = ['Constant', 'Time'] + [f'Batch {lv}' for lv in lev[:-1]] * (model in ('intercepts', 'full')) + [f'Time*Batch {lv}' for lv in lev[:-1]] * (model == 'full')
    coefs = [{'term': nm, 'coef': float(c), 'se': float(s), 't': float(c / s), 'p': float(2 * stats.t.sf(abs(c / s), dfe))} for nm, c, s in zip(names, beta, se)]
    tq = stats.t.ppf(confidence / 100, dfe)
    zc = stats.norm.ppf(confidence / 100)
    zp = stats.norm.ppf(percent / 100)
    mean_method = abs(percent - 50.0) < 1e-12
    horizon = t_max or max(10 * float(t.max()), 1.0)

    def row(level, tt):
        x = [1.0, tt]
        if model in ('intercepts', 'full'):
            x += list(eff(level))
        if model == 'full':
            x += list(tt * eff(level))
        return np.array(x)

    def life(level):
        res = []
        for spec, sign in ((lower_spec, -1), (upper_spec, 1)):
            if spec is None:
                continue

            def g(tt):
                x = row(level, tt)
                h = x @ XtXi @ x
                if mean_method:
                    return x @ beta + sign * tq * np.sqrt(s2 * h) - spec
                return x @ beta + sign * (zp * np.sqrt(s2) + zc * np.sqrt(s2 * h + zp * zp * s2 / (2 * dfe))) - spec
            g0 = g(0.0)
            if sign < 0 and g0 <= 0 or (sign > 0 and g0 >= 0):
                res.append(0.0)
                continue
            if sign < 0 and g(horizon) > 0 or (sign > 0 and g(horizon) < 0):
                res.append(float('inf'))
                continue
            res.append(float(optimize.brentq(g, 0.0, horizon, xtol=1e-12)))
        return min(res)
    if model == 'common':
        shelf = {'overall': life(lev[0] if lev else None)}
        per_batch = []
    else:
        per_batch = [{'batch': lv, 'shelf_life': life(lv)} for lv in lev]
        shelf = {'overall': min((r['shelf_life'] for r in per_batch))}
    return {'model': model, 'selection': selection, 'coefficients': coefs, 's': float(np.sqrt(s2)), 'r_sq': 1 - sse / sst, 'r_sq_adj': 1 - s2 / (sst / (n - 1)), 'r_sq_pred': 1 - press / sst, 'dfe': dfe, 'percent': percent, 'shelf_life': shelf['overall'], 'batches': per_batch}

qualistat/msa/vda5.py:
from __future__ import annotations
import math
import numpy as np
SQRT3, SQRT12 = (math.sqrt(3.0), math.sqrt(12.0))
_LABELS = {'CAL': 'Kalibrasyon (referans)', 'RE': 'Çözünürlük', 'EVR': 'Tekrarlanabilirlik (referans parça)', 'BI': 'Sistematik sapma (bias)', 'LIN': 'Doğrusallık', 'MS_REST': 'Diğer (ölçüm sistemi)', 'EVO': 'Tekrarlanabilirlik (parçalar)', 'AV': 'Yeniden üretilebilirlik (operatör)', 'GV': 'Yeniden üretilebilirlik (ölçüm sistemi)', 'IA': 'Etkileşim (parça × operatör)', 'STAB': 'Kararlılık', 'OBJ': 'Parça homojensizliği', 'T': 'Sıcaklık', 'MP_REST': 'Diğer (ölçüm prosesi)'}
_MS_KEYS = ('CAL', 'RE', 'EVR', 'BI', 'LIN', 'MS_REST')
_MP_KEYS = ('CAL', 'RE', 'EVR', 'EVO', 'BI', 'LIN', 'AV', 'GV', 'IA', 'STAB', 'OBJ', 'T', 'MP_REST')

def vda5(tolerance: float, resolution: float, k: float=2.0, u_cal: float | None=None, U_cal: float | None=None, k_cal: float=2.0, reference: float | None=None, reference_values=None, gage: dict | None=None, components: dict[str, float] | None=None, q_ms_max: float=15.0, q_mp_max: float=30.0, q_re_max: float=5.0) -> dict:
    if not (tolerance and tolerance > 0):
        raise ValueError('Tolerans pozitif olmalı.')
    if not (resolution and resolution > 0):
        raise ValueError('Çözünürlük pozitif olmalı.')
    u: dict[str, float] = {}
    how: dict[str, str] = {}
    u['RE'] = resolution / SQRT12
    how['RE'] = f'RE / √12 = {resolution:g} / √12'
    if u_cal is not None:
        u['CAL'], how['CAL'] = (float(u_cal), 'girildi')
    elif U_cal is not None:
        u['CAL'], how['CAL'] = (float(U_cal) / k_cal, f'U_CAL / k = {U_cal:g} / {k_cal:g}')
    ref_stats = None
    if reference_values is not None and len([v for v in reference_values if v is not None]) >= 2:
        x = np.array([float(v) for v in reference_values if v is not None])
        s = float(x.std(ddof=1))
        u['EVR'], how['EVR'] = (s, f's, n = {len(x)}')
        ref_stats = {'n': int(len(x)), 'mean': float(x.mean()), 's': s}
        if reference is not None:
            bi = float(x.mean() - reference)
            u['BI'], how['BI'] = (abs(bi) / SQRT3, '|x̄ − x_ref| / √3')
            ref_stats['bias'] = bi
    gage_stats = None
    if gage:
        from .gage_rr import gage_rr_anova
        r = gage_rr_anova(gage['parts'], gage['operators'], gage['y'], alpha_interaction=1.0)
        comp = {c.source: c.var_comp for c in r.components}
        u['EVO'], how['EVO'] = (math.sqrt(comp['Repeatability']), 'ANOVA tekrarlanabilirlik')
        u['AV'], how['AV'] = (math.sqrt(comp.get('Operator', 0.0)), 'ANOVA operatör')
        ia = next((v for kk, v in comp.items() if '*' in kk), 0.0)
        u['IA'], how['IA'] = (math.sqrt(ia), 'ANOVA etkileşim')
        gage_stats = {'parts': len(set(gage['parts'])), 'operators': len(set(gage['operators'])), 'n': len(gage['y']), 'p_interaction': r.anova_with_interaction[2].p}
    for key, val in (components or {}).items():
        if val is None:
            continue
        if key not in _LABELS:
            raise ValueError(f'Bilinmeyen bileşen: {key}')
        if val < 0:
            raise ValueError(f'{_LABELS[key]} belirsizliği negatif olamaz.')
        u[key], how[key] = (float(val), 'girildi')

    def combine(keys, max_group):
        terms = {kk: u.get(kk, 0.0) for kk in keys}
        dom = max(max_group, key=lambda kk: terms.get(kk, 0.0))
        used = [kk for kk in keys if kk not in max_group or kk == dom]
        var = sum((terms[kk] ** 2 for kk in used))
        return (math.sqrt(var), used, dom)
    u_ms, used_ms, dom_ms = combine(_MS_KEYS, ('EVR', 'RE'))
    u_mp, used_mp, dom_mp = combine(_MP_KEYS, ('EVR', 'EVO', 'RE'))
    U_ms, U_mp = (k * u_ms, k * u_mp)
    q_ms, q_mp = (2 * U_ms / tolerance * 100, 2 * U_mp / tolerance * 100)
    q_re = resolution / tolerance * 100

    def rows(keys, used, total):
        out = []
        for kk in keys:
            if kk not in u:
                continue
            out.append({'key': kk, 'label': _LABELS[kk], 'u': u[kk], 'method': how.get(kk, ''), 'used': kk in used, 'share': u[kk] ** 2 / total ** 2 * 100 if kk in used and total > 0 else None})
        return out
    return {'tolerance': tolerance, 'resolution': resolution, 'k': k, 'ms': {'u': u_ms, 'U': U_ms, 'q': q_ms, 'q_max': q_ms_max, 'capable': q_ms <= q_ms_max, 'tol_min': 2 * U_ms / (q_ms_max / 100), 'dominant_repeat': dom_ms, 'components': rows(_MS_KEYS, used_ms, u_ms)}, 'mp': {'u': u_mp, 'U': U_mp, 'q': q_mp, 'q_max': q_mp_max, 'capable': q_mp <= q_mp_max, 'tol_min': 2 * U_mp / (q_mp_max / 100), 'dominant_repeat': dom_mp, 'components': rows(_MP_KEYS, used_mp, u_mp)}, 'resolution_check': {'q_re': q_re, 'q_max': q_re_max, 'ok': q_re <= q_re_max}, 'reference': ref_stats, 'gage': gage_stats}

qualistat/power.py:
from __future__ import annotations
import math
from typing import Callable
import numpy as np
from scipy import optimize, stats
N = stats.norm

def _two_sided_normal(effect: float, s0: float, s1: float, alpha: float, alt: int) -> float:
    if alt == 0:
        z = N.ppf(1 - alpha / 2)
        return float(N.cdf((effect - z * s0) / s1) + N.cdf((-effect - z * s0) / s1))
    z = N.ppf(1 - alpha)
    return float(N.cdf((alt * effect - z * s0) / s1))

def power_z(diff: float, n: float, sigma: float, alpha: float=0.05, alt: int=0) -> float:
    return _two_sided_normal(diff * math.sqrt(n) / sigma, 1.0, 1.0, alpha, alt)

def _power_t(ncp: float, df: float, alpha: float, alt: int) -> float:
    if alt == 0:
        t = stats.t.ppf(1 - alpha / 2, df)
        return float(stats.nct.sf(t, df, ncp) + stats.nct.cdf(-t, df, ncp))
    t = stats.t.ppf(1 - alpha, df)
    return float(stats.nct.sf(t, df, alt * ncp))

def power_t1(diff: float, n: float, sigma: float, alpha: float=0.05, alt: int=0) -> float:
    return _power_t(diff * math.sqrt(n) / sigma, n - 1, alpha, alt)

def power_t2(diff: float, n: float, sigma: float, alpha: float=0.05, alt: int=0) -> float:
    return _power_t(diff / (sigma * math.sqrt(2 / n)), 2 * n - 2, alpha, alt)

def power_p1(p: float, n: float, p0: float, alpha: float=0.05, alt: int=0) -> float:
    return _two_sided_normal(p - p0 if alt else abs(p - p0), math.sqrt(p0 * (1 - p0) / n), math.sqrt(p * (1 - p) / n), alpha, alt)

def power_p2(p: float, n: float, p_base: float, alpha: float=0.05, alt: int=0) -> float:
    pb = (p + p_base) / 2
    s0 = math.sqrt(2 * pb * (1 - pb) / n)
    s1 = math.sqrt((p * (1 - p) + p_base * (1 - p_base)) / n)
    return _two_sided_normal(p - p_base if alt else abs(p - p_base), s0, s1, alpha, alt)

def power_anova(max_diff: float, n: float, k: int, sigma: float, alpha: float=0.05) -> float:
    lam = n * max_diff ** 2 / (2 * sigma ** 2)
    df1, df2 = (k - 1, k * (n - 1))
    return float(stats.ncf.sf(stats.f.ppf(1 - alpha, df1, df2), df1, df2, lam))

def power_var1(ratio: float, n: float, alpha: float=0.05, alt: int=0, sd: bool=False) -> float:
    r = ratio ** 2 if sd else ratio
    df = n - 1
    if alt == 0:
        return float(stats.chi2.sf(stats.chi2.ppf(1 - alpha / 2, df) / r, df) + stats.chi2.cdf(stats.chi2.ppf(alpha / 2, df) / r, df))
    if alt == 1:
        return float(stats.chi2.sf(stats.chi2.ppf(1 - alpha, df) / r, df))
    return float(stats.chi2.cdf(stats.chi2.ppf(alpha, df) / r, df))

def power_var2_f(ratio: float, n: float, alpha: float=0.05, alt: int=0, sd: bool=False) -> float:
    r = ratio ** 2 if sd else ratio
    df = n - 1
    if alt == 0:
        return float(stats.f.cdf(stats.f.ppf(alpha / 2, df, df) / r, df, df) + stats.f.sf(stats.f.ppf(1 - alpha / 2, df, df) / r, df, df))
    if alt == 1:
        return float(stats.f.sf(stats.f.ppf(1 - alpha, df, df) / r, df, df))
    return float(stats.f.cdf(stats.f.ppf(alpha, df, df) / r, df, df))

def power_rate1(rate: float, n: float, rate0: float, alpha: float=0.05, alt: int=0, length: float=1.0) -> float:
    e = n * length
    return _two_sided_normal(rate - rate0 if alt else abs(rate - rate0), math.sqrt(rate0 / e), math.sqrt(rate / e), alpha, alt)

def power_rate2(rate: float, n: float, rate_base: float, alpha: float=0.05, alt: int=0, length: float=1.0) -> float:
    e = n * length
    rb = (rate + rate_base) / 2
    return _two_sided_normal(rate - rate_base if alt else abs(rate - rate_base), math.sqrt(2 * rb / e), math.sqrt((rate + rate_base) / e), alpha, alt)
POWER_FUNCS: dict[str, Callable] = {'z': power_z, 't1': power_t1, 'paired': power_t1, 't2': power_t2, 'p1': power_p1, 'p2': power_p2, 'anova': power_anova, 'var1': power_var1, 'var2': power_var2_f, 'rate1': power_rate1, 'rate2': power_rate2}
MIN_N = {'t1': 2, 'paired': 2, 't2': 2, 'anova': 2, 'var1': 2, 'var2': 2}

def sample_size(fn: Callable, target: float, min_n: int=1, **kw) -> tuple[int, float]:
    lo = min_n
    if fn(n=lo, **kw) >= target:
        return (lo, fn(n=lo, **kw))
    hi = lo * 2
    while fn(n=hi, **kw) < target:
        hi *= 2
        if hi > 10 ** 8:
            raise ValueError('Hedef güce ulaşılamıyor.')
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if fn(n=mid, **kw) >= target:
            hi = mid
        else:
            lo = mid
    return (hi, fn(n=hi, **kw))

def solve_effect(fn: Callable, target: float, key: str, lo: float, hi: float, **kw) -> float:
    g = lambda v: fn(**{key: v}, **kw) - target
    a = lo
    b = min(hi, max(2 * lo, lo + (hi - lo) * 1e-06, 0.001 if lo < 1 else lo * 1.001))
    while g(b) < 0:
        a, b = (b, min(hi, b * 2 if b > 0 else 1.0))
        if b >= hi:
            break
    return float(optimize.brentq(g, a, b, xtol=1e-12))

def _ncf_power(lam: float, dfn: float, dfe: float, alpha: float) -> float:
    if dfe <= 0:
        raise ValueError('Hata için serbestlik derecesi yok.')
    return float(stats.ncf.sf(stats.f.ppf(1 - alpha, dfn, dfe), dfn, dfe, lam))

def power_two_level(corner_points: int, reps: int, effect: float, sigma: float, center_points: int=0, alpha: float=0.05, omit: int=0, fit_center: bool=False, blocks: int=1, fit_blocks: bool=False) -> dict:
    n_corner = corner_points * reps
    total = n_corner + center_points * blocks
    terms = corner_points - 1 - omit + (1 if fit_center else 0) + (blocks - 1 if fit_blocks else 0)
    dfe = total - 1 - terms
    lam = (effect / 2) ** 2 * n_corner / sigma ** 2
    return {'total_runs': total, 'df_error': dfe, 'power': _ncf_power(lam, 1, dfe, alpha)}

def power_plackett_burman(factors: int, runs: int, reps: int, effect: float, sigma: float, center_points: int=0, alpha: float=0.05, omit: int=0, fit_center: bool=False) -> dict:
    n_corner = runs * reps
    total = n_corner + center_points
    terms = factors - omit + (1 if fit_center else 0)
    dfe = total - 1 - terms
    lam = (effect / 2) ** 2 * n_corner / sigma ** 2
    return {'total_runs': total, 'df_error': dfe, 'power': _ncf_power(lam, 1, dfe, alpha)}

def power_general_factorial(levels: list[int], reps: int, max_difference: float, sigma: float, order: int=2, alpha: float=0.05) -> dict:
    from itertools import combinations
    cells = int(np.prod(levels))
    N = cells * reps
    terms = sum((int(np.prod([levels[i] - 1 for i in sub])) for r in range(1, order + 1) for sub in combinations(range(len(levels)), r)))
    dfe = N - 1 - terms
    powers = [_ncf_power(N / l * max_difference ** 2 / (2 * sigma ** 2), l - 1, dfe, alpha) for l in levels]
    return {'total_runs': N, 'df_error': dfe, 'power': min(powers), 'factor_powers': powers}

def power_tost(design: str, n: int, difference: float, lower: float | None, upper: float | None, sigma: float, alpha: float=0.05) -> float:
    import math
    from scipy import integrate
    if design == 'one' or design == 'paired':
        c, df = (1 / math.sqrt(n), n - 1)
    elif design == 'two':
        c, df = (math.sqrt(2 / n), 2 * n - 2)
    elif design == 'crossover':
        c, df = (math.sqrt(1 / n), 2 * n - 2)
    else:
        raise ValueError(design)
    tc = stats.t.ppf(1 - alpha, df)
    sd = sigma * c
    L = -math.inf if lower is None else lower
    U = math.inf if upper is None else upper

    def inner(w):
        lo, hi = (L + tc * sd * w, U - tc * sd * w)
        if hi <= lo:
            return 0.0
        return float(stats.norm.cdf((hi - difference) / sd) - stats.norm.cdf((lo - difference) / sd))
    dens = lambda w: stats.chi.pdf(w * math.sqrt(df), df) * math.sqrt(df)
    return float(integrate.quad(lambda w: inner(w) * dens(w), 0, 1 + 20 / math.sqrt(df), limit=200, epsabs=1e-12)[0])

def sample_size_estimation(parameter: str, margin: float, confidence: float=0.95, sides: int=0, sigma: float | None=None, sigma_known: bool=False, proportion: float | None=None, rate: float | None=None, length: float=1.0, n_max: int=10 ** 7) -> int:
    import math
    a = 1 - confidence
    q = a / 2 if sides == 0 else a

    def half(n):
        if parameter == 'mean':
            crit = stats.norm.ppf(1 - q) if sigma_known else stats.t.ppf(1 - q, n - 1)
            return (crit * sigma / math.sqrt(n), crit * sigma / math.sqrt(n))
        if parameter == 'proportion':
            p = proportion
            x = p * n
            lo = stats.beta.ppf(q, x, n - x + 1) if x > 0 else 0.0
            hi = stats.beta.ppf(1 - q, x + 1, n - x) if x < n else 1.0
            return (hi - p, p - lo)
        if parameter == 'rate':
            x = rate * length * n
            lo = stats.chi2.ppf(q, 2 * x) / (2 * length * n)
            hi = stats.chi2.ppf(1 - q, 2 * x + 2) / (2 * length * n)
            return (hi - rate, rate - lo)
        if parameter == 'stdev':
            lo = sigma * math.sqrt((n - 1) / stats.chi2.ppf(1 - q, n - 1))
            hi = sigma * math.sqrt((n - 1) / stats.chi2.ppf(q, n - 1))
            return (hi - sigma, sigma - lo)
        raise ValueError(parameter)

    def ok(n):
        up, down = half(n)
        if sides == 0:
            return max(up, down) <= margin
        return (up if sides == 1 else down) <= margin
    n = 2
    while not ok(n):
        n = n * 2
        if n > n_max:
            raise ValueError('Örneklem büyüklüğü sınırı aşıldı.')
    lo = max(2, n // 2)
    for m in range(lo, n + 1):
        if ok(m):
            return m
    return n

