from __future__ import annotations
import math
from dataclasses import dataclass
import numpy as np

@dataclass
class Data:
    X: np.ndarray
    cat: list[bool]
    names: list[str]
    levels: list[list[str]]
    y: np.ndarray
    task: str
    classes: list[str]
    rows: np.ndarray
    dropped: int

    @property
    def K(self) -> int:
        return len(self.classes)

def _num(v) -> float:
    if v is None:
        return math.nan
    try:
        x = float(v)
    except (TypeError, ValueError):
        return math.nan
    return x if math.isfinite(x) else math.nan

def _txt(v) -> str | None:
    if v is None:
        return None
    if isinstance(v, float):
        if not math.isfinite(v):
            return None
        return str(int(v)) if v.is_integer() else repr(v)
    s = str(v).strip()
    return s or None
_TR = 'aâbcçdefgğhıiîjklmnoöprsştuûüvyz'

def _tr_key(s: str) -> list:
    low = s.replace('I', 'ı').replace('İ', 'i').lower()
    return [(_TR.index(ch), '') if ch in _TR else (100 + ord(ch), '') for ch in low]

def _sort_levels(vals: list[str]) -> list[str]:
    u = sorted(set(vals), key=_tr_key)
    try:
        return sorted(u, key=lambda s: float(s.replace(',', '.')))
    except ValueError:
        return u

def prepare(response: list, predictors: list[dict], task: str, event: str | None=None) -> Data:
    if not predictors:
        raise ValueError('En az bir öngörücü seçin.')
    n = len(response)
    for p in predictors:
        if len(p['values']) < n:
            p['values'] = list(p['values']) + [None] * (n - len(p['values']))
    ok = np.ones(n, dtype=bool)
    if task == 'class':
        yt = [_txt(v) for v in response]
        ok &= np.array([t is not None for t in yt])
    else:
        yn = np.array([_num(v) for v in response])
        ok &= np.isfinite(yn)
    cols = []
    for p in predictors:
        if p.get('categorical'):
            t = [_txt(v) for v in p['values'][:n]]
            ok &= np.array([s is not None for s in t])
            cols.append(('c', t))
        else:
            v = np.array([_num(x) for x in p['values'][:n]])
            ok &= np.isfinite(v)
            cols.append(('n', v))
    rows = np.flatnonzero(ok)
    if len(rows) < 10:
        raise ValueError(f'Eksiksiz satır sayısı çok az ({len(rows)}); en az 10 gerekir.')
    X = np.empty((len(rows), len(cols)))
    levels: list[list[str]] = []
    for j, (kind, col) in enumerate(cols):
        if kind == 'c':
            vals = [col[i] for i in rows]
            lv = _sort_levels(vals)
            m = {s: k for k, s in enumerate(lv)}
            X[:, j] = [m[s] for s in vals]
            levels.append(lv)
        else:
            X[:, j] = col[rows]
            levels.append([])
    if task == 'class':
        vals = [yt[i] for i in rows]
        classes = _sort_levels(vals)
        if len(classes) < 2:
            raise ValueError('Yanıtta en az iki sınıf olmalı.')
        if len(classes) > 20:
            raise ValueError('Yanıtta en çok 20 sınıf olabilir (sürekli bir yanıtsa regresyonu kullanın).')
        if event is not None and len(classes) == 2 and (event in classes) and (classes[1] != event):
            classes = [c for c in classes if c != event] + [event]
        m = {s: k for k, s in enumerate(classes)}
        y = np.array([m[s] for s in vals], dtype=int)
    else:
        classes = []
        y = yn[rows]
        if np.ptp(y) == 0:
            raise ValueError('Yanıt sabit; modellenecek değişkenlik yok.')
    return Data(X=X, cat=[k == 'c' for k, _ in cols], names=[p['name'] for p in predictors], levels=levels, y=y, task=task, classes=classes, rows=rows, dropped=int(n - len(rows)))

def folds(n: int, k: int, rng: np.random.Generator, y: np.ndarray | None=None) -> np.ndarray:
    f = np.empty(n, dtype=int)
    if y is None:
        perm = rng.permutation(n)
        f[perm] = np.arange(n) % k
        return f
    start = 0
    for c in np.unique(y):
        idx = rng.permutation(np.flatnonzero(y == c))
        f[idx] = (np.arange(len(idx)) + start) % k
        start += len(idx)
    return f

def test_split(n: int, frac: float, rng: np.random.Generator, y: np.ndarray | None=None) -> np.ndarray:
    is_test = np.zeros(n, dtype=bool)
    groups = [np.arange(n)] if y is None else [np.flatnonzero(y == c) for c in np.unique(y)]
    for g in groups:
        idx = rng.permutation(g)
        is_test[idx[:int(round(len(idx) * frac))]] = True
    return is_test

def class_metrics(y: np.ndarray, prob: np.ndarray, classes: list[str]) -> dict:
    K = len(classes)
    pred = prob.argmax(1)
    cm = np.zeros((K, K), dtype=int)
    np.add.at(cm, (y, pred), 1)
    n = len(y)
    correct = int(np.trace(cm))
    out = {'n': n, 'confusion': cm.tolist(), 'accuracy': correct / n, 'misclass': 1 - correct / n, 'per_class': [{'class': classes[k], 'n': int(cm[k].sum()), 'correct': int(cm[k, k]), 'rate': float(cm[k, k] / cm[k].sum()) if cm[k].sum() else None} for k in range(K)], 'logloss': float(-np.mean(np.log(np.clip(prob[np.arange(n), y], 1e-15, 1))))}
    if K == 2:
        out['auc'], out['roc'] = roc(y, prob[:, 1])
    return out

def roc(y: np.ndarray, score: np.ndarray, max_points: int=120) -> tuple[float | None, list[list[float]]]:
    P = int((y == 1).sum())
    Nn = len(y) - P
    if P == 0 or Nn == 0:
        return (None, [])
    o = np.argsort(-score, kind='mergesort')
    s, yy = (score[o], y[o])
    tp = np.cumsum(yy == 1)
    fp = np.cumsum(yy == 0)
    last = np.r_[s[1:] != s[:-1], True]
    tpr = np.r_[0, tp[last] / P]
    fpr = np.r_[0, fp[last] / Nn]
    auc = float(np.trapezoid(tpr, fpr)) if hasattr(np, 'trapezoid') else float(np.trapz(tpr, fpr))
    step = max(1, len(fpr) // max_points)
    pts = [[float(a), float(b)] for a, b in zip(fpr[::step], tpr[::step])]
    if pts[-1] != [1.0, 1.0]:
        pts.append([1.0, 1.0])
    return (auc, pts)

def reg_metrics(y: np.ndarray, pred: np.ndarray) -> dict:
    e = y - pred
    sse = float((e ** 2).sum())
    sst = float(((y - y.mean()) ** 2).sum())
    nz = y != 0
    return {'n': int(len(y)), 'r2': 1 - sse / sst if sst > 0 else None, 'rmse': math.sqrt(sse / len(y)), 'mse': sse / len(y), 'mad': float(np.abs(e).mean()), 'mape': float(np.abs(e[nz] / y[nz]).mean() * 100) if nz.any() else None}

def relative_importance(scores: np.ndarray, names: list[str]) -> list[dict]:
    mx = float(scores.max()) if len(scores) and scores.max() > 0 else 0.0
    rows = [{'name': names[j], 'score': float(scores[j]), 'relative': float(scores[j] / mx * 100) if mx > 0 else 0.0} for j in range(len(names))]
    return sorted(rows, key=lambda r: -r['score'])

def sample_points(y: np.ndarray, pred: np.ndarray, max_n: int=1500) -> list[list[float]]:
    idx = np.arange(len(y)) if len(y) <= max_n else np.linspace(0, len(y) - 1, max_n).astype(int)
    return [[float(y[i]), float(pred[i])] for i in idx]

