from __future__ import annotations
import math
import numpy as np
from .cart import fit_cart
from .common import Data, class_metrics, folds, reg_metrics, relative_importance, sample_points
from .ensemble import fit_forest, fit_treenet
from .mars import fit_mars

def _design(d: Data, rows: np.ndarray, ref_levels: list[list[int]] | None=None):
    cols = [np.ones(len(rows))]
    names = ['Sabit']
    for j in range(d.X.shape[1]):
        if d.cat[j]:
            for L in range(1, len(d.levels[j])):
                cols.append((d.X[rows, j].astype(int) == L).astype(float))
                names.append(f'{d.names[j]} = {d.levels[j][L]}')
        else:
            cols.append(d.X[rows, j])
            names.append(d.names[j])
    return (np.column_stack(cols), names)

def _ols(B, y):
    beta, *_ = np.linalg.lstsq(B, y, rcond=None)
    return beta

def _logit(B, y, iters: int=50):
    beta = np.zeros(B.shape[1])
    for _ in range(iters):
        eta = np.clip(B @ beta, -30, 30)
        p = 1 / (1 + np.exp(-eta))
        W = p * (1 - p) + 1e-09
        H = B.T @ (B * W[:, None]) + 1e-08 * np.eye(B.shape[1])
        step = np.linalg.solve(H, B.T @ (y - p))
        beta += step
        if np.max(np.abs(step)) < 1e-08:
            break
    return beta

def fit_linear(d: Data, k: int=5, seed: int=1) -> dict:
    rng = np.random.default_rng(seed)
    n = len(d.y)
    B, names = _design(d, np.arange(n))
    binary = d.task == 'class'
    if binary and d.K != 2:
        raise ValueError('Lojistik regresyon karşılaştırması iki sınıflı yanıt içindir.')
    fid = folds(n, k, rng, d.y if binary else None)
    held = np.zeros(n)
    for f in range(k):
        tr, te = (fid != f, fid == f)
        if binary:
            b = _logit(B[tr], d.y[tr].astype(float))
            held[te] = 1 / (1 + np.exp(-np.clip(B[te] @ b, -30, 30)))
        else:
            held[te] = B[te] @ _ols(B[tr], d.y[tr])
    beta = _logit(B, d.y.astype(float)) if binary else _ols(B, d.y)
    fit = 1 / (1 + np.exp(-np.clip(B @ beta, -30, 30))) if binary else B @ beta
    res = {'method': 'logistic' if binary else 'linear', 'task': d.task, 'validation': f'{k} katlı çapraz doğrulama', 'n': n, 'names': d.names, 'classes': d.classes, 'coefs': [{'term': t, 'coef': float(c)} for t, c in zip(names, beta)]}
    if binary:
        res['train'] = class_metrics(d.y, np.c_[1 - fit, fit], d.classes)
        res['test'] = class_metrics(d.y, np.c_[1 - held, held], d.classes)
    else:
        res['train'] = reg_metrics(d.y, fit)
        res['test'] = reg_metrics(d.y, held)
        res['points'] = sample_points(d.y, held)
    return res
LABEL = {'linear': 'Doğrusal regresyon', 'logistic': 'İkili lojistik regresyon', 'cart': 'QualiTree (karar ağacı)', 'forest': 'QualiForest (ağaç topluluğu)', 'treenet': 'QualiBoost (gradyan artırma)', 'mars': 'QualiSpline (menteşe regresyonu)'}

def discover(d: Data, *, k: int=5, seed: int=1, n_trees: int=200) -> dict:
    models: list[dict] = []
    errors: list[dict] = []
    jobs = []
    if d.task == 'reg':
        jobs = [('linear', lambda: fit_linear(d, k, seed)), ('cart', lambda: fit_cart(d, validation='kfold', k=k, seed=seed)), ('forest', lambda: fit_forest(d, n_trees=n_trees, seed=seed)), ('treenet', lambda: fit_treenet(d, n_trees=n_trees, validation='kfold', k=k, seed=seed)), ('mars', lambda: fit_mars(d, validation='kfold', k=k, seed=seed))]
    else:
        if d.K == 2:
            jobs.append(('logistic', lambda: fit_linear(d, k, seed)))
        jobs += [('cart', lambda: fit_cart(d, validation='kfold', k=k, seed=seed)), ('forest', lambda: fit_forest(d, n_trees=n_trees, seed=seed)), ('treenet', lambda: fit_treenet(d, n_trees=n_trees, validation='kfold', k=k, seed=seed))]
    for key, job in jobs:
        try:
            r = job()
            models.append(r)
        except (ValueError, np.linalg.LinAlgError) as e:
            errors.append({'method': key, 'label': LABEL[key], 'error': str(e)})
    if not models:
        raise ValueError('Hiçbir model kurulamadı.')
    rows = []
    for r in models:
        t = r.get('test') or r.get('train')
        if d.task == 'reg':
            rows.append({'method': r['method'], 'label': LABEL[r['method']], 'r2': t['r2'], 'rmse': t['rmse'], 'mad': t['mad'], 'validation': r['validation']})
        else:
            rows.append({'method': r['method'], 'label': LABEL[r['method']], 'accuracy': t['accuracy'], 'misclass': t['misclass'], 'auc': t.get('auc'), 'logloss': t['logloss'], 'validation': r['validation']})
    if d.task == 'reg':
        key = lambda x: -(x['r2'] if x['r2'] is not None else -math.inf)
    elif d.K == 2:
        key = lambda x: (-(x['auc'] or 0), x['misclass'])
    else:
        key = lambda x: (x['misclass'], x['logloss'])
    rows.sort(key=key)
    best = next((r for r in models if r['method'] == rows[0]['method']))
    return {'method': 'discover', 'task': d.task, 'n': len(d.y), 'dropped': d.dropped, 'names': d.names, 'classes': d.classes, 'ranking': rows, 'errors': errors, 'best': best}

