from __future__ import annotations
import math
import numpy as np
from .common import Data, class_metrics, folds, reg_metrics, relative_importance, sample_points, test_split
from .tree import grow, leaves_of, predict

def fit_forest(d: Data, *, n_trees: int=300, mtry: int | None=None, min_split: int | None=None, min_leaf: int=1, sample_frac: float=1.0, seed: int=1, crit: str='gini') -> dict:
    rng = np.random.default_rng(seed)
    task, K, n, p = (d.task, d.K, len(d.y), d.X.shape[1])
    m = mtry if mtry else max(1, int(math.sqrt(p))) if task == 'class' else max(1, p // 3)
    ms = min_split if min_split else 2 if task == 'class' else 5
    votes = np.zeros((n, K)) if task == 'class' else np.zeros(n)
    cnt = np.zeros(n)
    imp = np.zeros(p)
    curve = []
    size = max(2, int(round(n * sample_frac)))
    every = max(1, n_trees // 60)
    for t in range(n_trees):
        boot = rng.integers(0, n, size=size)
        oob = np.setdiff1d(np.arange(n), boot, assume_unique=False)
        tr = grow(d.X, d.cat, d.y, task, K, idx=boot, min_split=ms, min_leaf=min_leaf, mtry=m, rng=rng, crit=crit)
        for nd in tr.nodes:
            if not nd.is_leaf:
                imp[nd.feat] += nd.gain / tr.N
        if len(oob):
            pr = predict(tr, d.X[oob])
            if task == 'class':
                votes[oob, pr.argmax(1)] += 1
            else:
                votes[oob] += pr
            cnt[oob] += 1
        if (t + 1) % every == 0 or t == n_trees - 1:
            has = cnt > 0
            if has.any():
                if task == 'class':
                    err = float((votes[has].argmax(1) != d.y[has]).mean())
                else:
                    err = float(((votes[has] / cnt[has] - d.y[has]) ** 2).mean())
                curve.append([t + 1, err])
    has = cnt > 0
    res: dict = {'method': 'forest', 'task': task, 'validation': 'torba dışı (OOB) veriler', 'n': n, 'dropped': d.dropped, 'classes': d.classes, 'names': d.names, 'n_trees': n_trees, 'mtry': m, 'min_split': ms, 'importance': relative_importance(imp / n_trees, d.names), 'curve': curve, 'oob_n': int(has.sum())}
    if task == 'class':
        prob = votes[has] / np.maximum(votes[has].sum(1, keepdims=True), 1)
        res['test'] = class_metrics(d.y[has], prob, d.classes)
    else:
        pr = votes[has] / cnt[has]
        res['test'] = reg_metrics(d.y[has], pr)
        res['points'] = sample_points(d.y[has], pr)
    return res

def _softmax(F: np.ndarray) -> np.ndarray:
    e = np.exp(F - F.max(1, keepdims=True))
    return e / e.sum(1, keepdims=True)

def _loss(task: str, K: int, y: np.ndarray, F: np.ndarray) -> float:
    if task == 'reg':
        return float(((y - F) ** 2).mean())
    if K == 2:
        p = 1 / (1 + np.exp(-F))
        return float(-np.mean(y * np.log(np.clip(p, 1e-15, 1)) + (1 - y) * np.log(np.clip(1 - p, 1e-15, 1))))
    P = _softmax(F)
    return float(-np.mean(np.log(np.clip(P[np.arange(len(y)), y], 1e-15, 1))))

def _boost(d: Data, train: np.ndarray, evalset: np.ndarray | None, M: int, lr: float, leaves: int, min_leaf: int, sub: float, rng: np.random.Generator, imp: np.ndarray | None=None):
    task, K = (d.task, d.K)
    y = d.y
    ntr = len(train)
    if task == 'reg':
        f0 = np.array([float(y[train].mean())])
    elif K == 2:
        pbar = float(np.clip(y[train].mean(), 1e-06, 1 - 1e-06))
        f0 = np.array([math.log(pbar / (1 - pbar))])
    else:
        pr = np.bincount(y[train], minlength=K) / ntr
        f0 = np.log(np.clip(pr, 1e-06, 1))
    G = 1 if task == 'reg' or K == 2 else K
    Ftr = np.tile(f0, (ntr, 1))
    Fev = np.tile(f0, (len(evalset), 1)) if evalset is not None else None
    Ytr = np.eye(K)[y[train]] if G > 1 else None
    trees = []
    curve = []
    for m in range(M):
        sidx = rng.choice(ntr, size=max(2, int(ntr * sub)), replace=False) if sub < 1 else np.arange(ntr)
        step = []
        if G > 1:
            P = _softmax(Ftr)
        for g in range(G):
            if task == 'reg':
                r = y[train] - Ftr[:, 0]
                h = None
            elif K == 2:
                p = 1 / (1 + np.exp(-Ftr[:, 0]))
                r = y[train] - p
                h = p * (1 - p)
            else:
                r = Ytr[:, g] - P[:, g]
                h = P[:, g] * (1 - P[:, g])
            tr = grow(d.X[train], d.cat, r, 'reg', 0, idx=sidx, min_split=2 * min_leaf, min_leaf=min_leaf, max_leaves=leaves)
            lf = leaves_of(tr, d.X[train])
            insub = np.zeros(ntr, dtype=bool)
            insub[sidx] = True
            for nd in tr.nodes:
                if nd.is_leaf:
                    rows = (lf == nd.id) & insub
                    if h is None:
                        nd.leaf_value = float(r[rows].mean()) if rows.any() else 0.0
                    else:
                        den = float(h[rows].sum())
                        num = float(r[rows].sum())
                        nd.leaf_value = num / den * ((K - 1) / K if G > 1 else 1.0) if den > 1e-12 else 0.0
                elif imp is not None:
                    imp[nd.feat] += nd.gain
            Ftr[:, g] += lr * predict(tr, d.X[train])
            if Fev is not None:
                Fev[:, g] += lr * predict(tr, d.X[evalset])
            step.append(tr)
        trees.append(step)
        if Fev is not None:
            curve.append(_loss(task, K, y[evalset], Fev if G > 1 else Fev[:, 0]))
    return (f0, trees, curve)

def _predict_boost(d: Data, f0: np.ndarray, trees: list, lr: float, X: np.ndarray, upto: int | None=None) -> np.ndarray:
    G = len(f0) if len(f0) > 1 else 1
    F = np.tile(f0, (len(X), 1))
    for step in trees[:upto or len(trees)]:
        for g, tr in enumerate(step):
            F[:, g] += lr * predict(tr, X)
    if d.task == 'reg':
        return F[:, 0]
    if d.K == 2:
        p = 1 / (1 + np.exp(-F[:, 0]))
        return np.c_[1 - p, p]
    return _softmax(F)

def fit_treenet(d: Data, *, n_trees: int=300, lr: float | None=None, leaves: int=6, min_leaf: int=3, subsample: float=0.5, validation: str='kfold', k: int=5, test_frac: float=0.3, seed: int=1) -> dict:
    rng = np.random.default_rng(seed)
    task, K, n, p = (d.task, d.K, len(d.y), d.X.shape[1])
    if lr is None:
        lr = 0.1 if n < 2000 else 0.05
    strat = d.y if task == 'class' else None
    curve_tr = None
    if validation == 'kfold':
        kk = max(2, min(k, n // 5))
        fid = folds(n, kk, rng, strat)
        curves = []
        held = np.zeros((n, K)) if task == 'class' else np.zeros(n)
        fold_models = []
        for f in range(kk):
            tr, te = (np.flatnonzero(fid != f), np.flatnonzero(fid == f))
            f0, trees, c = _boost(d, tr, te, n_trees, lr, leaves, min_leaf, subsample, rng)
            curves.append(np.array(c) * len(te))
            fold_models.append((f0, trees, te))
        curve = np.sum(curves, 0) / n
        best = int(np.argmin(curve)) + 1
        for f0, trees, te in fold_models:
            held[te] = _predict_boost(d, f0, trees, lr, d.X[te], best)
        train = np.arange(n)
        vname = f'{kk} katlı çapraz doğrulama'
    elif validation == 'test':
        is_test = test_split(n, test_frac, rng, strat)
        train, te = (np.flatnonzero(~is_test), np.flatnonzero(is_test))
        f0t, treest, c = _boost(d, train, te, n_trees, lr, leaves, min_leaf, subsample, rng)
        curve = np.array(c)
        best = int(np.argmin(curve)) + 1
        held = _predict_boost(d, f0t, treest, lr, d.X[te], best)
        vname = f'test kümesi (%{round(test_frac * 100)})'
    else:
        train = np.arange(n)
        best = n_trees
        curve = None
        vname = 'doğrulama yok (eğitim verisi)'
    imp = np.zeros(p)
    f0, trees, ctr = _boost(d, train, train, best, lr, leaves, min_leaf, subsample, rng, imp)
    tr_pred = _predict_boost(d, f0, trees, lr, d.X[train])
    res: dict = {'method': 'treenet', 'task': task, 'validation': vname, 'n': n, 'dropped': d.dropped, 'classes': d.classes, 'names': d.names, 'n_trees': n_trees, 'optimal_trees': best, 'learning_rate': lr, 'max_leaves': leaves, 'subsample': subsample, 'importance': relative_importance(np.sqrt(np.maximum(imp, 0)), d.names), 'curve': [[i + 1, float(v)] for i, v in enumerate(curve)] if curve is not None else None, 'train_curve': [[i + 1, float(v)] for i, v in enumerate(ctr)]}
    if task == 'class':
        res['train'] = class_metrics(d.y[train], tr_pred, d.classes)
        if validation == 'kfold':
            res['test'] = class_metrics(d.y, held, d.classes)
        elif validation == 'test':
            res['test'] = class_metrics(d.y[te], held, d.classes)
    else:
        res['train'] = reg_metrics(d.y[train], tr_pred)
        if validation == 'kfold':
            res['test'] = reg_metrics(d.y, held)
            res['points'] = sample_points(d.y, held)
        elif validation == 'test':
            res['test'] = reg_metrics(d.y[te], held)
            res['points'] = sample_points(d.y[te], held)
        else:
            res['points'] = sample_points(d.y[train], tr_pred)
    return res

