from __future__ import annotations
import math
import numpy as np
from .common import Data, folds, reg_metrics, relative_importance, sample_points, test_split

def _knots(x: np.ndarray, max_knots: int, p: int, alpha: float=0.05) -> np.ndarray:
    n = len(x)
    xs = np.sort(x)
    endspan = int(math.ceil(3 - math.log2(alpha / p)))
    minspan = max(1, int(-math.log2(-(1.0 / (p * n)) * math.log(1 - alpha)) / 2.5))
    lo, hi = (endspan, n - endspan)
    if hi <= lo:
        return np.array([])
    cand = np.unique(xs[lo:hi:minspan])
    cand = cand[(cand > xs[0]) & (cand < xs[-1])]
    if len(cand) > max_knots:
        cand = cand[np.linspace(0, len(cand) - 1, max_knots).astype(int)]
    return cand

class _Term:

    def __init__(self, parts: list[tuple[int, str, float, int]]):
        self.parts = parts

    def eval(self, X: np.ndarray) -> np.ndarray:
        v = np.ones(len(X))
        for f, kind, t, s in self.parts:
            if kind == 'h':
                v *= np.maximum(0.0, s * (X[:, f] - t))
            else:
                v *= (X[:, f].astype(int) == int(t)).astype(float)
        return v

    def text(self, d: Data) -> str:
        out = []
        for f, kind, t, s in self.parts:
            nm = d.names[f]
            if kind == 'h':
                out.append(f'max(0; {nm} − {t:.6g})' if s > 0 else f'max(0; {t:.6g} − {nm})')
            else:
                out.append(f'({nm} = {d.levels[f][int(t)]})')
        return ' × '.join(out) if out else 'sabit'

    @property
    def vars(self) -> set[int]:
        return {f for f, *_ in self.parts}

def _ortho_reduction(Q: np.ndarray, e: np.ndarray, C: np.ndarray) -> np.ndarray:
    R = C - np.einsum('nm,mtk->ntk', Q, np.einsum('nm,ntk->mtk', Q, C))
    g11 = (R[:, :, 0] ** 2).sum(0)
    g22 = (R[:, :, 1] ** 2).sum(0)
    g12 = (R[:, :, 0] * R[:, :, 1]).sum(0)
    c1 = (R[:, :, 0] * e[:, None]).sum(0)
    c2 = (R[:, :, 1] * e[:, None]).sum(0)
    det = g11 * g22 - g12 * g12
    tiny = 1e-10 * (g11 + g22 + 1e-300)
    red_pair = np.where(det > tiny * (g11 + g22), (g22 * c1 * c1 - 2 * g12 * c1 * c2 + g11 * c2 * c2) / np.where(det > 0, det, 1), 0.0)
    red_1 = np.where(g11 > tiny, c1 * c1 / np.where(g11 > 0, g11, 1), 0.0)
    red_2 = np.where(g22 > tiny, c2 * c2 / np.where(g22 > 0, g22, 1), 0.0)
    return np.maximum(red_pair, np.maximum(red_1, red_2))

def _gcv(rss: float, n: int, M: int, penalty: float) -> float:
    c = M + penalty * (M - 1) / 2
    den = (1 - c / n) ** 2
    return rss / n / den if den > 1e-12 and c < n else math.inf

def _fit_ls(B: np.ndarray, y: np.ndarray) -> tuple[np.ndarray, float]:
    beta, *_ = np.linalg.lstsq(B, y, rcond=None)
    r = y - B @ beta
    return (beta, float(r @ r))

def mars_build(d: Data, rows: np.ndarray, max_terms: int=30, degree: int=1, max_knots: int=40, penalty: float | None=None, thresh: float=0.001):
    X, y = (d.X[rows], d.y[rows])
    sst = float(((y - y.mean()) ** 2).sum())
    n, p = X.shape
    pen = penalty if penalty is not None else 2.0 if degree == 1 else 3.0
    terms = [_Term([])]
    B = np.ones((n, 1))
    knots = [None if d.cat[f] else _knots(X[:, f], max_knots, p) for f in range(p)]
    while len(terms) < max_terms:
        Q, _ = np.linalg.qr(B)
        e = y - Q @ (Q.T @ y)
        best = (0.0, None)
        for ti, term in enumerate(terms):
            if len(term.parts) >= degree:
                continue
            base = B[:, ti]
            for f in range(p):
                if f in term.vars:
                    continue
                if d.cat[f]:
                    lv = np.unique(X[:, f]).astype(int)
                    if len(lv) < 2:
                        continue
                    C = np.stack([np.stack([base * (X[:, f].astype(int) == L), base * (X[:, f].astype(int) != L)], -1) for L in lv], 1)
                    red = _ortho_reduction(Q, e, C)
                    j = int(np.argmax(red))
                    if red[j] > best[0] + 1e-12:
                        best = (float(red[j]), ('c', ti, f, int(lv[j])))
                else:
                    ks = knots[f]
                    if not len(ks):
                        continue
                    xf = X[:, f][:, None]
                    C = np.stack([base[:, None] * np.maximum(0, xf - ks[None, :]), base[:, None] * np.maximum(0, ks[None, :] - xf)], -1)
                    red = _ortho_reduction(Q, e, C)
                    j = int(np.argmax(red))
                    if red[j] > best[0] + 1e-12:
                        best = (float(red[j]), ('h', ti, f, float(ks[j])))
        if best[1] is None or best[0] < thresh * sst:
            break
        kind, ti, f, t = best[1]
        parent = terms[ti]
        new = [_Term(parent.parts + [(f, 'h', t, 1)]), _Term(parent.parts + [(f, 'h', t, -1)])] if kind == 'h' else [_Term(parent.parts + [(f, 'c', t, 1)])]
        for nt in new:
            col = nt.eval(X)
            if col.std() > 1e-12 and len(terms) < max_terms:
                terms.append(nt)
                B = np.c_[B, col]
    active = list(range(len(terms)))
    beta, rss = _fit_ls(B, y)
    best_set, best_gcv = (list(active), _gcv(rss, n, len(active), pen))
    path = [(len(active), best_gcv, rss)]
    while len(active) > 1:
        cand = None
        for j in active[1:]:
            s = [a for a in active if a != j]
            _, r = _fit_ls(B[:, s], y)
            if cand is None or r < cand[1]:
                cand = (j, r)
        active.remove(cand[0])
        g = _gcv(cand[1], n, len(active), pen)
        path.append((len(active), g, cand[1]))
        if g < best_gcv:
            best_gcv, best_set = (g, list(active))
    final = [terms[i] for i in best_set]
    Bf = B[:, best_set]
    beta, rss = _fit_ls(Bf, y)
    return (final, beta, rss, best_gcv, pen, path)

def _mars_predict(terms, beta, X):
    return np.column_stack([t.eval(X) for t in terms]) @ beta

def fit_mars(d: Data, *, max_terms: int=30, degree: int=1, max_knots: int=40, validation: str='kfold', k: int=5, test_frac: float=0.3, seed: int=1) -> dict:
    if d.task != 'reg':
        raise ValueError('QualiSpline sürekli yanıt içindir.')
    rng = np.random.default_rng(seed)
    n = len(d.y)
    held = None
    if validation == 'kfold':
        kk = max(2, min(k, n // 5))
        fid = folds(n, kk, rng)
        held = np.zeros(n)
        for f in range(kk):
            tr, te = (np.flatnonzero(fid != f), np.flatnonzero(fid == f))
            t_, b_, *_ = mars_build(d, tr, max_terms, degree, max_knots)
            held[te] = _mars_predict(t_, b_, d.X[te])
        train = np.arange(n)
        vname = f'{kk} katlı çapraz doğrulama'
    elif validation == 'test':
        is_test = test_split(n, test_frac, rng)
        train, te = (np.flatnonzero(~is_test), np.flatnonzero(is_test))
        vname = f'test kümesi (%{round(test_frac * 100)})'
    else:
        train = np.arange(n)
        vname = 'doğrulama yok (eğitim verisi; GCV)'
    terms, beta, rss, gcv, pen, path = mars_build(d, train, max_terms, degree, max_knots)
    tr_pred = _mars_predict(terms, beta, d.X[train])
    imp = np.zeros(d.X.shape[1])
    B = np.column_stack([t.eval(d.X[train]) for t in terms])
    ntr = len(train)
    for f in range(d.X.shape[1]):
        keep = [i for i, t in enumerate(terms) if f not in t.vars]
        if len(keep) < len(terms):
            beta_k, *_ = np.linalg.lstsq(B[:, keep], d.y[train], rcond=None)
            rk = float(((d.y[train] - B[:, keep] @ beta_k) ** 2).sum())
            imp[f] = max(0.0, _gcv(rk, ntr, len(keep), pen) - gcv)
    sst = float(((d.y[train] - d.y[train].mean()) ** 2).sum())
    res: dict = {'method': 'mars', 'task': 'reg', 'validation': vname, 'n': n, 'dropped': d.dropped, 'names': d.names, 'classes': [], 'degree': degree, 'max_terms': max_terms, 'terms': [{'term': t.text(d), 'coef': float(b)} for t, b in zip(terms, beta)], 'gcv': gcv, 'gcv_r2': 1 - gcv * ntr / sst if sst > 0 else None, 'path': [{'terms': m, 'gcv': g if math.isfinite(g) else None, 'rss': r} for m, g, r in path], 'importance': relative_importance(np.sqrt(imp), d.names), 'train': reg_metrics(d.y[train], tr_pred)}
    if validation == 'kfold':
        res['test'] = reg_metrics(d.y, held)
        res['points'] = sample_points(d.y, held)
    elif validation == 'test':
        pt = _mars_predict(terms, beta, d.X[te])
        res['test'] = reg_metrics(d.y[te], pt)
        res['points'] = sample_points(d.y[te], pt)
    else:
        res['points'] = sample_points(d.y[train], tr_pred)
    return res

