from __future__ import annotations
import heapq
import itertools
from dataclasses import dataclass, field
import numpy as np

@dataclass
class Node:
    id: int
    parent: int
    depth: int
    n: int
    value: np.ndarray
    feat: int = -1
    thr: float = np.nan
    left_set: frozenset | None = None
    left: int = -1
    right: int = -1
    gain: float = 0.0
    risk: float = 0.0
    leaf_value: float | None = None

    @property
    def is_leaf(self) -> bool:
        return self.left < 0

@dataclass
class Tree:
    nodes: list[Node]
    task: str
    K: int
    N: int
    cat: list[bool]
    levels_seen: list[set] = field(default_factory=list)

def _imp_class(counts: np.ndarray, n: np.ndarray, crit: str) -> np.ndarray:
    with np.errstate(divide='ignore', invalid='ignore'):
        p = counts / np.maximum(n, 1e-300)[..., None]
        if crit == 'entropy':
            lp = np.where(p > 0, np.log2(np.where(p > 0, p, 1.0)), 0.0)
            return -(p * lp).sum(-1)
        return 1.0 - (p * p).sum(-1)

def _node_risk(task: str, value: np.ndarray, n: int) -> float:
    if task == 'class':
        return float(n - value.max())
    return float(value[1])

def _best_numeric(x: np.ndarray, y: np.ndarray, task: str, K: int, min_leaf: int, crit: str, parent_mass: float):
    o = np.argsort(x, kind='mergesort')
    xs = x[o]
    n = len(xs)
    if n < 2 * min_leaf or xs[0] == xs[-1]:
        return None
    nL = np.arange(1, n, dtype=float)
    nR = n - nL
    valid = (xs[:-1] < xs[1:]) & (nL >= min_leaf) & (nR >= min_leaf)
    if not valid.any():
        return None
    if task == 'class':
        C = np.cumsum(np.eye(K)[y[o]], axis=0)
        L = C[:-1]
        R = C[-1] - L
        mass = nL * _imp_class(L, nL, crit) + nR * _imp_class(R, nR, crit)
    else:
        ys = y[o]
        S = np.cumsum(ys)
        S2 = np.cumsum(ys * ys)
        SL, SL2 = (S[:-1], S2[:-1])
        SR, SR2 = (S[-1] - SL, S2[-1] - SL2)
        mass = SL2 - SL * SL / nL + (SR2 - SR * SR / nR)
    gain = parent_mass - mass
    gain[~valid] = -np.inf
    i = int(np.argmax(gain))
    if not np.isfinite(gain[i]) or gain[i] <= 1e-12:
        return None
    return (float(gain[i]), float((xs[i] + xs[i + 1]) / 2.0), None)

def _best_categorical(x: np.ndarray, y: np.ndarray, task: str, K: int, min_leaf: int, crit: str, parent_mass: float):
    codes = x.astype(int)
    lv = np.unique(codes)
    if len(lv) < 2:
        return None
    nlev = np.array([(codes == c).sum() for c in lv], dtype=float)
    if task == 'class':
        cnt = np.array([np.bincount(y[codes == c], minlength=K) for c in lv], dtype=float)
        if K > 2 and len(lv) <= 10:
            L = len(lv)
            masks = np.array([[m >> j & 1 for j in range(L)] for m in range(1, 2 ** (L - 1) * 2 - 1) if m & 1], dtype=float)
            masks = masks[masks.sum(1) < L]
            if not len(masks):
                return None
            Lc = masks @ cnt
            nL = masks @ nlev
            Rc = cnt.sum(0) - Lc
            nR = nlev.sum() - nL
            ok = (nL >= min_leaf) & (nR >= min_leaf)
            if not ok.any():
                return None
            mass = nL * _imp_class(Lc, nL, crit) + nR * _imp_class(Rc, nR, crit)
            gain = np.where(ok, parent_mass - mass, -np.inf)
            i = int(np.argmax(gain))
            if gain[i] <= 1e-12:
                return None
            return (float(gain[i]), np.nan, frozenset((int(lv[j]) for j in range(L) if masks[i, j])))
        key = cnt[:, 1] / nlev if K == 2 else cnt[:, int(cnt.sum(0).argmax())] / nlev
        order = np.argsort(key, kind='mergesort')
        cnt_o, n_o = (cnt[order], nlev[order])
        Lc = np.cumsum(cnt_o, 0)[:-1]
        nL = np.cumsum(n_o)[:-1]
        Rc = cnt_o.sum(0) - Lc
        nR = n_o.sum() - nL
        mass = nL * _imp_class(Lc, nL, crit) + nR * _imp_class(Rc, nR, crit)
    else:
        s = np.array([y[codes == c].sum() for c in lv])
        s2 = np.array([(y[codes == c] ** 2).sum() for c in lv])
        order = np.argsort(s / nlev, kind='mergesort')
        s_o, s2_o, n_o = (s[order], s2[order], nlev[order])
        SL, SL2, nL = (np.cumsum(s_o)[:-1], np.cumsum(s2_o)[:-1], np.cumsum(n_o)[:-1])
        SR, SR2, nR = (s_o.sum() - SL, s2_o.sum() - SL2, n_o.sum() - nL)
        mass = SL2 - SL * SL / nL + (SR2 - SR * SR / nR)
    ok = (nL >= min_leaf) & (nR >= min_leaf)
    gain = np.where(ok, parent_mass - mass, -np.inf)
    i = int(np.argmax(gain))
    if not np.isfinite(gain[i]) or gain[i] <= 1e-12:
        return None
    return (float(gain[i]), np.nan, frozenset((int(c) for c in lv[order[:i + 1]])))

def _value(task: str, y: np.ndarray, K: int) -> np.ndarray:
    if task == 'class':
        return np.bincount(y, minlength=K).astype(float)
    m = float(y.mean())
    return np.array([m, float(((y - m) ** 2).sum())])

def _mass(task: str, value: np.ndarray, n: int, crit: str) -> float:
    if task == 'class':
        return float(n * _imp_class(value, np.array(float(n)), crit))
    return float(value[1])

def grow(X: np.ndarray, cat: list[bool], y: np.ndarray, task: str, K: int=0, *, min_split: int=10, min_leaf: int=3, max_depth: int | None=None, max_leaves: int | None=None, mtry: int | None=None, rng: np.random.Generator | None=None, crit: str='gini', idx: np.ndarray | None=None) -> Tree:
    rows = np.arange(len(y)) if idx is None else idx
    p = X.shape[1]
    nodes: list[Node] = []

    def make(rows_: np.ndarray, parent: int, depth: int) -> int:
        v = _value(task, y[rows_], K)
        nd = Node(id=len(nodes), parent=parent, depth=depth, n=len(rows_), value=v)
        nd.risk = _node_risk(task, v, len(rows_))
        nodes.append(nd)
        return nd.id

    def find_split(nid: int, rows_: np.ndarray):
        nd = nodes[nid]
        if nd.n < min_split or (max_depth is not None and nd.depth >= max_depth):
            return None
        if task == 'class' and nd.value.max() == nd.n:
            return None
        if task == 'reg' and nd.value[1] <= 1e-12:
            return None
        pm = _mass(task, nd.value, nd.n, crit)
        feats = range(p) if mtry is None or mtry >= p else rng.choice(p, size=mtry, replace=False)
        best = None
        ys = y[rows_]
        for f in feats:
            xf = X[rows_, f]
            r = (_best_categorical if cat[f] else _best_numeric)(xf, ys, task, K, min_leaf, crit, pm)
            if r is not None and (best is None or r[0] > best[0] + 1e-12):
                best = (r[0], f, r[1], r[2])
        return best

    def apply_split(nid: int, rows_: np.ndarray, sp):
        gain, f, thr, lset = sp
        xf = X[rows_, f]
        goes_left = np.isin(xf.astype(int), list(lset)) if cat[f] else xf <= thr
        nd = nodes[nid]
        nd.feat, nd.thr, nd.left_set, nd.gain = (f, thr, lset, gain)
        lr, rr = (rows_[goes_left], rows_[~goes_left])
        nd.left = make(lr, nid, nd.depth + 1)
        nd.right = make(rr, nid, nd.depth + 1)
        return (lr, rr)
    root = make(rows, -1, 0)
    if max_leaves is None:
        stack = [(root, rows)]
        while stack:
            nid, r = stack.pop()
            sp = find_split(nid, r)
            if sp is None:
                continue
            lr, rr = apply_split(nid, r, sp)
            stack.append((nodes[nid].right, rr))
            stack.append((nodes[nid].left, lr))
    else:
        heap: list = []
        counter = itertools.count()
        sp = find_split(root, rows)
        if sp is not None:
            heapq.heappush(heap, (-sp[0], next(counter), root, rows, sp))
        leaves = 1
        while heap and leaves < max_leaves:
            _, _, nid, r, sp = heapq.heappop(heap)
            lr, rr = apply_split(nid, r, sp)
            leaves += 1
            for child, cr in ((nodes[nid].left, lr), (nodes[nid].right, rr)):
                csp = find_split(child, cr)
                if csp is not None:
                    heapq.heappush(heap, (-csp[0], next(counter), child, cr, csp))
    seen = [set(np.unique(X[rows, f]).astype(int).tolist()) if cat[f] else set() for f in range(p)]
    return Tree(nodes=nodes, task=task, K=K, N=len(rows), cat=list(cat), levels_seen=seen)

def leaves_of(tree: Tree, X: np.ndarray, pruned: frozenset | set | None=None) -> np.ndarray:
    pruned = pruned or set()
    out = np.empty(len(X), dtype=int)
    stack = [(0, np.arange(len(X)))]
    nodes = tree.nodes
    while stack:
        nid, r = stack.pop()
        nd = nodes[nid]
        if nd.is_leaf or nid in pruned or (not len(r)):
            out[r] = nid
            continue
        xf = X[r, nd.feat]
        if tree.cat[nd.feat]:
            codes = xf.astype(int)
            gl = np.isin(codes, list(nd.left_set))
            unseen = ~np.isin(codes, list(tree.levels_seen[nd.feat]))
            if unseen.any():
                gl = np.where(unseen, nodes[nd.left].n >= nodes[nd.right].n, gl)
        else:
            gl = xf <= nd.thr
        stack.append((nd.left, r[gl]))
        stack.append((nd.right, r[~gl]))
    return out

def predict(tree: Tree, X: np.ndarray, pruned=None) -> np.ndarray:
    lf = leaves_of(tree, X, pruned)
    if tree.task == 'class':
        V = np.array([nd.value / max(nd.n, 1) for nd in tree.nodes])
        return V[lf]
    V = np.array([nd.leaf_value if nd.leaf_value is not None else nd.value[0] for nd in tree.nodes])
    return V[lf]

def _subtree_stats(tree: Tree, pruned: set) -> tuple[dict, dict]:
    risk_sum: dict[int, float] = {}
    leaves: dict[int, int] = {}

    def rec(nid: int) -> tuple[float, int]:
        nd = tree.nodes[nid]
        if nd.is_leaf or nid in pruned:
            return (nd.risk, 1)
        a = rec(nd.left)
        b = rec(nd.right)
        risk_sum[nid] = a[0] + b[0]
        leaves[nid] = a[1] + b[1]
        return (risk_sum[nid], leaves[nid])
    rec(0)
    return (risk_sum, leaves)

def prune_sequence(tree: Tree) -> list[tuple[float, frozenset, int, float]]:
    pruned: set[int] = set()
    N = tree.N
    while True:
        rs, _ = _subtree_stats(tree, pruned)
        zero = [nid for nid in rs if tree.nodes[nid].risk - rs[nid] <= 1e-09 * max(1.0, tree.nodes[nid].risk)]
        if not zero:
            break
        pruned.update(zero)
    seq = []
    alpha = 0.0
    while True:
        lv_ = _active_leaves(tree, pruned)
        seq.append((alpha, frozenset(pruned), len(lv_), sum((tree.nodes[n].risk for n in lv_)) / N))
        rs, lv = _subtree_stats(tree, pruned)
        if not rs:
            break
        g = {nid: (tree.nodes[nid].risk - rs[nid]) / N / (lv[nid] - 1) for nid in rs}
        alpha = min(g.values())
        for nid, v in g.items():
            if v <= alpha * (1 + 1e-09) + 1e-15:
                pruned.add(nid)
    return seq

def _active_leaves(tree: Tree, pruned) -> list[int]:
    out = []
    stack = [0]
    while stack:
        nid = stack.pop()
        nd = tree.nodes[nid]
        if nd.is_leaf or nid in pruned:
            out.append(nid)
        else:
            stack += [nd.left, nd.right]
    return out

def _count_leaves(tree: Tree, pruned) -> int:
    return len(_active_leaves(tree, pruned))

