from __future__ import annotations
from scipy import stats

def _dist(name: str, params: list[float]):
    n = name.lower()
    p = list(params)
    if n == 'normal':
        return (stats.norm(p[0], p[1]), False)
    if n == 'lognormal':
        import math
        return (stats.lognorm(p[1], loc=p[2] if len(p) > 2 else 0, scale=math.exp(p[0])), False)
    if n == 'weibull':
        return (stats.weibull_min(p[0], loc=p[2] if len(p) > 2 else 0, scale=p[1]), False)
    if n == 'exponential':
        return (stats.expon(loc=p[1] if len(p) > 1 else 0, scale=p[0]), False)
    if n == 'gamma':
        return (stats.gamma(p[0], loc=p[2] if len(p) > 2 else 0, scale=p[1]), False)
    if n == 'beta':
        return (stats.beta(p[0], p[1]), False)
    if n == 'chisquare':
        return (stats.chi2(p[0]), False)
    if n == 'f':
        return (stats.f(p[0], p[1]), False)
    if n == 't':
        return (stats.t(p[0]), False)
    if n == 'uniform':
        return (stats.uniform(p[0], p[1] - p[0]), False)
    if n == 'triangular':
        a, c, b = p
        return (stats.triang((c - a) / (b - a), loc=a, scale=b - a), False)
    if n == 'logistic':
        return (stats.logistic(p[0], p[1]), False)
    if n == 'loglogistic':
        import math
        return (stats.fisk(1 / p[1], loc=p[2] if len(p) > 2 else 0, scale=math.exp(p[0])), False)
    if n == 'laplace':
        return (stats.laplace(p[0], p[1]), False)
    if n == 'cauchy':
        return (stats.cauchy(p[0], p[1]), False)
    if n == 'sev':
        return (stats.gumbel_l(p[0], p[1]), False)
    if n == 'lev':
        return (stats.gumbel_r(p[0], p[1]), False)
    if n == 'binomial':
        return (stats.binom(int(p[0]), p[1]), True)
    if n == 'poisson':
        return (stats.poisson(p[0]), True)
    if n == 'geometric':
        return (stats.geom(p[0]), True)
    if n == 'negbinomial':
        prob, r = (p[0], int(p[1]))
        return (stats.nbinom(r, prob, loc=r), True)
    if n == 'hypergeometric':
        N, M, k = (int(v) for v in p)
        return (stats.hypergeom(N, M, k), True)
    raise ValueError(f'Bilinmeyen dağılım: {name}')

def pdf(name: str, params: list[float], x: list[float]) -> list[float]:
    d, discrete = _dist(name, params)
    return [float(d.pmf(v) if discrete else d.pdf(v)) for v in x]

def cdf(name: str, params: list[float], x: list[float]) -> list[float]:
    d, _ = _dist(name, params)
    return [float(d.cdf(v)) for v in x]

def inv_cdf(name: str, params: list[float], probs: list[float]) -> list:
    d, discrete = _dist(name, params)
    out = []
    for q in probs:
        if discrete:
            hi = float(d.ppf(q))
            lo = hi - 1
            out.append({'lower': (lo, float(d.cdf(lo))), 'upper': (hi, float(d.cdf(hi)))})
        else:
            out.append(float(d.ppf(q)))
    return out

