from __future__ import annotations
import math
from dataclasses import dataclass, field
from scipy import optimize, stats
N = stats.norm

@dataclass
class OCRow:
    quality: float
    p_accept: float
    p_reject: float
    aoq: float | None
    ati: float | None

@dataclass
class SamplingPlan:
    kind: str
    n: int
    c: float
    rows: list[OCRow] = field(default_factory=list)
    aoql: float | None = None
    aoql_at: float | None = None

def _scale(units: str) -> float:
    return {'percent': 100.0, 'proportion': 1.0, 'ppm': 1000000.0}[units]

def _attr_pa(c: int, n: int, p: float, distribution: str, lot: int | None) -> float:
    if distribution == 'poisson':
        return float(stats.poisson.cdf(c, n * p))
    if distribution == 'hypergeometric':
        return float(stats.hypergeom.cdf(c, lot, int(round(p * lot)), n))
    return float(stats.binom.cdf(c, n, p))

def _finish(plan: SamplingPlan, pa_fn, qualities: list[float], scale: float, lot: int | None, discrete: bool=False) -> SamplingPlan:
    n = plan.n
    for q in qualities:
        p = q / scale
        pa = pa_fn(p)
        aoq = ati = None
        if lot:
            aoq = pa * p * (lot - n) / lot * scale
            ati = n + (1 - pa) * (lot - n)
        plan.rows.append(OCRow(q, pa, 1 - pa, aoq, ati))
    if lot and discrete:
        best = max(range(0, lot + 1), key=lambda d: pa_fn(d / lot) * d / lot)
        plan.aoql = pa_fn(best / lot) * best / lot * (lot - n) / lot * scale
        plan.aoql_at = best / lot * scale
    elif lot:
        f = lambda p: -pa_fn(p) * p * (lot - n) / lot
        hi = max((q / scale for q in qualities)) * 4
        grid = [hi * i / 400 for i in range(1, 401)]
        best = max(grid, key=lambda p: -f(p))
        r = optimize.minimize_scalar(f, bounds=(max(best - hi / 400, 1e-12), best + hi / 400), method='bounded', options={'xatol': 1e-12})
        plan.aoql, plan.aoql_at = (-r.fun * scale, r.x * scale)
    return plan

def attribute_plan(aql: float, rql: float, alpha: float=0.05, beta: float=0.1, lot: int | None=None, units: str='percent', defects: bool=False, hypergeometric: bool=False, n: int | None=None, c: int | None=None) -> SamplingPlan:
    scale = _scale(units)
    dist = 'poisson' if defects else 'hypergeometric' if hypergeometric and lot else 'binomial'
    pa = lambda cc, nn, p: _attr_pa(cc, nn, p, dist, lot)
    if n is None:
        a_, r_ = (aql / scale, rql / scale)
        for cc in range(0, 1000):
            nn = cc + 1
            lo, hi = (nn, nn)
            while pa(cc, hi, r_) > beta:
                lo, hi = (hi, hi * 2)
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if pa(cc, mid, r_) > beta:
                    lo = mid
                else:
                    hi = mid
            nn = hi if pa(cc, lo, r_) > beta else lo
            if pa(cc, nn, a_) >= 1 - alpha:
                n, c = (nn, cc)
                break
    plan = SamplingPlan('attributes-defects' if defects else 'attributes-defective', int(n), int(c))
    return _finish(plan, lambda p: pa(int(c), int(n), p), [aql, rql], scale, lot, dist == 'hypergeometric')

def variables_plan(aql: float, rql: float, alpha: float=0.05, beta: float=0.1, lot: int | None=None, units: str='percent', sigma_known: bool=False, n: int | None=None, k: float | None=None) -> SamplingPlan:
    scale = _scale(units)
    za, zb = (N.ppf(1 - alpha), N.ppf(1 - beta))
    z1, z2 = (N.ppf(1 - aql / scale), N.ppf(1 - rql / scale))
    if n is None:
        base = ((za + zb) / (z1 - z2)) ** 2
        k0 = (z1 * zb + z2 * za) / (za + zb)
        if sigma_known:
            n = math.ceil(base)
            k = (z1 - za / math.sqrt(n) + (z2 + zb / math.sqrt(n))) / 2
        else:
            n = math.ceil((1 + k0 * k0 / 2) * base)
            k = k0
    if sigma_known:
        pa = lambda p: float(N.cdf((N.ppf(1 - p) - k) * math.sqrt(n)))
    else:
        pa = lambda p: float(stats.nct.sf(k * math.sqrt(n), n - 1, N.ppf(1 - p) * math.sqrt(n)))
    plan = SamplingPlan('variables', int(n), float(k))
    return _finish(plan, pa, [aql, rql], scale, lot)

def accept_reject(values, k: float, lsl: float | None=None, usl: float | None=None, sigma: float | None=None) -> dict:
    xs = [float(v) for v in values if v is not None]
    n = len(xs)
    m = sum(xs) / n
    s = sigma if sigma is not None else math.sqrt(sum(((v - m) ** 2 for v in xs)) / (n - 1))
    out = {'n': n, 'mean': m, 'stdev': s, 'k': k}
    ok = True
    if lsl is not None:
        out['z_lsl'] = (m - lsl) / s
        ok &= out['z_lsl'] >= k
    if usl is not None:
        out['z_usl'] = (usl - m) / s
        ok &= out['z_usl'] >= k
    out['decision'] = 'accept' if ok else 'reject'
    return out

