from __future__ import annotations
import math
import numpy as np
from scipy import stats
_COEF = {0.1: (1.2092, 0.7992, 0.6238, 0.4797, 1.6819, -0.2155, 0.4529, -0.6095), 0.05: (1.7011, 0.6047, 0.7102, 1.4605, 1.9102, 0.225, 0.63, -0.2202), 0.01: (2.3539, 0.5176, 0.7107, 4.3161, 2.3629, 4.64, 1.864, 0.3204), 0.001: (3.1981, 0.3619, 0.7886, 8.3489, 3.1003, 22.7005, 5.1277, 0.7271)}

def _h_formula(c, k, df):
    lk = math.log(k)
    lk2 = math.log(k - 2) if k > 2 else 0.0
    x = 1 / (df - 1)
    return c[0] + c[1] * lk ** c[2] + (c[3] + c[4] * lk) * x + (c[5] + c[6] * lk2 + c[7] * lk2 * lk2) * x * x

def anom_h_balanced(k: int, df: float, alpha: float) -> float:
    if k == 2:
        return float(stats.t.ppf(1 - alpha / 2, df))
    if not 0.001 <= alpha <= 0.1:
        return _sidak_t(k, df, alpha)
    pts = [0.1, 0.05, 0.01, 0.001]
    for hi, lo in zip(pts, pts[1:]):
        if lo <= alpha <= hi:
            a, b = (_h_formula(_COEF[hi], k, df), _h_formula(_COEF[lo], k, df))
            return a - (hi - alpha) / (hi - lo) * (a - b)
    raise ValueError(alpha)

def _sidak_t(k, df, alpha):
    a = 1 - (1 - alpha) ** (1 / k)
    return float(stats.t.ppf(1 - a / 2, df))

def _levels(v):
    u = list(dict.fromkeys(v))
    try:
        return sorted(u, key=float)
    except (TypeError, ValueError):
        return sorted(u, key=str)

def anom_normal(response, factor, alpha: float=0.05) -> dict:
    pairs = [(float(y), str(f)) for y, f in zip(response, factor) if y is not None and f is not None]
    lv = [str(v) for v in _levels([f for _, f in pairs])]
    k = len(lv)
    if k < 2:
        raise ValueError('En az iki düzey gerekli.')
    y = np.array([p[0] for p in pairs])
    groups = {l: np.array([v for v, f in pairs if f == l]) for l in lv}
    n = np.array([len(groups[l]) for l in lv], dtype=float)
    if np.any(n < 1):
        raise ValueError('Boş düzey var.')
    N = n.sum()
    means = np.array([groups[l].mean() for l in lv])
    df = N - k
    sse = sum((((groups[l] - groups[l].mean()) ** 2).sum() for l in lv))
    s = math.sqrt(sse / df)
    gm = float(y.mean())
    balanced = bool(np.all(n == n[0]))
    if balanced:
        h = anom_h_balanced(k, df, alpha)
        w = s * np.sqrt((k - 1) / (k * n))
    else:
        h = _sidak_t(k, df, alpha)
        w = s * np.sqrt((N - n) / (N * n))
    return {'levels': lv, 'n': n.tolist(), 'means': means.tolist(), 'center': gm, 's': s, 'df': df, 'h': h, 'balanced': balanced, 'upper': (gm + h * w).tolist(), 'lower': (gm - h * w).tolist(), 'out': [bool(m > gm + h * wi or m < gm - h * wi) for m, wi in zip(means, w)]}

def anom_attribute(counts, kind: str='binomial', sample_size: float | None=None, alpha: float=0.05) -> dict:
    c = np.array([float(v) for v in counts if v is not None])
    k = len(c)
    if k < 2:
        raise ValueError('En az iki örnek gerekli.')
    h = float(stats.norm.ppf(1 - alpha / 2)) if k == 2 else float(stats.norm.ppf(1 - alpha / (2 * k)))
    if kind == 'binomial':
        if not sample_size or sample_size <= 0:
            raise ValueError('Binom için örneklem büyüklüğü gerekli.')
        if np.any(c > sample_size):
            raise ValueError('Sayımlar örneklem büyüklüğünü aşamaz.')
        pts = c / sample_size
        center = float(c.sum() / (sample_size * k))
        w = math.sqrt(center * (1 - center) / sample_size) * math.sqrt((k - 1) / k)
        up, lo = (min(center + h * w, 1.0), max(center - h * w, 0.0))
    else:
        pts = c
        center = float(c.mean())
        w = math.sqrt((k - 1) * center / k)
        up, lo = (center + h * w, max(center - h * w, 0.0))
    return {'kind': kind, 'points': pts.tolist(), 'center': center, 'h': h, 'upper': up, 'lower': lo, 'out': [bool(v >= up or v <= lo) for v in pts]}

qualistat/regression/glz.py:
from __future__ import annotations
import math
from dataclasses import dataclass, field
from itertools import combinations
import numpy as np
from scipy import stats
from .linear import _levels, _term_columns

@dataclass
class GLZCoef:
    term: str
    group: str | None
    coef: float
    se: float
    z: float
    p: float
    vif: float | None

@dataclass
class GLZResult:
    family: str
    link: str
    n: int
    event: str | None
    event_count: int | None
    coefficients: list[GLZCoef]
    odds_continuous: list[dict] = field(default_factory=list)
    odds_categorical: list[dict] = field(default_factory=list)
    deviance: float = 0.0
    null_deviance: float = 0.0
    dev_r_sq: float = 0.0
    dev_r_sq_adj: float = 0.0
    aic: float = 0.0
    aicc: float = 0.0
    bic: float = 0.0
    auc: float | None = None
    gof: list[dict] = field(default_factory=list)
    anova: list[dict] = field(default_factory=list)
    unusual: list[dict] = field(default_factory=list)
    equations: list[tuple[str | None, str]] = field(default_factory=list)
    fits: list[float] = field(default_factory=list)

def _link_funcs(link: str):
    if link == 'logit':
        return (lambda eta: 1 / (1 + np.exp(-eta)), lambda mu: mu * (1 - mu))
    if link == 'normit':
        return (lambda eta: stats.norm.cdf(eta), lambda mu: stats.norm.pdf(stats.norm.ppf(np.clip(mu, 1e-15, 1 - 1e-15))))
    if link == 'gompit':
        return (lambda eta: 1 - np.exp(-np.exp(eta)), lambda mu: -(1 - mu) * np.log(np.clip(1 - mu, 1e-300, 1)))
    if link == 'log':
        return (lambda eta: np.exp(eta), lambda mu: mu)
    if link == 'sqrt':
        return (lambda eta: eta ** 2, lambda mu: 2 * np.sqrt(mu))
    if link == 'identity':
        return (lambda eta: eta, lambda mu: np.ones_like(mu))
    raise ValueError(link)

def _fit_irls(X, y, family, link, max_iter=100):
    inv, dmu = _link_funcs(link)
    p = X.shape[1]
    if family == 'binomial':
        mu = np.clip((y + 0.5) / 2, 0.05, 0.95)
        var = lambda m: m * (1 - m)
    else:
        mu = y + 0.5
        var = lambda m: m
    eta = {'logit': np.log(mu / (1 - mu)) if family == 'binomial' else None}.get(link)
    if eta is None:
        if link == 'normit':
            eta = stats.norm.ppf(mu)
        elif link == 'gompit':
            eta = np.log(-np.log(1 - mu))
        elif link == 'log':
            eta = np.log(mu)
        elif link == 'sqrt':
            eta = np.sqrt(mu)
        else:
            eta = mu.copy()
    beta = np.zeros(p)
    for _ in range(max_iter):
        mu = np.clip(inv(eta), 1e-12, 1 - 1e-12) if family == 'binomial' else np.maximum(inv(eta), 1e-12)
        d = dmu(mu)
        w = d * d / var(mu)
        z = eta + (y - mu) / d
        WX = X * w[:, None]
        new = np.linalg.solve(X.T @ WX, WX.T @ z)
        eta = X @ new
        if np.max(np.abs(new - beta)) < 1e-12 * (1 + np.max(np.abs(new))):
            beta = new
            break
        beta = new
    mu = np.clip(inv(eta), 1e-12, 1 - 1e-12) if family == 'binomial' else np.maximum(inv(eta), 1e-12)
    d = dmu(mu)
    w = d * d / var(mu)
    cov = np.linalg.inv(X.T @ (X * w[:, None]))
    return (beta, mu, w, cov)

def _deviance_terms(y, mu, family):
    if family == 'binomial':
        with np.errstate(divide='ignore', invalid='ignore'):
            t1 = np.where(y > 0, y * np.log(y / mu), 0.0)
            t2 = np.where(y < 1, (1 - y) * np.log((1 - y) / (1 - mu)), 0.0)
        return 2 * (t1 + t2)
    with np.errstate(divide='ignore', invalid='ignore'):
        t = np.where(y > 0, y * np.log(y / mu), 0.0)
    return 2 * (t - (y - mu))

def _loglik(y, mu, family):
    if family == 'binomial':
        return float((y * np.log(mu) + (1 - y) * np.log(1 - mu)).sum())
    return float((y * np.log(mu) - mu - np.array([math.lgamma(v + 1) for v in y])).sum())

def _auc(y, p):
    pos, neg = (p[y == 1], p[y == 0])
    if len(pos) == 0 or len(neg) == 0:
        return None
    r = stats.rankdata(np.concatenate([pos, neg]))
    return float((r[:len(pos)].sum() - len(pos) * (len(pos) + 1) / 2) / (len(pos) * len(neg)))

def _hosmer_lemeshow(y, p, groups=10):
    order = np.argsort(p, kind='mergesort')
    n = len(y)
    edges = [int(round(n * g / groups)) for g in range(groups + 1)]
    chi = 0.0
    used = 0
    for g in range(groups):
        idx = order[edges[g]:edges[g + 1]]
        if len(idx) == 0:
            continue
        used += 1
        o1, e1 = (y[idx].sum(), p[idx].sum())
        o0, e0 = (len(idx) - o1, len(idx) - e1)
        chi += (o1 - e1) ** 2 / e1 + (o0 - e0) ** 2 / e0
    df = used - 2
    return (chi, df)

def fit_glz(data: dict, response: str, terms: list[str], categorical: list[str] | None=None, family: str='binomial', link: str | None=None, event=None, conf: float=0.95, hl_groups: int=10) -> GLZResult:
    categorical = set(categorical or [])
    link = link or ('logit' if family == 'binomial' else 'log')
    cols = {p for t in terms for p in t.split('*')} | {response}
    n_all = len(data[response])
    keep = [i for i in range(n_all) if all((data[c][i] is not None for c in cols))]
    d = {c: [data[c][i] for i in keep] for c in cols}
    raw = d[response]
    ev = None
    if family == 'binomial':
        vals = _levels(raw)
        ev = vals[-1] if event is None else type(vals[0])(event) if not isinstance(vals[0], str) else str(event)
        y = np.array([1.0 if v == ev else 0.0 for v in raw])
    else:
        y = np.asarray(raw, dtype=float)
    n = len(y)
    order = list(dict.fromkeys((p for t in terms for p in t.split('*'))))
    levels = {c: _levels(d[c]) for c in order if c in categorical}
    Xc, names, groups, slices = ([np.ones(n)], ['Constant'], [None], [])
    for t in terms:
        cs, labels = _term_columns(t, d, categorical, levels)
        start = len(Xc)
        for c, lab in zip(cs, labels):
            Xc.append(c)
            names.append(t if lab is None else f'{t} {lab}')
            groups.append(None if lab is None else t)
        slices.append((t, list(range(start, len(Xc)))))
    X = np.column_stack(Xc)
    p = X.shape[1]
    beta, mu, w, cov = _fit_irls(X, y, family, link)
    se = np.sqrt(np.diag(cov))
    zq = stats.norm.ppf(1 - (1 - conf) / 2)
    sw = np.sqrt(w)
    Xw = X * sw[:, None]
    vifs = [None]
    for j in range(1, p):
        xj = Xw[:, j]
        others = np.delete(Xw, j, axis=1)
        r = xj - others @ np.linalg.lstsq(others, xj, rcond=None)[0]
        xm = xj - sw * (sw @ xj) / (sw @ sw)
        vifs.append(float(xm @ xm / (r @ r)))
    coefs = [GLZCoef(names[j], groups[j], float(beta[j]), float(se[j]), float(beta[j] / se[j]), float(2 * stats.norm.sf(abs(beta[j] / se[j]))), vifs[j]) for j in range(p)]
    res = GLZResult(family, link, n, None if ev is None else str(ev), int(y.sum()) if family == 'binomial' else None, coefs)
    if family == 'binomial' and link == 'logit':
        for t, idx in slices:
            if t not in categorical and '*' not in t:
                j = idx[0]
                res.odds_continuous.append({'term': t, 'odds': math.exp(beta[j]), 'ci': (math.exp(beta[j] - zq * se[j]), math.exp(beta[j] + zq * se[j]))})
            elif t in categorical:
                lv = levels[t]
                col = {lv[0]: None} | {l_: idx[k] for k, l_ in enumerate(lv[1:])}
                for a, b in combinations(lv, 2):
                    va = np.zeros(p)
                    if col[b] is not None:
                        va[col[b]] += 1
                    if col[a] is not None:
                        va[col[a]] -= 1
                    est = float(va @ beta)
                    s_ = float(np.sqrt(va @ cov @ va))
                    res.odds_categorical.append({'term': t, 'level_a': str(b), 'level_b': str(a), 'odds': math.exp(est), 'ci': (math.exp(est - zq * s_), math.exp(est + zq * s_))})
    dev_i = _deviance_terms(y, mu, family)
    dev = float(dev_i.sum())
    mu0 = np.full(n, y.mean())
    null_dev = float(_deviance_terms(y, mu0, family).sum())
    res.deviance, res.null_deviance = (dev, null_dev)
    res.dev_r_sq = 1 - dev / null_dev
    res.dev_r_sq_adj = 1 - (dev + (p - 1)) / null_dev
    ll = _loglik(y, mu, family)
    res.aic = -2 * ll + 2 * p
    res.aicc = res.aic + 2 * p * (p + 1) / (n - p - 1)
    res.bic = -2 * ll + p * math.log(n)
    var = mu * (1 - mu) if family == 'binomial' else mu
    pear = float(((y - mu) ** 2 / var).sum())
    df = n - p
    if family == 'binomial':
        res.auc = _auc(y, mu)
        res.gof = [{'test': 'Deviance', 'df': df, 'chi_square': dev, 'p': float(stats.chi2.sf(dev, df))}, {'test': 'Pearson', 'df': df, 'chi_square': pear, 'p': float(stats.chi2.sf(pear, df))}]
        hl, hdf = _hosmer_lemeshow(y, mu, hl_groups)
        res.gof.append({'test': 'Hosmer-Lemeshow', 'df': hdf, 'chi_square': hl, 'p': float(stats.chi2.sf(hl, hdf))})
    else:
        res.gof = [{'test': 'Deviance', 'df': df, 'estimate': dev, 'mean': dev / df, 'chi_square': dev, 'p': float(stats.chi2.sf(dev, df))}, {'test': 'Pearson', 'df': df, 'estimate': pear, 'mean': pear / df, 'chi_square': pear, 'p': float(stats.chi2.sf(pear, df))}]
    allc = list(range(1, p))
    b = beta[allc]
    wald = float(b @ np.linalg.solve(cov[np.ix_(allc, allc)], b))
    res.anova.append({'source': 'Regression', 'df': len(allc), 'chi_square': wald, 'p': float(stats.chi2.sf(wald, len(allc)))})
    for t, idx in slices:
        bb = beta[idx]
        wv = float(bb @ np.linalg.solve(cov[np.ix_(idx, idx)], bb))
        res.anova.append({'source': t, 'df': len(idx), 'chi_square': wv, 'p': float(stats.chi2.sf(wv, len(idx)))})
    h = w * np.einsum('ij,jk,ik->i', X, cov, X)
    dres = np.sign(y - mu) * np.sqrt(np.maximum(dev_i, 0))
    sres = dres / np.sqrt(1 - h)
    for i in range(n):
        if abs(sres[i]) > 2:
            res.unusual.append({'obs': keep[i] + 1, 'observed': float(y[i]), 'fit': float(mu[i]), 'resid': float(dres[i]), 'std_resid': float(sres[i])})
    res.fits = mu.tolist()
    cats = [c for c in order if c in categorical]
    for combo in list(__import__('itertools').product(*[levels[c] for c in cats])) if cats else [()]:
        setting = dict(zip(cats, combo))
        const = float(beta[0])
        slope_txt = ''
        for t, idx in slices:
            parts = t.split('*')
            if all((pp in categorical for pp in parts)):
                one = {c: [setting[c]] for c in parts}
                cs, _ = _term_columns(t, one, categorical, levels)
                const += sum((float(beta[j]) * float(c_[0]) for j, c_ in zip(idx, cs)))
            elif not any((pp in categorical for pp in parts)):
                v = float(beta[idx[0]])
                slope_txt += f" {('-' if v < 0 else '+')} {abs(v):.6g} {t}"
        res.equations.append((' '.join((str(c) for c in combo)) if combo else None, f"Y' = {const:.6g}{slope_txt}"))
    return res

qualistat/regression/multinomial.py:
from __future__ import annotations
import math
import numpy as np
from scipy import stats

def _exp(v):
    return math.exp(v) if v < 700 else math.inf

def _sort_levels(v):
    u = list(dict.fromkeys(v))
    try:
        return sorted(u, key=float)
    except (TypeError, ValueError):
        return sorted(u, key=str)

def _cdf_pdf(link):
    if link == 'logit':
        return (lambda z: 1 / (1 + np.exp(-z)), lambda z: np.exp(-z) / (1 + np.exp(-z)) ** 2)
    if link == 'normit':
        return (stats.norm.cdf, stats.norm.pdf)
    if link == 'gompit':
        return (lambda z: 1 - np.exp(-np.exp(z)), lambda z: np.exp(z - np.exp(z)))
    raise ValueError(link)

def _scoring(info_score, x0, max_iter=20, tol=0.0001):
    x = np.array(x0, dtype=float)
    info = None
    for _ in range(max_iter):
        info, g = info_score(x)
        step = np.linalg.solve(info, g)
        x = x + step
        if np.max(np.abs(step) / np.maximum(np.abs(x), 1.0)) < tol:
            break
    return (x, info)

def _patterns(X):
    keys = [tuple(r) for r in X]
    uniq = list(dict.fromkeys(keys))
    idx = np.array([uniq.index(k) for k in keys])
    return (idx, len(uniq))

def _gof(Y, P, idx, npat, npar):
    k = Y.shape[1]
    O = np.zeros((npat, k))
    E = np.zeros((npat, k))
    np.add.at(O, idx, Y)
    np.add.at(E, idx, P)
    pearson = float(((O - E) ** 2 / E).sum())
    with np.errstate(divide='ignore', invalid='ignore'):
        dev = float(2 * np.where(O > 0, O * np.log(O / E), 0.0).sum())
    df = npat * (k - 1) - npar
    return [{'method': 'Pearson', 'chi_square': pearson, 'df': df, 'p': float(stats.chi2.sf(pearson, df))}, {'method': 'Deviance', 'chi_square': dev, 'df': df, 'p': float(stats.chi2.sf(dev, df))}]

def _design(data, predictors):
    cols = [np.array([float(v) for v in data[p]]) for p in predictors]
    return np.column_stack(cols) if cols else np.zeros((len(next(iter(data.values()))), 0))

def ordinal_logistic(data: dict, response: str, predictors: list[str], link: str='logit', order: list | None=None, confidence: float=95.0) -> dict:
    yraw = [str(v) for v in data[response]]
    levels = [str(v) for v in order] if order else [str(v) for v in _sort_levels(data[response])]
    yi = np.array([levels.index(v) for v in yraw])
    X = _design(data, predictors)
    n, p = X.shape
    k = len(levels)
    F, f = _cdf_pdf(link)

    def probs(par):
        th, b = (par[:k - 1], par[k - 1:])
        eta = X @ b
        cum = F(th[None, :] + eta[:, None])
        cum = np.column_stack([np.zeros(n), cum, np.ones(n)])
        return (cum, eta)

    def info_score(par):
        th, b = (par[:k - 1], par[k - 1:])
        z = th[None, :] + (X @ b)[:, None]
        cum = np.column_stack([np.zeros(n), F(z), np.ones(n)])
        dens = np.column_stack([np.zeros(n), f(z), np.zeros(n)])
        info = np.zeros((len(par), len(par)))
        g = np.zeros(len(par))
        for j in range(k):
            pj = cum[:, j + 1] - cum[:, j]
            D = np.zeros((n, len(par)))
            if j < k - 1:
                D[:, j] += dens[:, j + 1]
            if j > 0:
                D[:, j - 1] -= dens[:, j]
            D[:, k - 1:] = X * (dens[:, j + 1] - dens[:, j])[:, None]
            info += (D / pj[:, None]).T @ D
            g += (yi == j) / pj @ D
        return (info, g)
    counts = np.bincount(yi, minlength=k)
    cumf = np.cumsum(counts)[:-1] / n
    finv = {'logit': lambda q: np.log(q / (1 - q)), 'normit': stats.norm.ppf, 'gompit': lambda q: np.log(-np.log(1 - q))}[link]
    par, info = _scoring(info_score, np.concatenate([finv(cumf), np.zeros(p)]))
    se = np.sqrt(np.diag(np.linalg.inv(info)))
    cum, eta = probs(par)
    P = np.diff(cum, axis=1)
    nll = -float(np.log(P[np.arange(n), yi]).sum())
    ll0 = float((counts[counts > 0] * np.log(counts[counts > 0] / n)).sum())
    G = 2 * (-nll - ll0)
    zc = stats.norm.ppf(0.5 + confidence / 200)
    names = [f'Const({j + 1})' for j in range(k - 1)] + list(predictors)
    coefs = []
    for i, nm in enumerate(names):
        z = par[i] / se[i]
        row = {'term': nm, 'coef': float(par[i]), 'se': float(se[i]), 'z': float(z), 'p': float(2 * stats.norm.sf(abs(z)))}
        if i >= k - 1 and link == 'logit':
            row.update(odds_ratio=_exp(par[i]), lower=_exp(par[i] - zc * se[i]), upper=_exp(par[i] + zc * se[i]))
        coefs.append(row)
    Y = np.eye(k)[yi]
    idx, npat = _patterns(X)
    score = -eta
    conc = disc = ties = 0
    for i in range(n):
        for j in range(i + 1, n):
            if yi[i] == yi[j]:
                continue
            d = (yi[i] - yi[j]) * (score[i] - score[j])
            if abs(score[i] - score[j]) < 1e-12:
                ties += 1
            elif d > 0:
                conc += 1
            else:
                disc += 1
    tot = conc + disc + ties
    return {'link': link, 'levels': levels, 'counts': [int(c) for c in counts], 'n': n, 'coefficients': coefs, 'log_likelihood': -nll, 'slopes_test': {'df': p, 'g': G, 'p': float(stats.chi2.sf(G, p))}, 'gof': _gof(Y, P, idx, npat, len(par)), 'association': {'concordant': conc, 'discordant': disc, 'ties': ties, 'total': tot, 'somers_d': (conc - disc) / tot, 'gamma': (conc - disc) / (conc + disc), 'tau_a': (conc - disc) / (n * (n - 1) / 2)}, 'probabilities': P.tolist()}

def nominal_logistic(data: dict, response: str, predictors: list[str], reference: str | None=None, confidence: float=95.0) -> dict:
    yraw = [str(v) for v in data[response]]
    levels = [str(v) for v in _sort_levels(data[response])]
    ref = str(reference) if reference is not None else levels[-1]
    others = [lv for lv in reversed(levels) if lv != ref]
    X = _design(data, predictors)
    n, p = X.shape
    Xd = np.column_stack([np.ones(n), X])
    q = p + 1
    m = len(others)
    Y = np.column_stack([[1.0 if v == lv else 0.0 for v in yraw] for lv in others])
    yref = np.array([1.0 if v == ref else 0.0 for v in yraw])

    def probs(par):
        B = par.reshape(m, q)
        E = np.exp(np.clip(Xd @ B.T, -700, 700))
        den = 1 + E.sum(1)
        return (E / den[:, None], 1 / den)

    def info_score(par):
        P, _ = probs(par)
        info = np.zeros((m * q, m * q))
        for a in range(m):
            for b in range(m):
                w = P[:, a] * ((a == b) - P[:, b])
                info[a * q:(a + 1) * q, b * q:(b + 1) * q] = (Xd * w[:, None]).T @ Xd
        return (info, ((Y - P).T @ Xd).ravel())
    nref = float(yref.sum())
    x0 = np.zeros((m, q))
    x0[:, 0] = np.log(Y.sum(0) / nref)
    par, info = _scoring(info_score, x0.ravel())
    se = np.sqrt(np.diag(np.linalg.inv(info)))
    P, p0 = probs(par)
    nll = -float((Y * np.log(P)).sum() + (yref * np.log(p0)).sum())
    counts = {lv: yraw.count(lv) for lv in levels}
    cnt = np.array([c for c in counts.values() if c > 0], dtype=float)
    ll0 = float((cnt * np.log(cnt / n)).sum())
    G = 2 * (-nll - ll0)
    zc = stats.norm.ppf(0.5 + confidence / 200)
    logits = []
    for j, lv in enumerate(others):
        rows = []
        for t, nm in enumerate(['Constant'] + list(predictors)):
            i = j * q + t
            z = par[i] / se[i]
            row = {'term': nm, 'coef': float(par[i]), 'se': float(se[i]), 'z': float(z), 'p': float(2 * stats.norm.sf(abs(z)))}
            if t > 0:
                row.update(odds_ratio=_exp(par[i]), lower=_exp(par[i] - zc * se[i]), upper=_exp(par[i] + zc * se[i]))
            rows.append(row)
        logits.append({'label': f'Logit {j + 1}: ({lv}/{ref})', 'level': lv, 'coefficients': rows})
    idx, npat = _patterns(X)
    gof = _gof(np.column_stack([Y, yref]), np.column_stack([P, p0]), idx, npat, len(par))
    return {'reference': ref, 'levels': [ref] + others, 'counts': [counts[ref]] + [counts[lv] for lv in others], 'n': n, 'logits': logits, 'log_likelihood': -nll, 'slopes_test': {'df': m * p, 'g': G, 'p': float(stats.chi2.sf(G, m * p))}, 'gof': gof}

