from __future__ import annotations
import ast
import math
import re
import numpy as np
from scipy import stats
_FUNCS = {'exp': np.exp, 'expo': np.exp, 'ln': np.log, 'loge': np.log, 'log': np.log10, 'logten': np.log10, 'log10': np.log10, 'sqrt': np.sqrt, 'sqrt2': np.sqrt, 'abs': np.abs, 'absolute': np.abs, 'sin': np.sin, 'cos': np.cos, 'tan': np.tan, 'asin': np.arcsin, 'acos': np.arccos, 'atan': np.arctan, 'arcsin': np.arcsin, 'arccos': np.arccos, 'arctan': np.arctan, 'sinh': np.sinh, 'cosh': np.cosh, 'tanh': np.tanh, 'signs': np.sign}
_BIN = {ast.Add: np.add, ast.Sub: np.subtract, ast.Mult: np.multiply, ast.Div: np.divide, ast.Pow: np.power}

def compile_expression(expr: str):
    src = re.sub("'([^']+)'", lambda m: '__q_' + re.sub('\\W', '_', m.group(1)), expr)
    src = src.replace('^', '**')
    tree = ast.parse(src, mode='eval')
    names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Expression, ast.Load, ast.operator, ast.unaryop)):
            continue
        if isinstance(node, ast.BinOp):
            if type(node.op) not in _BIN:
                raise ValueError('İzin verilmeyen işlem.')
        elif isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, (ast.USub, ast.UAdd)):
                raise ValueError('İzin verilmeyen işlem.')
        elif isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id.lower() not in _FUNCS or node.keywords or (len(node.args) != 1):
                raise ValueError(f'İzin verilmeyen fonksiyon: {ast.unparse(node.func)}')
        elif isinstance(node, ast.Name):
            names.add(node.id)
        elif isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                raise ValueError('Yalnız sayısal sabitler kullanılabilir.')
        else:
            raise ValueError('Geçersiz ifade.')
    call_names = {n.func.id for n in ast.walk(tree) if isinstance(n, ast.Call)}
    return (tree, names - call_names)

def _eval(node, env):
    if isinstance(node, ast.Expression):
        return _eval(node.body, env)
    if isinstance(node, ast.BinOp):
        return _BIN[type(node.op)](_eval(node.left, env), _eval(node.right, env))
    if isinstance(node, ast.UnaryOp):
        v = _eval(node.operand, env)
        return -v if isinstance(node.op, ast.USub) else v
    if isinstance(node, ast.Call):
        return _FUNCS[node.func.id.lower()](_eval(node.args[0], env))
    if isinstance(node, ast.Name):
        return env[node.id]
    return float(node.value)

def _keys(name: str) -> list[str]:
    q = '__q_' + re.sub('\\W', '_', name)
    return [name, q] if name.isidentifier() else [q]

def nonlinear_regression(response, predictors: dict, expression: str, start: dict, max_iter: int=200, tolerance: float=1e-05, algorithm: str='gauss-newton', confidence: float=95.0) -> dict:
    tree, used = compile_expression(expression)
    params = list(start)
    cols = {key: k for k in predictors for key in _keys(k)}
    unknown = used - set(params) - set(cols)
    if unknown:
        raise ValueError(f"Tanımsız ad: {', '.join(sorted(unknown))}")
    keep = [i for i in range(len(response)) if response[i] is not None and all((predictors[c][i] is not None for c in predictors))]
    y = np.array([float(response[i]) for i in keep])
    data = {k: np.array([float(predictors[orig][i]) for i in keep]) for k, orig in cols.items()}
    n, p = (len(y), len(params))

    def f(theta):
        env = dict(data)
        env.update({nm: theta[j] for j, nm in enumerate(params)})
        with np.errstate(all='ignore'):
            return np.broadcast_to(np.asarray(_eval(tree, env), dtype=float), y.shape).astype(float)

    def jac(theta):
        J = np.zeros((n, p))
        for j in range(p):
            h = 1e-06 * max(1.0, abs(theta[j]))
            e = np.zeros(p)
            e[j] = h
            J[:, j] = (f(theta + e) - f(theta - e)) / (2 * h)
        return J
    theta = np.array([float(start[nm]) for nm in params])
    r = y - f(theta)
    sse = float(r @ r)
    if not np.isfinite(sse):
        raise ValueError('Başlangıç değerlerinde ifade hesaplanamıyor.')
    mu = 0.001
    iters, converged = (0, False)
    for iters in range(1, max_iter + 1):
        J = jac(theta)
        A = J.T @ J
        g = J.T @ r
        while True:
            if algorithm == 'levenberg-marquardt':
                step = np.linalg.solve(A + mu * np.diag(np.diag(A)), g)
            else:
                step = np.linalg.lstsq(J, r, rcond=None)[0]
            lam = 1.0
            ok = False
            while lam > 1e-10:
                new = theta + lam * step
                rn = y - f(new)
                ssen = float(rn @ rn)
                if np.isfinite(ssen) and ssen <= sse:
                    ok = True
                    break
                lam /= 2
            if ok or algorithm != 'levenberg-marquardt':
                break
            mu *= 10
            if mu > 10000000000.0:
                break
        if not ok:
            converged = True
            break
        rel = np.max(np.abs(new - theta) / np.maximum(np.abs(theta), 1e-10))
        theta, r, sse = (new, rn, ssen)
        if algorithm == 'levenberg-marquardt':
            mu = max(mu / 10, 1e-12)
        if rel < tolerance:
            converged = True
            break
    J = jac(theta)
    dfe = n - p
    mse = sse / dfe
    cov = np.linalg.pinv(J.T @ J) * mse
    se = np.sqrt(np.diag(cov))
    tq = stats.t.ppf(0.5 + confidence / 200, dfe)
    est = [{'parameter': nm, 'estimate': float(theta[j]), 'se': float(se[j]), 'lower': float(theta[j] - tq * se[j]), 'upper': float(theta[j] + tq * se[j])} for j, nm in enumerate(params)]
    fits = f(theta)
    return {'expression': expression, 'n': n, 'parameters': est, 'iterations': iters, 'converged': converged, 'sse': sse, 'dfe': dfe, 'mse': mse, 's': math.sqrt(mse), 'fits': fits.tolist(), 'residuals': (y - fits).tolist(), 'covariance': cov.tolist()}

