import math
from dataclasses import dataclass, field
import numpy as np
from scipy import optimize, special, stats
LOG_FAMILIES = {'weibull': 'sev', 'exponential': 'sev', 'lognormal': 'normal', 'loglogistic': 'logistic'}
LIN_FAMILIES = {'normal': 'normal', 'logistic': 'logistic', 'sev': 'sev'}

def _std(fam: str):
    if fam == 'sev':
        return (lambda z: z - np.exp(z), lambda z: 1 - np.exp(z), lambda z: -np.exp(z), lambda z: -np.exp(z), lambda z: -np.exp(z), lambda z: -np.exp(z), lambda z: 1 - np.exp(-np.exp(z)), lambda p: np.log(-np.log(1 - p)))
