        mu, s, cov, ll_y = _fit_location_scale(y, fail, fam, fixed)
    if start is None and method == 'lsxy':
        mu, s, corr = _lsxy(t, fail, fam, logscale)
        a, _, _, b, _, _, _, _ = _std(fam)
        zz = (y - mu) / s
        ll_y = float(np.where(fail, a(zz) - math.log(s), 0).sum() + np.where(~fail, b(zz), 0).sum())
        cov = None
    if start is None:
        loglik = ll_y - (y[fail].sum() if logscale else 0.0)
    z = stats.norm.ppf(1 - (1 - conf) / 2)
    _, _, _, _, _, _, G, ppf = _std(fam)

