    elif dist == 'normal':
        params = [est('Mean', lambda m, s_: m, False), est('StDev', lambda m, s_: s_, True)]
    else:
        params = [est('Location', lambda m, s_: m, False), est('Scale', lambda m, s_: s_, True)]

    def quant(p):
