        res = ParametricResult(dist, counts['exact'], counts['right'] + counts['interval'] + counts['left'], params, float(loglik), chars, pcts, surv, mu, s)
        res.censoring = counts
    else:
        res = ParametricResult(dist, int(fail.sum()), int((~fail).sum()), params, float(loglik), chars, pcts, surv, mu, s)
    res.correlation = corr
    return res

def kaplan_meier(times, censor=None, censor_value=0, conf: float=0.95) -> dict:
    t, fail = _prepare(times, censor, censor_value)
    order = np.lexsort((~fail, t))
    t, fail = (t[order], fail[order])
    z = stats.norm.ppf(1 - (1 - conf) / 2)
    n = len(t)
    S, var_sum = (1.0, 0.0)
    rows = []
    i = 0
    while i < n:
        j = i
        while j < n and t[j] == t[i]:
            j += 1
        d = int(fail[i:j].sum())
        at_risk = n - i
        if d > 0:
            S *= 1 - d / at_risk
            var_sum += d / (at_risk * (at_risk - d)) if at_risk > d else float('inf')
            se = S * math.sqrt(var_sum) if math.isfinite(var_sum) else 0.0
            rows.append({'time': float(t[i]), 'at_risk': at_risk, 'failed': d, 'survival': S, 'se': se, 'ci': (max(0.0, S - z * se), min(1.0, S + z * se))})
        i = j
    t_max = float(t.max())
    area, prev_t, prev_s = (0.0, 0.0, 1.0)
    for r in rows:
        area += prev_s * (r['time'] - prev_t)
        prev_t, prev_s = (r['time'], r['survival'])
    area += prev_s * (t_max - prev_t)
    var = 0.0
    for k, r in enumerate(rows):
        a_k, ps, pt = (0.0, r['survival'], r['time'])
        for r2 in rows[k + 1:]:
            a_k += ps * (r2['time'] - pt)
            ps, pt = (r2['survival'], r2['time'])
        a_k += ps * (t_max - pt)
        if r['at_risk'] > r['failed']:
            var += a_k ** 2 * r['failed'] / (r['at_risk'] * (r['at_risk'] - r['failed']))
    r_eff = int(fail.sum()) + (0 if fail[-1] else 1)
    mttf_se = math.sqrt(var * r_eff / (r_eff - 1)) if r_eff > 1 else float('nan')

    def q(p):
        for r in rows:
            if r['survival'] <= 1 - p + 1e-12:
                return r['time']
        return None
    return {'rows': rows, 'mttf': area, 'mttf_se': mttf_se, 'mttf_ci': (area - z * mttf_se, area + z * mttf_se), 'q1': q(0.25), 'median': q(0.5), 'q3': q(0.75), 'n_uncensored': int(fail.sum()), 'n_censored': int((~fail).sum())}

