from __future__ import annotations
import math
import numpy as np
from scipy import stats
from .distribution import LIN_FAMILIES, LOG_FAMILIES, _std
BOLTZMANN_EV = 11604.83

def _same(a, b) -> bool:
    if str(a).strip() == str(b).strip():
        return True
    try:
        return float(a) == float(b)
    except (TypeError, ValueError):
        return False

def transform_stress(x, relationship: str):
    x = np.asarray(x, dtype=float)
    if relationship == 'arrhenius':
        return BOLTZMANN_EV / (x + 273.16)
    if relationship == 'invtemp':
        return 1 / (x + 273.16)
    if relationship == 'ln':
        return np.log(x)
    if relationship == 'linear':
        return x
    raise ValueError(f'Bilinmeyen ilişki: {relationship}')

def life_regression(times, stresses: dict, censor=None, censor_value=0, distribution: str='weibull', relationships: dict | None=None, confidence: float=95.0) -> dict:
    fam = LOG_FAMILIES.get(distribution) or LIN_FAMILIES.get(distribution)
    if fam is None:
        raise ValueError(f'Bilinmeyen dağılım: {distribution}')
    logscale = distribution in LOG_FAMILIES
    names = list(stresses)
    relationships = relationships or {}
    n_all = len(times)
    keep = [i for i in range(n_all) if times[i] is not None and all((stresses[k][i] is not None for k in names))]
    t = np.array([float(times[i]) for i in keep])
    fail = np.ones(len(t), dtype=bool) if censor is None else np.array([not _same(censor[i], censor_value) for i in keep])
    y = np.log(t) if logscale else t
    cols = [transform_stress([float(stresses[k][i]) for i in keep], relationships.get(k, 'linear')) for k in names]
    X = np.column_stack([np.ones(len(t))] + cols)
    p = X.shape[1]
    lg, lg1, lg2, ls, ls1, ls2, _, _ = _std(fam)
    d = fail.astype(float)

    def parts(par):
        b, s = (par[:p], par[p])
        z = (y - X @ b) / s
        h0 = np.where(fail, lg(z), ls(z))
        h1 = np.where(fail, lg1(z), ls1(z))
        h2 = np.where(fail, lg2(z), ls2(z))
        return (b, s, z, h0, h1, h2)

    def loglik(par):
        b, s, z, h0, *_ = parts(par)
        return float((h0 - d * math.log(s) - (d * y if logscale else 0)).sum())

    def grad_hess(par):
        b, s, z, h0, h1, h2 = parts(par)
        g = np.r_[X.T @ (-h1 / s), (-h1 * z / s - d / s).sum()]
        H = np.zeros((p + 1, p + 1))
        H[:p, :p] = (X * (h2 / s ** 2)[:, None]).T @ X
        H[:p, p] = X.T @ ((h2 * z + h1) / s ** 2)
        H[p, :p] = H[:p, p]
        H[p, p] = ((h2 * z * z + 2 * h1 * z + d) / s ** 2).sum()
        return (g, H)
    fixed = distribution == 'exponential'
    free = p if fixed else p + 1
    b0 = np.linalg.lstsq(X[fail], y[fail], rcond=None)[0]
    s0 = 1.0 if fixed else max(float(np.std(y[fail] - X[fail] @ b0)), 0.001)
    par = np.r_[b0, s0]
    ll = loglik(par)
    for _ in range(200):
        g, H = grad_hess(par)
        step = np.zeros(p + 1)
        step[:free] = np.linalg.solve(H[:free, :free], -g[:free])
        lam = 1.0
        while True:
            new = par + lam * step
            if new[p] > 0:
                lln = loglik(new)
                if np.isfinite(lln) and lln >= ll - 1e-12:
                    break
            lam /= 2
            if lam < 1e-12:
                new, lln = (par, ll)
                break
        conv = np.max(np.abs(new - par)) < 1e-11
        par, ll = (new, lln)
        if conv:
            break
    _, H = grad_hess(par)
    cov = np.zeros((p + 1, p + 1))
    cov[:free, :free] = np.linalg.inv(-H[:free, :free])
    se = np.sqrt(np.diag(cov))
    zc = stats.norm.ppf(0.5 + confidence / 200)
    coefs = []
    for i, nm in enumerate(['Intercept'] + names):
        z = par[i] / se[i]
        coefs.append({'term': nm, 'coef': float(par[i]), 'se': float(se[i]), 'z': float(z), 'p': float(2 * stats.norm.sf(abs(z))), 'lower': float(par[i] - zc * se[i]), 'upper': float(par[i] + zc * se[i])})
    s, ses = (float(par[p]), float(se[p]))
    if distribution == 'weibull':
        est, est_se, label = (1 / s, ses / s ** 2, 'Shape')
    else:
        est, est_se, label = (s, ses, 'Scale')
    if not fixed:
        w = math.exp(zc * est_se / est)
        coefs.append({'term': label, 'coef': est, 'se': est_se, 'z': None, 'p': None, 'lower': est / w, 'upper': est * w})
    return {'distribution': distribution, 'n': len(t), 'failures': int(fail.sum()), 'censored': int((~fail).sum()), 'relationships': {k: relationships.get(k, 'linear') for k in names}, 'coefficients': coefs, 'log_likelihood': ll, 'covariance': cov.tolist()}

