from __future__ import annotations
import math
from scipy import stats
from .distribution import parametric_analysis

def preprocess_warranty(shipments, returns: list[list]) -> dict:
    n = len(shipments)
    ship = [float(v) for v in shipments]
    if len(returns) != n:
        raise ValueError('Her dönem için bir iade sütunu gerekli.')
    by_age: dict[int, float] = {}
    returned = [0.0] * n
    for j, col in enumerate(returns):
        vals = [v for v in col[:j + 1]]
        if len(vals) < j + 1 or any((v is None for v in vals)):
            raise ValueError(f'{j + 1}. iade sütununun ilk {j + 1} satırı dolu olmalı.')
        for i, v in enumerate(vals):
            a = j - i + 1
            by_age[a] = by_age.get(a, 0.0) + float(v)
            returned[i] += float(v)
    start, end, freq = ([], [], [])
    for a in sorted(by_age):
        if by_age[a] > 0:
            start.append(a - 1)
            end.append(a)
            freq.append(by_age[a])
    for i in reversed(range(n)):
        surv = ship[i] - returned[i]
        if surv < 0:
            raise ValueError(f'{i + 1}. sevkiyatta iade sayısı sevkiyattan büyük.')
        start.append(n - i)
        end.append(None)
        freq.append(surv)
    return {'start': start, 'end': end, 'freq': freq, 'shipped': sum(ship), 'returns': sum(returned), 'at_risk': sum(ship) - sum(returned)}

def _poisson_ci(x: float, conf: float):
    a = 1 - conf
    lo = stats.chi2.ppf(a / 2, 2 * x) / 2 if x > 0 else 0.0
    return (float(lo), float(stats.chi2.ppf(1 - a / 2, 2 * x + 2) / 2))

def warranty_prediction(start, end, freq, distribution: str='weibull', periods: int=1, production: list[float] | float | None=None, warranty_length: float | None=None, confidence: float=0.95, cost: float | None=None) -> dict:
    fit = parametric_analysis(None, distribution=distribution, start=start, end=end, freq=freq, conf=confidence)
    mu, s = (fit.mu, fit.sigma)
    from .distribution import LOG_FAMILIES, _std
    logscale = distribution in LOG_FAMILIES
    G = _std(LOG_FAMILIES.get(distribution) or distribution)[6]

    def F(t):
        if t <= 0:
            return 0.0
        return float(G(((math.log(t) if logscale else t) - mu) / s))
    W = warranty_length
    risk = [(float(f), float(a)) for a, e, f in zip(start, end, freq) if e is None and f > 0]
    if W is not None:
        risk = [(n, a) for n, a in risk if a < W]
    at_risk = sum((n for n, _ in risk))
    if production is None:
        prod = [0.0] * periods
    elif isinstance(production, (int, float)):
        prod = [float(production)] * periods
    else:
        prod = [float(v) for v in production] + [0.0] * max(0, periods - len(production))
    rows = []
    for k in range(1, periods + 1):
        tot = 0.0
        for n, a in risk:
            hi = a + k if W is None else min(a + k, W)
            tot += n * (F(hi) - F(a)) / (1 - F(a))
        for m in range(1, k + 1):
            age = k - m + 1
            tot += prod[m - 1] * F(age if W is None else min(age, W))
        lo, hi_ = _poisson_ci(tot, confidence)
        row = {'period': k, 'potential': at_risk + sum(prod[:k]), 'predicted': tot, 'lower': lo, 'upper': hi_}
        if cost is not None:
            row.update(cost=tot * cost, cost_lower=lo * cost, cost_upper=hi_ * cost)
        rows.append(row)
    return {'distribution': distribution, 'parameters': [{'name': p.name, 'estimate': p.estimate} for p in fit.parameters], 'total_units': float(sum(freq)), 'observed_failures': float(sum((f for e, f in zip(end, freq) if e is not None))), 'units_at_risk': at_risk, 'warranty_length': W, 'production': prod, 'table': rows}

