from __future__ import annotations
from dataclasses import dataclass
from enum import StrEnum
from typing import Sequence
import numpy as np
from .constants import c4, d2, d3, d4, mssd_unbiasing
RBAR_MAX_SUBGROUP = 100
_SBAR_DF_FACTOR = [(2, 0.88), (3, 0.92), (4, 0.94), (5, 0.95), (7, 0.96), (9, 0.97), (17, 0.98), (64, 0.99)]
_RBAR_DF_FACTOR = 0.9

class WithinMethod(StrEnum):
    POOLED = 'pooled'
    RBAR = 'rbar'
    SBAR = 'sbar'
    AVG_MR = 'avg_mr'
    MEDIAN_MR = 'median_mr'
    SQRT_MSSD = 'sqrt_mssd'

class SigmaError(ValueError):
    pass

@dataclass(frozen=True)
class SigmaEstimate:
    value: float
    method: str
    df: float

def split_subgroups(values: np.ndarray, subgroup: int | Sequence) -> list[np.ndarray]:
    values = np.asarray(values, dtype=float)
    if isinstance(subgroup, (int, np.integer)):
        n = int(subgroup)
        if n < 1:
            raise ValueError('alt grup boyutu >= 1 olmalı')
        chunks = [values[i:i + n] for i in range(0, len(values), n)]
    else:
        ids = list(subgroup)
        if len(ids) != len(values):
            raise ValueError('alt grup sütunu veriyle aynı uzunlukta olmalı')
        chunks, start = ([], 0)
        for i in range(1, len(ids) + 1):
            if i == len(ids) or ids[i] != ids[i - 1]:
                chunks.append(values[start:i])
                start = i
    return [c[~np.isnan(c)] for c in chunks]

def _sbar_df_factor(n: int) -> float:
    for upper, f in _SBAR_DF_FACTOR:
        if n <= upper:
            return f
    return 1.0

def _mean_subgroup_size(groups: list[np.ndarray]) -> int:
    sizes = [len(g) for g in groups if len(g) > 0]
    return max(2, int(np.mean(sizes) + 0.5))

def pooled_sd(groups: list[np.ndarray], unbiased: bool=True) -> SigmaEstimate:
    ss = sum((float(((g - g.mean()) ** 2).sum()) for g in groups if len(g) > 1))
    dof = sum((len(g) - 1 for g in groups if len(g) > 0))
    if dof < 1:
        raise SigmaError('birleştirilmiş standart sapma için yeterli veri yok')
    sp = np.sqrt(ss / dof)
    value = sp / c4(dof + 1) if unbiased else sp
    return SigmaEstimate(value, WithinMethod.POOLED, float(dof))

def rbar(groups: list[np.ndarray]) -> SigmaEstimate:
    usable = [g for g in groups if len(g) >= 2]
    if not usable:
        raise SigmaError('R̄ yöntemi için en az bir alt grupta 2 gözlem gerekir')
    if max((len(g) for g in usable)) > RBAR_MAX_SUBGROUP:
        raise SigmaError(f"R̄ yöntemi alt grup boyutu {RBAR_MAX_SUBGROUP}'ü aşınca kullanılamaz")
    num = den = 0.0
    for g in usable:
        n = len(g)
        f = d2(n) ** 2 / d3(n) ** 2
        num += f * float(g.max() - g.min()) / d2(n)
        den += f
    nbar = _mean_subgroup_size(groups)
    dof = _RBAR_DF_FACTOR * len(groups) * (nbar - 1)
    return SigmaEstimate(num / den, WithinMethod.RBAR, dof)

def sbar(groups: list[np.ndarray], unbiased: bool=True) -> SigmaEstimate:
    usable = [g for g in groups if len(g) >= 2]
    if not usable:
        raise SigmaError('S̄ yöntemi için en az bir alt grupta 2 gözlem gerekir')
    num = den = 0.0
    for g in usable:
        n = len(g)
        s = float(g.std(ddof=1))
        h = c4(n) ** 2 / (1 - c4(n) ** 2)
        num += h * (s / c4(n) if unbiased else s)
        den += h
    nbar = _mean_subgroup_size(groups)
    dof = _sbar_df_factor(nbar) * len(groups) * (nbar - 1)
    return SigmaEstimate(num / den, WithinMethod.SBAR, dof)

def moving_ranges(x: np.ndarray, span: int) -> np.ndarray:
    x = np.asarray(x, dtype=float)
    if len(x) < span:
        return np.array([])
    windows = np.lib.stride_tricks.sliding_window_view(x, span)
    mr = windows.max(axis=1) - windows.min(axis=1)
    return mr[~np.isnan(mr)]

def average_mr(x: np.ndarray, span: int=2, unbiased: bool=True) -> SigmaEstimate:
    mr = moving_ranges(x, span)
    if len(mr) == 0:
        raise SigmaError('hareketli aralık için yeterli veri yok')
    value = mr.mean() / d2(span) if unbiased else mr.mean()
    n = int(np.count_nonzero(~np.isnan(x)))
    return SigmaEstimate(float(value), WithinMethod.AVG_MR, float(n - span + 1))

def median_mr(x: np.ndarray, span: int=2, unbiased: bool=True) -> SigmaEstimate:
    mr = moving_ranges(x, span)
    if len(mr) == 0:
        raise SigmaError('hareketli aralık için yeterli veri yok')
    value = np.median(mr) / d4(span) if unbiased else np.median(mr)
    n = int(np.count_nonzero(~np.isnan(x)))
    return SigmaEstimate(float(value), WithinMethod.MEDIAN_MR, float(n - span + 1))

def sqrt_mssd(x: np.ndarray, unbiased: bool=True) -> SigmaEstimate:
    x = np.asarray(x, dtype=float)
    diffs = np.diff(x)
    diffs = diffs[~np.isnan(diffs)]
    if len(diffs) == 0:
        raise SigmaError('MSSD için yeterli veri yok')
    value = np.sqrt((diffs ** 2).sum() / (2 * len(diffs)))
    n = int(np.count_nonzero(~np.isnan(x)))
    if unbiased:
        value /= mssd_unbiasing(len(diffs) + 1)
    return SigmaEstimate(float(value), WithinMethod.SQRT_MSSD, float(n - 1))

def within_sigma(values: np.ndarray, subgroup: int | Sequence, method: WithinMethod | None=None, unbiased: bool=True, mr_span: int=2) -> SigmaEstimate:
    values = np.asarray(values, dtype=float)
    groups = split_subgroups(values, subgroup)
    individual = max((len(g) for g in groups), default=0) < 2
    if method is None:
        method = WithinMethod.AVG_MR if individual else WithinMethod.POOLED
    if method in (WithinMethod.AVG_MR, WithinMethod.MEDIAN_MR, WithinMethod.SQRT_MSSD):
        if not individual:
            raise SigmaError('hareketli aralık yöntemleri yalnızca alt grup boyutu 1 iken kullanılır')
        if method is WithinMethod.AVG_MR:
            return average_mr(values, mr_span, unbiased)
        if method is WithinMethod.MEDIAN_MR:
            return median_mr(values, mr_span, unbiased)
        return sqrt_mssd(values, unbiased)
    if individual:
        raise SigmaError('alt grup yöntemleri için alt grup boyutu en az 2 olmalı')
    if method is WithinMethod.POOLED:
        return pooled_sd(groups, unbiased)
    if method is WithinMethod.RBAR:
        return rbar(groups)
    return sbar(groups, unbiased)

def overall_sigma(values: np.ndarray, unbiased: bool=False) -> SigmaEstimate:
    x = np.asarray(values, dtype=float)
    x = x[~np.isnan(x)]
    if len(x) < 2:
        raise SigmaError('genel standart sapma için en az 2 gözlem gerekir')
    s = float(x.std(ddof=1))
    return SigmaEstimate(s / c4(len(x)) if unbiased else s, 'overall', float(len(x) - 1))

def between_within_sigma(values: np.ndarray, subgroup: int | Sequence, method: WithinMethod | None=None, unbiased: bool=True) -> SigmaEstimate:
    values = np.asarray(values, dtype=float)
    groups = [g for g in split_subgroups(values, subgroup) if len(g) > 0]
    sw = within_sigma(values, subgroup, method or WithinMethod.POOLED, unbiased).value
    means = np.array([g.mean() for g in groups])
    sm = np.abs(np.diff(means)).mean() / d2(2)
    n_bar = float(np.mean([len(g) for g in groups]))
    sigma = float(np.sqrt(sm ** 2 + (1 - 1 / n_bar) * sw ** 2))
    ni = np.array([len(g) for g in groups], dtype=float)
    x = np.concatenate(groups)
    big_n, a = (len(x), len(groups))
    gm = x.mean()
    sst = ((x - gm) ** 2).sum()
    ssb = (ni * (means - gm) ** 2).sum()
    msw, msb = ((sst - ssb) / (big_n - a), ssb / (a - 1))
    n0 = (big_n ** 2 - (ni ** 2).sum()) / ((a - 1) * big_n)
    s2 = ((n0 - 1) * msw + msb) / n0
    dof = s2 ** 2 / (msw ** 2 / (big_n - a) * ((n0 - 1) / n0) ** 2 + msb ** 2 / (a - 1) / n0 ** 2)
    return SigmaEstimate(sigma, 'between_within', float(dof))

