from __future__ import annotations
from dataclasses import dataclass
from typing import Sequence
import numpy as np
from ..constants import d2
from .tests import TestSpec, run_tests
from .variables import ChartPanel, _nan_list

@dataclass(frozen=True)
class AttributeOptions:
    k_sigma: float = 3.0
    historical: float | None = None
    tests: TestSpec = TestSpec()

@dataclass
class AttributeChartResult:
    center_value: float
    sigma_z: float | None
    panel: ChartPanel

def _arr(values: Sequence[float | None]) -> np.ndarray:
    return np.array([np.nan if v is None else v for v in values], dtype=float)

def _sizes(sizes, n_points: int) -> np.ndarray:
    if isinstance(sizes, (int, float, np.integer, np.floating)):
        return np.full(n_points, float(sizes))
    return _arr(sizes)

def _finish(name, pts, center, sd, opts: AttributeOptions, lo=0.0, hi=None) -> ChartPanel:
    half = opts.k_sigma * sd
    lcl = np.maximum(center - half, lo)
    ucl = center + half if hi is None else np.minimum(center + half, hi)
    spec = TestSpec(tuple((t for t in opts.tests.tests if t in (1, 2, 3, 4))), opts.tests.k)
    tests = run_tests(pts, center, sd, spec) if spec.tests else {}
    return ChartPanel(name, _nan_list(pts), _nan_list(center), _nan_list(lcl), _nan_list(ucl), tests)

def p_chart(defectives, sizes, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    d = _arr(defectives)
    n = _sizes(sizes, len(d))
    ok = np.isfinite(d) & np.isfinite(n) & (n > 0)
    pbar = opts.historical if opts.historical is not None else d[ok].sum() / n[ok].sum()
    p = np.where(ok, d / np.where(ok, n, 1), np.nan)
    sd = np.where(ok, np.sqrt(pbar * (1 - pbar) / np.where(ok, n, 1)), np.nan)
    return AttributeChartResult(pbar, None, _finish('P', p, np.full(len(d), pbar), sd, opts, 0.0, 1.0))

def np_chart(defectives, sizes, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    d = _arr(defectives)
    n = _sizes(sizes, len(d))
    ok = np.isfinite(d) & np.isfinite(n) & (n > 0)
    pbar = opts.historical if opts.historical is not None else d[ok].sum() / n[ok].sum()
    center = np.where(ok, n * pbar, np.nan)
    sd = np.where(ok, np.sqrt(n * pbar * (1 - pbar)), np.nan)
    panel = _finish('NP', np.where(ok, d, np.nan), center, sd, opts, 0.0, None)
    panel.ucl = [None if u is None else min(u, float(m)) for u, m in zip(panel.ucl, n)]
    return AttributeChartResult(pbar, None, panel)

def c_chart(defects, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    c = _arr(defects)
    ok = np.isfinite(c)
    cbar = opts.historical if opts.historical is not None else c[ok].mean()
    sd = np.where(ok, np.sqrt(cbar), np.nan)
    return AttributeChartResult(cbar, None, _finish('C', c, np.full(len(c), cbar), sd, opts))

def u_chart(defects, sizes, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    c = _arr(defects)
    n = _sizes(sizes, len(c))
    ok = np.isfinite(c) & np.isfinite(n) & (n > 0)
    ubar = opts.historical if opts.historical is not None else c[ok].sum() / n[ok].sum()
    u = np.where(ok, c / np.where(ok, n, 1), np.nan)
    sd = np.where(ok, np.sqrt(ubar / np.where(ok, n, 1)), np.nan)
    return AttributeChartResult(ubar, None, _finish('U', u, np.full(len(c), ubar), sd, opts))

def laney_p_chart(defectives, sizes, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    d = _arr(defectives)
    n = _sizes(sizes, len(d))
    ok = np.isfinite(d) & np.isfinite(n) & (n > 0)
    pbar = opts.historical if opts.historical is not None else d[ok].sum() / n[ok].sum()
    p = np.where(ok, d / np.where(ok, n, 1), np.nan)
    sd_i = np.where(ok, np.sqrt(pbar * (1 - pbar) / np.where(ok, n, 1)), np.nan)
    return _laney_from(p, np.full(len(d), pbar), sd_i, pbar, 'P′', opts, 1.0)

def laney_u_chart(defects, sizes, opts: AttributeOptions=AttributeOptions()) -> AttributeChartResult:
    c = _arr(defects)
    n = _sizes(sizes, len(c))
    ok = np.isfinite(c) & np.isfinite(n) & (n > 0)
    ubar = opts.historical if opts.historical is not None else c[ok].sum() / n[ok].sum()
    u = np.where(ok, c / np.where(ok, n, 1), np.nan)
    sd_i = np.where(ok, np.sqrt(ubar / np.where(ok, n, 1)), np.nan)
    return _laney_from(u, np.full(len(c), ubar), sd_i, ubar, 'U′', opts, None)

def _laney_from(pts, center, sd_i, value, name, opts, hi) -> AttributeChartResult:
    z = (pts - center) / sd_i
    mr = np.abs(np.diff(z))
    mr = mr[np.isfinite(mr)]
    sigma_z = float(mr.mean() / d2(2))
    panel = _finish(name, pts, center, sd_i * sigma_z, opts, 0.0, hi)
    return AttributeChartResult(value, sigma_z, panel)

