from __future__ import annotations
from dataclasses import dataclass
import numpy as np
DEFAULT_K = {1: 3.0, 2: 9, 3: 6, 4: 14, 5: 2, 6: 4, 7: 15, 8: 8}

@dataclass(frozen=True)
class TestSpec:
    tests: tuple[int, ...] = (1,)
    k: dict[int, float] | None = None

    def param(self, t: int) -> float:
        return (self.k or {}).get(t, DEFAULT_K[t])

def run_tests(points: np.ndarray, center: np.ndarray, sigma_pt: np.ndarray, spec: TestSpec) -> dict[int, list[int]]:
    z = (points - center) / sigma_pt
    x = points
    out: dict[int, list[int]] = {}
    for t in spec.tests:
        k = spec.param(t)
        out[t] = _TESTS[t](z, x, k)
    return out

def _t1(z, x, k):
    return [i for i, v in enumerate(z) if np.isfinite(v) and abs(v) > k]

def _t2(z, x, k):
    hits, run, side = ([], 0, 0)
    for i, v in enumerate(z):
        s = 0 if not np.isfinite(v) or v == 0 else 1 if v > 0 else -1
        run = run + 1 if s != 0 and s == side else 1 if s != 0 else 0
        side = s
        if run >= k:
            hits.append(i)
    return hits

def _t3(z, x, k):
    hits, run, direction = ([], 0, 0)
    for i in range(1, len(x)):
        a, b = (x[i - 1], x[i])
        d = 0 if not (np.isfinite(a) and np.isfinite(b)) or a == b else 1 if b > a else -1
        if d != 0 and d == direction:
            run += 1
        else:
            run = 1 if d != 0 else 0
        direction = d
        if run >= k:
            hits.append(i)
    return hits

def _t4(z, x, k):
    hits, run, prev_d = ([], 0, 0)
    for i in range(1, len(x)):
        a, b = (x[i - 1], x[i])
        d = 0 if not (np.isfinite(a) and np.isfinite(b)) or a == b else 1 if b > a else -1
        if d != 0 and prev_d != 0 and (d == -prev_d):
            run += 1
        else:
            run = 1 if d != 0 else 0
        prev_d = d
        if run >= k:
            hits.append(i)
    return hits

def _k_of_k1(z, k, limit):
    k = int(k)
    hits = []
    for i in range(len(z)):
        if not np.isfinite(z[i]) or abs(z[i]) <= limit:
            continue
        side = 1 if z[i] > 0 else -1
        window = z[max(0, i - k):i + 1]
        if np.count_nonzero(np.isfinite(window) & (side * window > limit)) >= k:
            hits.append(i)
    return hits

def _t5(z, x, k):
    return _k_of_k1(z, k, 2.0)

def _t6(z, x, k):
    return _k_of_k1(z, k, 1.0)

def _t7(z, x, k):
    hits, run = ([], 0)
    for i, v in enumerate(z):
        run = run + 1 if np.isfinite(v) and abs(v) < 1.0 else 0
        if run >= k:
            hits.append(i)
    return hits

def _t8(z, x, k):
    hits, run = ([], 0)
    for i, v in enumerate(z):
        run = run + 1 if np.isfinite(v) and abs(v) > 1.0 else 0
        if run >= k:
            hits.append(i)
    return hits
_TESTS = {1: _t1, 2: _t2, 3: _t3, 4: _t4, 5: _t5, 6: _t6, 7: _t7, 8: _t8}

