from __future__ import annotations
from dataclasses import dataclass, field
from typing import Sequence
import numpy as np
from ..constants import c4, d2, d3
from ..sigma import SigmaEstimate, WithinMethod, moving_ranges, split_subgroups, within_sigma
from .tests import TestSpec, run_tests

@dataclass
class ChartPanel:
    name: str
    points: list[float | None]
    center: list[float | None]
    lcl: list[float | None]
    ucl: list[float | None]
    tests: dict[int, list[int]] = field(default_factory=dict)

@dataclass
class VariablesChartResult:
    mean: float
    sigma: SigmaEstimate
    subgroup_sizes: list[int]
    panels: list[ChartPanel]

@dataclass(frozen=True)
class ChartOptions:
    sigma_method: WithinMethod | None = None
    unbiased: bool = True
    mr_span: int = 2
    k_sigma: float = 3.0
    historical_mean: float | None = None
    historical_sigma: float | None = None
    tests: TestSpec = TestSpec()

def _nan_list(a: np.ndarray) -> list[float | None]:
    return [None if not np.isfinite(v) else float(v) for v in a]

def _location(values: np.ndarray, opts: ChartOptions) -> float:
    if opts.historical_mean is not None:
        return opts.historical_mean
    x = values[np.isfinite(values)]
    return float(x.mean())

def _sigma(values, subgroup, opts: ChartOptions, default: WithinMethod) -> SigmaEstimate:
    if opts.historical_sigma is not None:
        return SigmaEstimate(opts.historical_sigma, 'historical', float('inf'))
    return within_sigma(values, subgroup, opts.sigma_method or default, opts.unbiased, opts.mr_span)

def _panel(name, points, center, half_width, sd_point, opts: ChartOptions, allowed_tests, floor_zero=False) -> ChartPanel:
    lcl = center - half_width
    if floor_zero:
        lcl = np.maximum(lcl, 0.0)
    ucl = center + half_width
    spec = TestSpec(tuple((t for t in opts.tests.tests if t in allowed_tests)), opts.tests.k)
    tests = run_tests(points, center, sd_point, spec) if spec.tests else {}
    return ChartPanel(name, _nan_list(points), _nan_list(center), _nan_list(lcl), _nan_list(ucl), tests)

def _xbar_panel(groups, mu, sigma, opts) -> ChartPanel:
    n = np.array([len(g) for g in groups], dtype=float)
    pts = np.array([g.mean() if len(g) else np.nan for g in groups])
    sd = np.where(n > 0, sigma / np.sqrt(np.maximum(n, 1)), np.nan)
    center = np.full(len(groups), mu)
    return _panel('Xbar', pts, center, opts.k_sigma * sd, sd, opts, range(1, 9))

def _range_panel(groups, sigma, opts) -> ChartPanel:
    n = [len(g) for g in groups]
    pts = np.array([g.max() - g.min() if len(g) >= 2 else np.nan for g in groups])
    center = np.array([d2(m) * sigma if m >= 2 else np.nan for m in n])
    sd = np.array([d3(m) * sigma if m >= 2 else np.nan for m in n])
    return _panel('R', pts, center, opts.k_sigma * sd, sd, opts, range(1, 5), floor_zero=True)

def _s_panel(groups, sigma, opts) -> ChartPanel:
    n = [len(g) for g in groups]
    pts = np.array([g.std(ddof=1) if len(g) >= 2 else np.nan for g in groups])
    center = np.array([c4(m) * sigma if m >= 2 else np.nan for m in n])
    sd = np.array([np.sqrt(1 - c4(m) ** 2) * sigma if m >= 2 else np.nan for m in n])
    return _panel('S', pts, center, opts.k_sigma * sd, sd, opts, range(1, 5), floor_zero=True)

def _subgroup_chart(values, subgroup, opts: ChartOptions, default_method: WithinMethod, second: str | None) -> VariablesChartResult:
    values = np.array([np.nan if v is None else v for v in values], dtype=float)
    groups = split_subgroups(values, subgroup)
    mu = _location(values, opts)
    sig = _sigma(values, subgroup, opts, default_method)
    panels = [_xbar_panel(groups, mu, sig.value, opts)]
    if second == 'R':
        panels.append(_range_panel(groups, sig.value, opts))
    elif second == 'S':
        panels.append(_s_panel(groups, sig.value, opts))
    return VariablesChartResult(mu, sig, [len(g) for g in groups], panels)

def xbar_r_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()):
    return _subgroup_chart(values, subgroup, opts, WithinMethod.RBAR, 'R')

def xbar_s_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()):
    return _subgroup_chart(values, subgroup, opts, WithinMethod.SBAR, 'S')

def xbar_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()):
    return _subgroup_chart(values, subgroup, opts, WithinMethod.POOLED, None)

def _individuals(values, opts: ChartOptions, with_mr: bool, with_i: bool=True) -> VariablesChartResult:
    x = np.array([np.nan if v is None else v for v in values], dtype=float)
    mu = _location(x, opts)
    sig = _sigma(x, 1, opts, WithinMethod.AVG_MR)
    panels = []
    if with_i:
        sd = np.where(np.isfinite(x), sig.value, np.nan)
        panels.append(_panel('I', x, np.full(len(x), mu), opts.k_sigma * sd, sd, opts, range(1, 9)))
    if with_mr:
        w = opts.mr_span
        mr = np.full(len(x), np.nan)
        if len(x) >= w:
            win = np.lib.stride_tricks.sliding_window_view(x, w)
            mr[w - 1:] = win.max(axis=1) - win.min(axis=1)
        center = np.full(len(x), d2(w) * sig.value)
        sd = np.full(len(x), d3(w) * sig.value)
        panels.append(_panel('MR', mr, center, opts.k_sigma * sd, sd, opts, range(1, 5), floor_zero=True))
    return VariablesChartResult(mu, sig, [1] * len(x), panels)

def i_mr_chart(values: Sequence[float | None], opts: ChartOptions=ChartOptions()):
    return _individuals(values, opts, with_mr=True)

def i_chart(values: Sequence[float | None], opts: ChartOptions=ChartOptions()):
    return _individuals(values, opts, with_mr=False)

def mr_chart(values: Sequence[float | None], opts: ChartOptions=ChartOptions()):
    return _individuals(values, opts, with_mr=True, with_i=False)

def r_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()):
    r = _subgroup_chart(values, subgroup, opts, WithinMethod.RBAR, 'R')
    return VariablesChartResult(r.mean, r.sigma, r.subgroup_sizes, r.panels[1:])

def s_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()):
    r = _subgroup_chart(values, subgroup, opts, WithinMethod.SBAR, 'S')
    return VariablesChartResult(r.mean, r.sigma, r.subgroup_sizes, r.panels[1:])
__all__ = ['between_within_chart', 'BetweenWithinResult', 'ChartOptions', 'ChartPanel', 'VariablesChartResult', 'xbar_r_chart', 'xbar_s_chart', 'xbar_chart', 'r_chart', 's_chart', 'i_mr_chart', 'i_chart', 'mr_chart', 'moving_ranges']

@dataclass
class BetweenWithinResult:
    mean: float
    sigma_means: float
    sigma_between: float
    sigma_within: float
    sigma_total: float
    panels: list[ChartPanel]

def between_within_chart(values: Sequence[float | None], subgroup, opts: ChartOptions=ChartOptions()) -> BetweenWithinResult:
    x = np.array([np.nan if v is None else v for v in values], dtype=float)
    groups = split_subgroups(x, subgroup)
    sig_w = _sigma(x, subgroup, opts, WithinMethod.RBAR)
    means = np.array([g.mean() for g in groups])
    sizes = np.array([len(g) for g in groups], dtype=float)
    mu = _location(x, opts)
    mr = np.r_[np.nan, np.abs(np.diff(means))]
    sig_m = float(np.nanmean(mr) / d2(2))
    n_bar = float(np.mean(sizes))
    sig_b = float(np.sqrt(max(sig_m ** 2 - sig_w.value ** 2 / n_bar, 0.0)))
    k = opts.k_sigma
    n = len(groups)
    i_panel = _panel('I', means, np.full(n, mu), np.full(n, k * sig_m), np.full(n, sig_m), opts, range(1, 9))
    mr_center = np.full(n, d2(2) * sig_m)
    mr_panel = _panel('MR', mr, mr_center, np.full(n, k * d3(2) * sig_m), np.full(n, d3(2) * sig_m), opts, range(1, 5), floor_zero=True)
    r_panel = _range_panel(groups, sig_w.value, opts)
    return BetweenWithinResult(mu, sig_m, sig_b, sig_w.value, float(np.hypot(sig_b, sig_w.value)), [i_panel, mr_panel, r_panel])

