from __future__ import annotations
import math
from dataclasses import dataclass
import numpy as np
from scipy import integrate, optimize, stats

def k_one_sided(n: int, coverage: float, confidence: float) -> float:
    delta = stats.norm.ppf(coverage) * math.sqrt(n)
    return float(stats.nct.ppf(confidence, n - 1, delta) / math.sqrt(n))

def _two_sided_confidence(k: float, n: int, coverage: float) -> float:

    def f(z):
        q = stats.ncx2.ppf(coverage, 1, z * z) if z > 0 else stats.chi2.ppf(coverage, 1)
        return math.exp(-n * z * z / 2) * stats.chi2.sf((n - 1) * q / k ** 2, n - 1)
    upper = 12 / math.sqrt(n)
    val, _ = integrate.quad(f, 0, upper, epsabs=1e-13, epsrel=1e-11, limit=200)
    return math.sqrt(2 * n / math.pi) * val

def k_two_sided(n: int, coverage: float, confidence: float) -> float:
    k_lo = stats.norm.ppf((1 + coverage) / 2)
    f = lambda k: _two_sided_confidence(k, n, coverage) - confidence
    howe = k_lo * math.sqrt((n - 1) * (1 + 1 / n) / stats.chi2.ppf(1 - confidence, n - 1))
    a, b = (max(k_lo * 0.999, howe * 0.97), howe * 1.03)
    if f(a) < 0 < f(b):
        return float(optimize.brentq(f, a, b, xtol=1e-12))
    return float(optimize.brentq(f, k_lo * 0.999, 50, xtol=1e-12))

@dataclass
class ToleranceResult:
    n: int
    mean: float
    stdev: float
    k: float | None
    normal: tuple[float | None, float | None]
    nonparametric: tuple[float | None, float | None]
    achieved_confidence: float

def _nonparametric(xs: np.ndarray, coverage: float, confidence: float, sides: str):
    n = len(xs)
    if sides == 'two':
        best = (1, stats.binom.cdf(n - 2, n, coverage))
        for r in range(1, n // 2 + 1):
            conf = stats.binom.cdf(n - 2 * r, n, coverage)
            if conf >= confidence:
                best = (r, conf)
            else:
                break
        r, conf = best
        return ((float(xs[r - 1]), float(xs[n - r])), float(conf))
    best = (1, stats.binom.cdf(n - 1, n, coverage))
    for r in range(1, n + 1):
        conf = stats.binom.cdf(n - r, n, coverage)
        if conf >= confidence:
            best = (r, conf)
        else:
            break
    r, conf = best
    lo, hi = (float(xs[r - 1]), float(xs[n - r]))
    return ((lo, None) if sides == 'lower' else (None, hi), float(conf))

def tolerance_interval(values, coverage: float=0.99, confidence: float=0.95, sides: str='two') -> ToleranceResult:
    x = np.array([v for v in values if v is not None and np.isfinite(v)], dtype=float)
    n = len(x)
    m, s = (float(x.mean()), float(x.std(ddof=1)))
    if sides == 'two':
        k = k_two_sided(n, coverage, confidence)
        normal = (m - k * s, m + k * s)
    else:
        k = k_one_sided(n, coverage, confidence)
        normal = (m - k * s, None) if sides == 'lower' else (None, m + k * s)
    npar, conf = _nonparametric(np.sort(x), coverage, confidence, sides)
    return ToleranceResult(n, m, s, k, normal, npar, conf)

def sample_size_tolerance(coverage: float=0.95, max_coverage: float=0.97, confidence: float=0.95, error_prob: float=0.05, sides: str='two', n_max: int=100000) -> dict:
    if not 0 < coverage < max_coverage < 1:
        raise ValueError('0 < P < P* < 1 olmalı.')

    def normal_err(n):
        if sides == 'two':
            return _two_sided_confidence(k_two_sided(n, coverage, confidence), n, max_coverage)
        k = k_one_sided(n, coverage, confidence)
        delta = stats.norm.ppf(max_coverage) * math.sqrt(n)
        return float(stats.nct.cdf(k * math.sqrt(n), n - 1, delta))
    lo, hi = (2, 4)
    while normal_err(hi) > error_prob:
        lo, hi = (hi, hi * 2)
        if hi > n_max:
            raise ValueError('Örneklem büyüklüğü sınırı aşıldı.')
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if normal_err(mid) <= error_prob:
            hi = mid
        else:
            lo = mid
    n_norm = hi

    def np_best(n):
        m_lo = 2 if sides == 'two' else 1
        q = int(stats.binom.ppf(confidence, n, coverage))
        while q > 0 and stats.binom.cdf(q - 1, n, coverage) >= confidence:
            q -= 1
        while stats.binom.cdf(q, n, coverage) < confidence:
            q += 1
        m = n - q
        if m < m_lo:
            return None
        return (m, float(stats.binom.cdf(n - m, n, coverage)), float(stats.binom.cdf(n - m, n, max_coverage)))
    n = max(2, n_norm // 2)
    while True:
        b = np_best(n)
        if b and b[2] <= error_prob:
            break
        n += 1
        if n > n_max:
            raise ValueError('Örneklem büyüklüğü sınırı aşıldı.')
    return {'coverage': coverage, 'max_coverage': max_coverage, 'confidence': confidence, 'error_prob': error_prob, 'normal_n': n_norm, 'normal_error': float(normal_err(n_norm)), 'nonparametric_n': n, 'order_stats_removed': b[0], 'achieved_confidence': b[1], 'achieved_error': b[2]}

