from __future__ import annotations
import hashlib
import json
import os
import time
import urllib.error
import urllib.request
from pathlib import Path
from fastapi import FastAPI, Request
from fastapi.responses import FileResponse, JSONResponse
OPEN_PATHS = {'/api/health', '/api/public-config'}
_CACHE_SECONDS = 300
_cache: dict[str, tuple[float, str]] = {}

def supabase_settings() -> tuple[str | None, str | None]:
    url = (os.environ.get('SUPABASE_URL') or '').strip().rstrip('/') or None
    key = (os.environ.get('SUPABASE_ANON_KEY') or '').strip() or None
    return (url, key)

def allowed(who: str) -> bool:
    raw = (os.environ.get('QUALISTAT_ALLOWED') or '').strip()
    if not raw:
        return True
    who = who.strip().lower()
    for item in (x.strip().lower() for x in raw.split(',')):
        if item and (who == item or (item.startswith('@') and who.endswith(item))):
            return True
    return False

def _verify(token: str, url: str, key: str) -> str | None:
    h = hashlib.sha256(token.encode()).hexdigest()
    now = time.time()
    hit = _cache.get(h)
    if hit and hit[0] > now:
        return hit[1]
    req = urllib.request.Request(f'{url}/auth/v1/user', headers={'apikey': key, 'Authorization': f'Bearer {token}'})
    try:
        with urllib.request.urlopen(req, timeout=8) as res:
            user = json.loads(res.read().decode('utf-8'))
    except (urllib.error.URLError, TimeoutError, ValueError):
        return None
    who = user.get('email') or user.get('id')
    if not who:
        return None
    if len(_cache) > 2000:
        _cache.clear()
    _cache[h] = (now + _CACHE_SECONDS, who)
    return who

def install(app: FastAPI) -> None:

    @app.get('/api/public-config')
    def public_config() -> dict:
        url, key = supabase_settings()
        return {'supabaseUrl': url, 'anonKey': key} if url and key else {'supabaseUrl': None, 'anonKey': None}

    @app.get('/api/whoami')
    def whoami(request: Request) -> dict:
        return {'user': getattr(request.state, 'user', None)}

    @app.middleware('http')
    async def require_session(request: Request, call_next):
        url, key = supabase_settings()
        path = request.url.path
        if url and key and path.startswith('/api/') and (path not in OPEN_PATHS) and (request.method != 'OPTIONS'):
            auth = request.headers.get('authorization', '')
            token = auth[7:].strip() if auth.lower().startswith('bearer ') else ''
            who = _verify(token, url, key) if token else None
            if not who:
                return JSONResponse({'detail': 'Oturum gerekli: lütfen yeniden giriş yapın.'}, status_code=401)
            if not allowed(who):
                return JSONResponse({'detail': f"{who} hesabının QualiStat'ı kullanma izni yok. Yöneticinize başvurun."}, status_code=403)
            request.state.user = who
        return await call_next(request)
    here = Path(__file__).resolve().parents
    default = here[3] / 'frontend' / 'dist' if len(here) > 3 else None
    static = Path(os.environ['QUALISTAT_STATIC']) if os.environ.get('QUALISTAT_STATIC') else default
    if static is not None and static.is_dir() and (static / 'index.html').is_file():
        root = static.resolve()

        @app.get('/{rest:path}', include_in_schema=False)
        def spa(rest: str):
            if rest.startswith('api/'):
                return JSONResponse({'detail': 'Not Found'}, status_code=404)
            target = (root / rest).resolve()
            if rest and target.is_file() and (root in target.parents):
                return FileResponse(target)
            return FileResponse(root / 'index.html')
